window.__LEX={"G4000":"<h1>pentakischilioi</h1>\n<p>Strong n° 4000 <i>Prononciation [pen-tak-is-khil'-ee-oy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cinq mille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεντακισ·χίλιοι, αι, α</b> <span>[ᾰχῑ]</span> cinq mille, HDT. <i>1, 194 ;</i> PLAT. <i>Leg. 738</i> a ; <i>sg</i>. πεντακισχιλία ἀσπίς, LUC. <i>D. mer. 9, 4,</i> troupe de 5 000 boucliers ; ἵππος, SPT. <i>1Macc. 4, 28,</i> troupe de 5 000 cavaliers.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντακισχιλιοι - πεντακισχίλιοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4001":"<h1>pentakosioi</h1>\n<p>Strong n° 4001 <i>Prononciation [pen-tak-os'-ee-oy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cinq cents</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεντακόσιοι, αι, α</b> <span>[ᾰ]</span> cinq cents, OD. <i>3, 7 ;</i> HDT. <i>1, 7 ; sg</i>. πεντακοσία ἵππος, LGS <i>3, 1,</i> troupe de 500 cavaliers ; οἱ π. PLUT. <i>Cim. 17,</i> le Conseil des Cinq Cents.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πεντηκόσιοι, HDT. <i>l. c</i>.<br><span><b>Étym</b>. πέντε, -κόσιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντακοσιοι - πεντακόσιοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4002":"<h1>pente</h1>\n<p>Strong n° 4002 <i>Prononciation [pen'-teh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>cinq</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέντε (οἱ, αἱ, τὰ)</b> <i>n. de n. indécl.,</i> cinq, HOM. ATT. <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. πέμπε, Ps.-HDT. <i>V. Hom. 37 ; gén</i>. πέμπων, ALC. <i>33, 7</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *pénk<sup>w</sup>e ; <i>cf. lat</i>. quīnque, <i>sscr</i>. páñca, <i>gotique</i> fimf.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντε - πέντε</font>\n<br><br>un nombre primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom indéclinable</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n38 fois dans 33 versets de 7 livres bibliques (NT\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (3)</li>\n<li>Luc (9)</li>\n<li>Jean (5)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4003":"<h1>pentekaidekatos</h1>\n<p>Strong n° 4003 <i>Prononciation [pen-tek-ahee-ded'-at-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>la quinzième</td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεντε·και·δέκατος, η, ον</b> <span>[ᾰ]</span> quinzième, DS. <i>12, 81</i>.<br><span><b>Étym</b>. π. κ. δέκατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντεκαιδεκατος - πεντεκαιδέκατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4004":"<h1>pentekonta</h1>\n<p>Strong n° 4004 <i>Prononciation [pen-tay'-kon-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cinquante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεντήκοντα (οἱ, αἱ, τά)</b> <i>indécl</i>. cinquante, IL. <i>2, 509, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. πεντείκοντα, CORINN. <i>fr. 13 Bgk</i>.<br><span><b>Étym</b>. πέντε, -κοντα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντηκοντα - πεντήκοντα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4005":"<h1>pentekoste</h1>\n<p>Strong n° 4005 <i>Prononciation [pen-tay-kos-tay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pentecôte (Angl. Pentecost) = « le cinquantième jour »\n<ol><li>la seconde des trois grandes fêtes Juives, célébrée annuellement à Jérusalem, la septième semaine après la Pâque, dans la gratitude reconnaissante de la moisson accomplie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεντηκοστη - πεντηκοστή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4006":"<h1>pepoithesis</h1>\n<p>Strong n° 4006 <i>Prononciation [pep-oy'-thay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>confiance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πεποίθησις, εως (ἡ)</b> confiance, assurance, PHIL. <i>2, 444 ;</i> SPT. <i>Gen. 34, 25 ;</i> NT. <i>Eph. 3, 12, etc. ; plur</i>. BABR. <i>43, 19</i>.<br><span><b>Étym</b>. πέποιθα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πεποιθησις - πεποίθησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4007":"<h1>per</h1>\n<p>Strong n° 4007 <i>Prononciation [per]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>si ...que, beaucoup, quiconque, tout à fait, en effet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πέρ</b>, <i>enclit</i>. <b>περ</b>, <i>particule adv. :</i><br><b>   I</b> certes, tout à fait, <i>joint à des adj., à des adv., à des part., qqf. à des subst. :</i> ἐγὼ δ' ἐλεεινότερός περ, IL. <i>24, 504,</i> je suis certes plus à plaindre (que ton père) ; μίνυνθά περ, IL. <i>13, 573 ; 23, 97,</i> un moment tout à fait court ; ἐπεί μ' ἔτεκές γε μινυνθάδιόν περ ἐόντα, IL. <i>1, 352,</i> comme je suis né de toi pour une existence tout à fait courte ; ὀλίγον περ, IL. <i>11, 391 ;</i> OD. <i>8, 187,</i> très peu ; πρῶτόν περ, IL. <i>14, 295,</i> tout à fait pour la première fois ; ὑστάτιόν περ, IL. <i>8, 353,</i> du moins dans la dernière extrémité ; ὡς τὸ πάρος περ, IL. <i>5, 806,</i> tout à fait comme auparavant ; νόον πύκα περ φρονεόντων, IL. <i>14, 217,</i> l’intelligence de gens tout à fait avisés ; γεινόμενόν περ, IL. <i>23, 79,</i> au moment même de la naissance ;<br><b>   II</b> et certes, et cependant, quoique : τά τε στυγέουσι θεοί περ, IL. <i>20, 65,</i> devant quoi les dieux eux-mêmes (<i>litt</i>. et cependant ce sont des dieux) éprouvent le frisson ; <i>après une nég. :</i> οὐδ' ὑμῖν ποταμός περ ἐΰρροος ἀρκέσει, IL. <i>21, 130,</i> non, le fleuve, même avec son courant rapide, ne vous protégera pas ; <i>cf</i>. OD. <i>1, 59 ; 11, 441, etc. ; particul. avec le part</i>. ὤν, <i>épq</i>. ἐών : ἀγαθός περ ἐών, IL. <i>1, 131, 275,</i> quoique tu sois brave, si brave que tu sois ; κρατερός περ ἐών, IL. <i>15, 164, 195,</i> bien que fort ; μέγαν περ ἐόντα, IL. <i>5, 625,</i> bien que grand ; πολέες περ ἐόντες, IL. <i>5, 94,</i> bien que nombreux ; γενναῖός περ ὤν, SOPH. <i>Ph. 1058,</i> bien que généreux ; γυνή περ οὖσα, ESCHL. <i>Sept. 1029,</i> bien que femme ; <i>sans le participe :</i> φράδμων περ ἀνήρ, IL. <i>16, 638,</i> un homme, même habile connaisseur ; <i>avec</i> καί : καὶ κρατερός περ ἐών, IL. <i>16, 624,</i> même, bien que fort ; <i>cf</i>. IL. <i>16, 617, 620 ;</i> ESCHL. <i>Ag. 1176, etc. ; de même avec un partic. :</i> ἀχνύμενός περ, ἱέμενός περ, οὐτάμενός περ, <i>etc</i>. HOM. bien qu’affligé, bien que le désirant, bien que blessé, <i>etc. ;</i><br><b>   III</b> en tout cas, du moins : τόδε πέρ μοι ἐπικρήηνον ἐέλδωρ, αὐτοὺς δή περ ἔασον ὑπεκφυγέειν, IL. <i>8, 242,</i> ce souhait du moins, accorde-le-moi, laisse-nous en tout cas échapper ; <i>particul. après un membre de phrase marquant une supposition :</i> εἰ δέ τοι Ἀτρείδης μὲν ἀπήχθετο…, σὺ δ' ἄλλους περ ἐλέαιρε, IL. <i>9, 301,</i> si l’Atride haïssait, toi du moins aie pitié des autres ; <i>cf</i>. IL. <i>12, 349, 362 ;</i><br><b>   IV</b> <i>en un sens indéterminé,</i> au reste, d’ailleurs, en général :<br><b>      1</b> <i>après une conj. conditionnelle :</i> εἴπερ, ἐάνπερ, si d’ailleurs, si même, <i>etc</i>. IL. <i>4, 55 ; 7, 117 ; 16, 263 ;</i> OD. <i>1, 167, etc. ; de même</i> εἴπερ καί, OD. <i>9, 35 ;</i> εἴπερ τε, IL. <i>10, 225 ;</i> OD. <i>1, 204 ;</i> ἐάνπερ, SOPH. <i>O.C. 1212, etc. ;</i><br><b>      2</b> <i>après une particule de temps :</i> ὅτε πέρ, à l’époque même où, quand précisément, IL. <i>4, 259 ; 5, 802 ; 14, 319, 323, etc. ;</i> HDT. <i>5, 99, etc. ;</i> ὅτε πέρ τε, IL. <i>10, 7,</i> justement aussi quand ; ἦμός περ, IL. <i>11, 86 ;</i> ὅτανπερ, SOPH. <i>Ph. 756, O.C. 302, etc. m. sign. ; ou une particule de cause :</i> ἐπείπερ, ἐπειδήπερ, ATT. puisque précisément ; διότι περ, HDT. <i>4, 186,</i> justement par cette raison que ;<br><b>      3</b> <i>après un pronom ou un adv. relatif :</i> ὅσπερ, ἥπερ, ὅπερ, qui justement, précisément qui, qui certes pourtant, IL. <i>6, 100, 398 ; 2, 805, etc. ;</i> ATT. ; <i>qqf. séparé du pronom :</i> IL. <i>4, 524, etc. ;</i> οἷός περ <i>ou</i> οἷόσπερ, tout à fait <i>ou</i> précisément comme, IL. <i>6, 146 ; 16, 557, etc. ;</i> ATT. ; ὅσος περ <i>ou</i> ὅσοσπερ, justement combien grand, précisément combien grand, HDT. <i>2, 170 ; 4, 40 ; 5, 106, etc. ;</i> ATT. ; ἔνθα περ <i>ou</i> ἔνθαπερ, où justement, où certes, IL. <i>6, 379, 384, etc. ;</i> ATT. ; ὅθι περ, où justement, où toujours, IL. <i>2, 861 ; 10, 568 ;</i> οὗπερ, SOPH. <i>O.C. 77, 357, etc. m. sign. ;</i> ὅθεν περ, de là justement d’où, SOPH. <i>O.R. 1498, O.C. 1229, etc. ;</i> ὥσπερ ;<br><b>      4</b> <i>après la particule de comparaison</i> ἤ, <i>épq</i>. ἠέ : ἤπερ, que même, IL. <i>14, 468 ;</i> OD. <i>4, 819 ; 8, 154 ;</i> HDT. <i>4, 50 ; 9, 26 ;</i> ἠέπερ, IL. <i>1, 260 ; 10, 556 ; 16, 688 ;</i> OD. <i>17, 417</i>.<br><span><b><span class=\"arrow\"></span></b> <i>L’usage primaire de</i> περ <i>posthomérique limite le domaine d’application d’un énoncé à</i> « précisément et uniquement » ; <i>il se situe entre</i> γε, <i>qui le limite à</i> « du moins » <i>et</i> καί <i>adverbial</i> « aussi », <i>qui est additif</i>.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *per, traversant, <i>v</i>. περί ; <i>cf. lat</i>. -per <i>dans</i> nuper, parumper, <i>etc</i>.</span><br><br>\n➁ <b>περ'</b>, <i>élis. p</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περ - περ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G4008":"<h1>peran</h1>\n<p>Strong n° 4008 <i>Prononciation [per'-an]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>au delà, de l'autre côté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>περᾶν</b>, <i>inf. de</i> περάω.<br><br>\n<b>περάω-ῶ</b> <span>(<i>f</i>. -άσω, <i>ao</i>. ἐπέρασα <span>[ᾱσ]</span>, <i>pf</i>. πεπέρακα <span>[ρᾱ]</span>)</span><br><b>   I <i>intr</i>.<br>      1</b> passer à travers, traverser, <i>avec une prép. :</i> δι' Ὠκεανοῖο, OD. <i>10, 508 ; 11, 158,</i> traverser l’Océan ; διὰ πόρον, ESCHL. <i>Pers. 501,</i> traverser un passage ; <i>avec un suj. de chose</i> (arme, IL. <i>21, 594 ;</i> pluie, OD. <i>5, 480, etc</i>.) ; διὰ κροτάφοιο, IL. <i>4, 502,</i> pénétrer à travers la tempe ; ὀστέον εἴσω, IL. <i>4, 460, etc</i>. en dedans de l’os ;<br><b>      2</b> <i>p. ext</i>. aller, s’avancer : ἐπὶ πόντον, IL. <i>2, 613,</i> sur la mer ; εἰς χώραν, ESCHL. <i>Pers. 65,</i> pénétrer dans un pays ; δόμων ἔσω, EUR. <i>Or. 1572,</i> aller dans une maison ; δωμάτων ἔξω, SOPH. <i>O.R. 531,</i> sortir d’une maison ; <i>avec un acc</i>. δόμους, EUR. <i>Hipp. 782,</i> aller dans une maison ; Δελφούς, EUR. <i>Ph. 980,</i> aller à Delphes ; <i>fig. avec un gén</i>. θυμοῦ, SOPH. <i>O.R. 674, litt</i>. aller au delà du terme de la colère, <i>càd</i>. se calmer dans sa colère ; <i>avec une prép</i>. π. νόημα διὰ στέρνοιο, HH. <i>Merc. 43,</i> la pensée pénètre à travers la poitrine ;<br><b>   II <i>tr</i>.<br>      1</b> traverser : θάλασσαν, OD. <i>6, 272, etc. ; ou</i> πόντον, OD. <i>24, 118 ;</i> PD. <i>P. 3, 136 ;</i> XÉN. <i>Œc. 20, 27, etc</i>. traverser la mer ; <i>fig</i>. βίον, ORACL. (XÉN. <i>Cyr. 7, 2, 20</i>) mourir, <i>propr</i>. mener la vie jusqu’au terme ; τέλος, PD. <i>N. 11, 11,</i> traverser une charge, <i>càd</i>. l’exercer jusqu’au terme fixé ;<br><b>      2</b> <i>p. suite,</i> franchir, dépasser : γῆς ὁρίσματα, EUR. <i>Rhes. 437,</i> les limites de la terre ; τάφρους, XÉN. <i>Hipp. 6, 5,</i> franchir des fossés ; τάφρος περῆσαι οὐ ῥηϊδίη, IL. <i>12, 53,</i> fossé difficile à franchir ; <i>fig</i>. π. τὴν ἡϐητικὴν ἡλικίαν, XÉN. <i>Lac. 4, 7,</i> dépasser l’âge de la jeunesse ; τέρμα τοῦ βίου, SOPH. <i>O.R. 1530,</i> franchir le terme de la vie, mourir ; <i>p. anal</i>. ὅρκον, ESCHL. <i>Eum. 489,</i> violer (<i>propr</i>. transgresser) un serment ; θέμιν, ESCHL. <i>fr. 268, 2 Dind</i>. violer la justice ; <i>abs</i>. aller trop loin, SOPH. <i>O.C. 155 ;</i> s’étendre plus loin, XÉN. <i>Cyr. 8, 5 ;</i><br><b>      3</b> faire passer à travers : π. κατὰ δειρῆς, HH. <i>Merc. 133,</i> faire descendre (des aliments) à travers la gorge, <i>càd</i>. manger ;<br><b><i>Moy.</i></b> (<i>3 pl. impf. épq</i>. περόωντο) passer à travers, traverser, OPP. <i>C. 6, 261</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. épq</i>. περόωσι, OD. <i>4, 709 ; 6, 273 ; inf. épq</i>. περάαν, IL. <i>2, 613 ; 12, 63. Impf. itér. 3 sg</i>. περάασκε, OD. <i>5, 480 ; 19, 442 ;</i> OPP. <i>H. 5, 450. Ao. part. dor</i>. περάσαις, PD. <i>P. 3, 76. Conjug. ion. en</i> η : <i>f</i>. περήσω, IL. <i>5, 646, etc., d’où inf. épq</i>. περησέμεναι, IL. <i>12, 200, 218. Impf. moy. 3 pl. épq</i>. περόωντο, OPP. <i>C. 2, 623</i>.<br><span><b>Étym</b>. πέρα².</span><br><br>\n<b>*περάω-ῶ</b>, <i>à cause des homonymes avec</i> περάω¹ (περάαν, ἐπέρασα, <i>etc.) posé par erreur p</i>. πέρνημι.<br><br>\n<b>περάω-ῶ</b>, <i>att. c</i>. περάσω, <i>fut. de</i> πέρνημι.<br><br>\n<b>πέρνημι</b> <span>(<i>f</i>. περάω, <i>att</i>. περῶ, <i>ao</i>. ἐπέρασα <span>[ᾰσ]</span>, <i>pf. inus. ; autres formes de</i> πιπράσκω)</span> exporter et vendre, vendre, <i>particul. du commerce des hommes ou des esclaves, acc</i>. IL. <i>21, 102 ; 22, 45 ; 24, 752 ;</i> OD. <i>14, 297, etc. ;</i> HH. <i>Cer. 132 ;</i> THGN. <i>1215 ;</i> τινα Λῆμνον, IL. <i>21, 40 ; ou</i> τινα ἐς Λῆμνον, IL. <i>21, 58, 78 ; ou</i> τινα πρὸς δώματα, OD. <i>15, 387 ;</i> τινα ἐπὶ νήσων, IL. <i>21, 454,</i> vendre qqn pour aller à Lemnos, dans la demeure de, dans des îles, <i>etc. ;</i> τινα κατ' ἀλλοθρόους ἀνθρώπους, OD. <i>15, 453,</i> aller vendre qqn parmi des hommes au langage étranger ; <i>en gén. des marchandises,</i> HIPPON. <i>fr. 52 ;</i> EUR. <i>Cycl. 270 etc. ; au pass</i>. être vendu : κτήματα περνάμενα, IL. <i>18, 292,</i> denrées, marchandises.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. 3 pl</i>. περνᾶσι, THGN. <i>1215 ; part</i>. περνάς, IL. <i>22, 45, etc. ; impf. itér. 3 sg</i>. πέρνασκε, IL. <i>24, 752. Fut. inf. épq</i>. περάαν <span>[ᾰᾱ]</span> (<i>p</i>. περάσειν) IL. <i>21, 454. Ao. épq</i>. ἐπέρασσα, IL. <i>21, 40, 78, ou</i> πέρασσα, IL. <i>21, 102 ;</i> OD. <i>15, 387 ; part. pf. pass. ion</i>. πεπερημένος, IL. <i>21, 58</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *perh₂-, vendre ; <i>cf</i>. πιπράσκω, πόρνη ; <i>v</i>. περάω¹, πέρα², πείρω.</span></span></span><br><br>\n➁ <b>πέραν</b> <span>[ᾱ]</span> <i>adv. et prép. :</i><br><b>   I</b> au delà de, de l’autre côté, <i>d’ord. avec idée de la mer ou d’un fleuve qui sépare ; chez les plus anc. poètes avec un gén</i>. au delà de, de l’autre côté de, IL. <i>2, 626 ; 24, 752 ;</i> HÉS. <i>Th. 215, etc. ;</i> PD. <i>N. 5, 39 ;</i> SOPH. <i>Ant. 334 ;</i> THC. <i>2, 67, etc. ;</i> τὸ πέραν τοῦ ποταμοῦ, XÉN. <i>An. 3, 5, 2,</i> la région opposée du fleuve ; <i>gén</i>. HÉS. <i>Th. 814 ;</i> HDT. <i>6, 44 ;</i> THC. <i>1, 111 ;</i> XÉN. <i>An. 2, 4, 20, etc. ;</i> ἡ πέραν γῆ, THC. <i>3, 91,</i> la terre opposée ; τὸ πέραν, XÉN. <i>Hell. 1, 3, 17, etc</i>. le rivage situé de l’autre côté, la rive opposée ; τὰ πέραν, XÉN. <i>An. 4, 3, 24,</i> ce qui se passe sur la rive opposée ; τὰ πέραν πράγματα, POL. <i>3, 97, 5,</i> les affaires d’au delà, de l’autre côté ; οἱ πέραν, PLUT. <i>Mar. 23,</i> ceux de l’autre côté, de la région opposée ; <i>qqf. avec</i> εἰς <i>et l’acc</i>. HDT. <i>8, 36 ;</i> XÉN. <i>An. 7, 2, 2 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> vis-à-vis, HDT. <i>6, 97 ; avec le gén</i>. vis-à-vis de, IL. <i>2, 535 ;</i> ESCHL. <i>Ag. 190 ;</i> PAUS. <i>2, 22, 2, etc. ;</i><br><b>      2</b> au delà de, plus loin que, <i>gén</i>. PD. <i>I. 6, 33 ;</i> EUR. <i>Hipp. 1053, Alc. 588, Suppl. 676</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πέρην, IL. HÉS. HDT. <i>ll. cc. etc</i>.<br><span><b>Étym</b>. <i>acc. de</i> πέρα².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περαν - πέραν</font>\n<br><br>vient apparemment d'un dérivé de peiro (« percer »</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 23 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (7)</li>\n<li>Luc (1)</li>\n<li>Jean (8)</li>\n</ul>\n</td></tr>\n</table>","G4009":"<h1>peras</h1>\n<p>Strong n° 4009 <i>Prononciation [per'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>extrémité, borne, fin, bout\n<ol type=\"a\">\n<li>d'une portion d'espace\n<ol>\n<li>limites</li>\n<li>frontières</li>\n<li>les extrémités de la terre</li>\n<li>les territoires les plus éloignés</li>\n</ol>\n</li>\n<li>d'une chose s'étendant sur une période de temps (terminaison)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέρας, ατος (τὸ) :<br>   I</b> terme, fin, limite, extrémité, ESCHL. <i>Pers. 632 ;</i> EUR. <i>Andr. 1216, etc. ;</i> ἐκ περάτων γῆς, THC. <i>1, 69,</i> des extrémités de la terre ; π. ἔχειν, avoir un terme, PLAT. <i>Parm. 165</i> a ; LYCURG. <i>155, 34 ;</i> π. ἐπιθεῖναι τῷ πολέμῳ, POL. <i>1, 41, 2,</i> mettre fin à la guerre ; π. λαμϐάνειν, POL. <i>5, 31, 2,</i> prendre fin, tirer à sa fin ; <i>adv</i>., πέρας, ESCHN. <i>9, 21 ;</i> DÉM. <i>1285, 27 ;</i> POL. <i>2, 55, 6 ; ou</i> τὸ πέρας, LYS. <i>115, 35 ;</i> ARSTT. <i>Mir. 122 ;</i> POL. <i>1, 48, 9, etc</i>. à la fin, enfin ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> terme extrême, le plus haut point, le plus haut degré de force, d’autorité, ISOCR. <i>42</i> b ; DIN. <i>110, 15 ;</i> PLUT. <i>Alex. 40 ; ou en gén</i>. POSIDIPP. (ATH. <i>377</i> a), <i>etc. ;</i><br><b>      2</b> <i>d’où</i> accomplissement (d’un vœu, <i>etc</i>.) LUC. <i>Harm. 2, 3</i>.<br><span><b>Étym</b>. πεῖραρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περας - πέρας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4010":"<h1>Pergamos</h1>\n<p>Strong n° 4010 <i>Prononciation [per'-gam-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pergame (Angl. Pergamos) = « hauteur ou élévation »\n<ol><li>une cité de Mysie Mineure, en Asie Mineure, le siège des dynasties des Attale et des Eumène, célèbre pour son sanctuaire d'Asklepios (Esculape, dieu de la médecine), et l'invention et la fabrication du parchemin (pergamena en latin), qui tire son nom de cette ville. Eumène y créa une bibliothèque royale célèbre, seconde après celle d'Alexandrie. Une église chrétienne s'y trouvait, la 3ème des 7 Eglises d'Asie.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πέργαμος, ου (ὁ</b> <i>ou</i> <b>ἡ)</b> <span>[ᾰ]</span> Pergamos (Pergame) :<br><b>      1</b> <i>citadelle de Troie,</i> IL. <i>4, 508 ; 5, 446, 460, etc. ;</i><br><b>      2</b> <i>forteresse de Piérie,</i> HDT. <i>7, 112 ;</i><br><b>      3</b> <i>v. de Mysie,</i> XÉN. <i>Hell. 3, 1, 6 ;</i><br><b>      4</b> <i>p. ext</i>. toute place forte <i>ou</i> citadelle, ESCHL. <i>Pr. 956 ;</i> EUR. <i>Ph. 1098, 1176</i>.<br><span><b>Étym</b>. <i>cf</i>. πύργος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Περγαμος - Πέργαμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4011":"<h1>Perge</h1>\n<p>Strong n° 4011 <i>Prononciation [perg'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Perge (Angl. Perga) = « terreux »\n<ol><li>ville de Pamphilie, sur le fleuve Cestius, à environ 10 km de son embouchure, et fameuse dans l'antiquité pour son culte d'Artémis (Diane)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πέργη, ης (ἡ) :<br>      1</b> Pergè (<i>auj</i>. ruines près d’Aksu) <i>v. de Pamphylie,</i> CALL. <i>H. 3, 187 ;</i> STR. <i>667 ;</i><br><b>      2</b> <i>mt de Tyrrhénie,</i> LYC. <i>805</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Περγη - Πέργη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4012":"<h1>peri</h1>\n<p>Strong n° 4012 <i>Prononciation [per-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><i>autour, concernant, à cause de, parce que, près de, ...</i></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>περί</b> <span>[ῐ]</span> <i>adv. et prép. :</i><br><b><i>Adv</i>.<br>      1</b> tout autour : περί τ' ἀμφί τε, HH. <i>Cer. 277,</i> tout alentour ;<br><b>      2</b> au-dessus, <i>d’où fig</i>. par-dessus tout, surtout (<i>en ce sens on accentue</i> πέρι) : πέρι μέν σε τίον Δαναοί, IL. <i>8, 161,</i> les Grecs t’honoraient au-dessus de tous ; σὲ χρὴ πέρι μὲν φάσθαι ἔπος ἠδ' ἐπακοῦσαι, IL. <i>9, 100,</i> il te faut plus que tous les autres parler et écouter ; πέρι κέρδεα οἶδεν, OD. <i>2, 88,</i> elle s’entend par-dessus tout aux ruses ; τὸν πέρι Μοῦσ' ἐφίλησε, OD. <i>8, 63,</i> que la Muse aima par-dessus tous les autres ; <i>cf</i>. OD. <i>1, 66 ; 2, 116 ; 3, 95, etc. ; particul. dans la locut</i>. περὶ κῆρι (<i>où malgré le sens</i> περί <i>s’accentue comme s’il était prépos. sans que pourtant il faille le joindre à</i> κῆρι) : περὶ κῆρι φιλεῖν, IL. <i>13, 430, etc</i>. aimer de tout cœur (<i>litt</i>. par-dessus tout de cœur) ; ἀπέχθεσθαι περὶ κῆρι, IL. <i>4, 53,</i> haïr de tout cœur ; <i>cf</i>. IL. <i>4, 46, etc. ;</i> OD. <i>5, 36, etc. ; de même dans les locut</i>. περὶ φρεσίν, IL. <i>16, 157 ;</i> OD. <i>14, 433, m. sign. ;</i> περὶ θυμῷ, IL. <i>22, 70, etc. m. sign. ;</i> περὶ σθένεϊ, IL. <i>17, 22,</i> de toute sa force ;<br><b><i>Prép.</i></b> <i>avec le gén., le dat. et l’acc. :</i><br><i>Gén. :</i><br><b>   I</b> autour de (<i>sens rare et poét.) avec ou sans mouvement :</i> περὶ τρόπιος βεϐαῶτα, OD. <i>5, 130,</i> nageant autour de la carène de son vaisseau ; τείχη περὶ Δαρδανίας, EUR. <i>Tr. 824,</i> les murs autour de Troie ; <i>cf</i>. OD. <i>5, 68 ;</i> A. RH. <i>2, 1129, etc. ; p. suite,</i> aux côtés de, auprès de, MOSCH. <i>3, 60 ;</i> ANTH. <i>App. 120 ;</i><br><b>   II</b> pour, <i>càd. :</i><br><b>      1</b> au sujet de (<i>sens qui se rattache au préc. par l’usage primit. de</i> περί <i>avec les verbes marquant l’idée de combattre</i>) μάχεσθαι περὶ νηός, IL. <i>15, 416, 707 ; 16, 1 ; ou</i> περὶ θανόντος, IL. <i>8, 476,</i> combattre autour d’un vaisseau, d’un mort, <i>càd</i>. pour un vaisseau, pour un mort (autour duquel luttent les deux partis) ; ἀμύνεσθαι περὶ πάτρης, IL. <i>12, 243,</i> combattre pour la terre des ancêtres ; περὶ ψυχῆς, περὶ τῶν μεγίστων ὁ ἀγών, XÉN. <i>Cyr. 3, 3, 44,</i> la lutte pour la vie, pour les plus grands intérêts ; μάχη περί τινος, PLAT. <i>Theæt. 179</i> d, combat pour qqe ch. ; <i>par ext. sans idée de combat :</i> περὶ νόστου ἄκουσα, OD. <i>19, 270,</i> j’ai entendu parler de son retour ; διαλέγεσθαι περί τινος, XÉN. <i>An. 5, 5, 25,</i> s’entretenir au sujet de qqe ch. ; λέγειν περί τινος, THC. <i>4, 22, etc</i>. parler de qqn <i>ou</i> de qqe ch. ; λόγος περί τινος, PLAT. <i>Prot. 347</i> b, <i>etc</i>. entretien au sujet de qqn <i>ou</i> de qqe ch. ; κινδυνεύειν περί τινος, HDT. <i>8, 74,</i> ATT. courir un danger pour qqn <i>ou</i> pour qqe ch. ; περί τινος μερμηρίζειν, IL. <i>20, 17 ;</i> φροντίζειν, HDT. <i>8, 36,</i> s’inquiéter, se préoccuper de qqe ch. ; δεδιέναι περί τινος, PLAT. <i>Prot. 320</i> a, craindre pour qqn ; <i>en ce sens</i> περί <i>suivi ou précédé de son rég. se met souv. au commenc. de la phrase au sens de notre locut</i>. quant à : περὶ μὲν δὴ βρώσεως καὶ πόσεως οὕτω παρεσκευασμένος ἦν, XÉN. <i>Mem. 1, 3, 15,</i> en ce qui regarde la nourriture et la boisson, telles étaient ses dispositions ; ἀριθμοῦ δὲ πέρι μὴ πύθῃ, ὅσοι, <i>etc</i>. HDT. <i>7, 102,</i> quant au nombre, ne me demande pas combien, <i>etc. Dans le même sens il se construit souv. avec un subst. ou avec l’art. :</i> αἰτία περί τινος, PLAT. <i>Phæd. 95</i> e, <i>97</i> e, accusation au sujet de qqe ch. ; τὰ περί τινος, XÉN. <i>Hell. 1, 6, 28 ; 7, 4, 1, etc</i>. ce qui concerne qqn <i>ou</i> qqe ch. ;<br><b>      2</b> en vue de : τὴν ἀρχὴν τοῦ πολέμου γεγενημένην περὶ τοῦ τιμωρήσασθαι Φίλιππον, DÉM. <i>4, 43 Baiter-Sauppe,</i> (voyant que) la guerre avait commencé en vue de se venger de Philippe ; τοῦ πέρι, PLAT. <i>Prot. 312</i> b, en quel sens, de quelle façon ;<br><b>   III</b> par-dessus, au-dessus de, <i>au propre :</i> περὶ γᾶς μελαίνας, SAPPH. <i>1, 10 Bgk,</i> sur la noire terre ; <i>fig</i>. au-dessus, plus que : περὶ πάντων ἔμμεναι ἄλλων, IL. <i>1, 287,</i> être au-dessus de tous les autres ; <i>souv. avec un superlat. ou, en gén., un adj. :</i> περὶ δ' ἔγχει Ἀχαιῶν φέρτατός ἐσσι, IL. <i>7, 289,</i> tu es le plus habile des Grecs pour lancer la javeline ; περὶ πάντων κρατερός, IL. <i>21, 566,</i> fort par-dessus tous ; <i>particul. dans les locut</i>. περὶ πολλοῦ, περὶ πλείονος, περὶ πλείστου ποιεῖσθαι, ATT. faire grand cas, plus grand cas, très grand cas de, <i>acc. ;</i> περὶ ὀλίγου, ἐλάττονος ποιεῖσθαι, ATT. faire peu de cas, moins de cas de, <i>acc. ;</i> περὶ οὐδενὸς ἡγεῖσθαι, LYS. <i>189, 42,</i> ne faire aucun cas de ; περὶ παντὸς ποιεῖσθαι, XÉN. <i>Cyr. 1, 4, 1,</i> estimer au plus haut point.<br><i>Dat. :</i><br><b>   I</b> autour de : ἔνδυνε περὶ στήθεσσι χιτῶνα, IL. <i>10, 21,</i> il revêtit une tunique autour de sa poitrine ; περὶ μὲν τῇσι κεφαλῇσι εἶχον τιάρας, HDT. <i>7, 61,</i> ils avaient une tiare autour de la tête ; θώρακα περὶ τοῖς στέρνοις ἔχειν, XÉN. <i>Cyr. 1, 2, 13,</i> avoir une cuirasse autour de la poitrine ; οἱ στρεπτοὶ οἱ περὶ τῇ δέρῃ καὶ τὰ ψέλια τὰ περὶ ταῖς χερσίν, XÉN. <i>Cyr. 1, 3, 2,</i> les colliers autour du cou et les bracelets autour des bras ; περὶ τῇ χειρὶ χρυσοῦν δακτύλιον, PLAT. <i>Rsp. 359</i> e, un anneau d’or autour du bras ; κνημῖδας περὶ κνήμῃσιν ἔθηκε, IL. <i>11, 17,</i> il s’enveloppa les jambes de ses bottines ; <i>particul. en parl. de la blessure que fait un fer de lance :</i> περὶ δουρὶ πεπαρμένη, IL. <i>21, 577,</i> percée d’une lance ; περὶ τοῖς δορατίοις διεφθείροντο, THC. <i>7, 84,</i> ils périssaient percés de javelines. <i>En ce sens</i> περί <i>se construit souv. avec les verbes qui marquent une idée de protection, de défense :</i> ἑσταότες περὶ Πατρόκλῳ, IL. <i>17, 355,</i> se tenant debout autour de Patrocle (pour le protéger) ; ἑστήκει ὥς τίς τε λέων περὶ οἷσι τέκεσσιν, IL. <i>17, 133,</i> il se tenait debout comme un lion autour de ses petits (pour les défendre) ; <i>fig. :</i><br><b>      1</b> autour de, de manière à envelopper, <i>p. suite,</i> tout à fait, entièrement : περὶ κῆρι, IL. <i>4, 46, etc. ; ou</i> περὶ θυμῷ, IL. <i>22, 70, etc</i>. dans son cœur, de tout son cœur ;<br><b>      2</b> aux environs de, dans le voisinage de, auprès de : μάρναντο περὶ Σκαιῇσι πύλῃσι, IL. <i>18, 453,</i> ils combattaient autour des portes Scées ; κεῖται νεκρὸς περὶ νεκρῷ, SOPH. <i>Ant. 1240,</i> mort il est étendu près de la morte ; περὶ χειῇ, IL. <i>22, 95,</i> auprès d’un trou (de serpent) ;<br><b>   II</b> pour, <i>càd. :</i><br><b>      1</b> au sujet de : περὶ οἷσι μαχειόμενος κτεάτεσσι, OD. <i>17, 471,</i> combattant pour ses biens ; περὶ παιδὶ μάχης πόνος, IL. <i>16, 568,</i> le rude combat pour son fils (<i>propr</i>. autour de son fils) ; <i>p. anal. après les verbes exprimant l’idée de crainte ou de confiance :</i> περί τινι δεδιέναι, IL. <i>5, 566 ; 9, 433, etc. ;</i> THC. <i>1, 60, 67, etc. ; ou</i> περί τινι δειμαίνειν, HDT. <i>8, 74 ; ou</i> περί τινι φοϐεῖσθαι, THC. <i>2, 90, etc</i>. craindre pour qqn <i>ou</i> qqe ch. ; θαρρεῖν περί τινι, PLAT. <i>Phæd. 114</i> d, avoir confiance au sujet de qqe ch. ;<br><b>      2</b> à cause de, par suite de : περὶ τάρϐει, ESCHL. <i>Pers. 682 ;</i> περὶ φόϐῳ, ESCHL. <i>Ch. 35,</i> par crainte ; περὶ χάρματι, HH. <i>Cer. 430,</i> dans un transport de joie ; <i>cf</i>. HDT. <i>9, 101 ;</i> THC. <i>1, 69 ; 6, 33</i>.<br><i>Acc. ;</i><br><b>A</b> autour de :<br><b>   I</b> <i>dev. un nom de lieu ou de pers. :</i><br><b>      1</b> <i>propr</i>. autour de, <i>avec ou sans mouv. :</i> περὶ κεῖνον ὁμίλεον, OD. <i>24, 19,</i> ils se rassemblaient autour de lui ; περὶ ἄστυ μάρνασθαι, IL. <i>6, 256,</i> combattre autour de la ville ; περὶ τὸ στρατόπεδον εἶναι, XÉN. <i>An. 5, 1, 9</i> (il faut) qu’il y ait des gardes autour du camp ;<br><b>      2</b> au bord de, le long de, <i>avec idée d’une ligne circulaire :</i> ἡ ἀγορὰ ἡ περὶ τὰ ἀρχεῖα, XÉN. <i>Cyr. 1, 2, 4,</i> la place qui longe tout autour les édifices des magistrats ; ἡ περὶ Λέσϐον ναυμαχία, XÉN. <i>Hell. 2, 3, 32,</i> le combat naval près de Lesbos ; <i>p. ext</i>. au bord de : οἱ περὶ τὴν θάλατταν οἰκοῦντες, PLAT. <i>Phæd. 109</i> b, ceux qui habitent au bord de la mer ; περὶ τὴν κρήνην εὕδειν, PLAT. <i>Phædr. 259</i> a, dormir au bord de la fontaine ; <i>en ce sens, qqf. renforcé par</i> ἀμφί : περί τ' ἀμφί τε τάφρον, IL. <i>17, 760,</i> tout autour du fossé ; περὶ πίδακας ἀμφί, THCR. <i>Idyl. 7, 142,</i> tout autour de sources jaillissantes ; <i>cf</i>. HÉS. <i>Th. 848 ;</i><br><b>      3</b> contre : περὶ λίθον πεσεῖν, AR. <i>Ach. 1180,</i> être tombé contre une pierre ; ταραχθεῖσαι αἱ νῆες περὶ ἀλλήλας, THC. <i>7, 23,</i> les vaisseaux en désordre et s’étant embarrassés les uns au milieu des autres ;<br><b>      4</b> <i>p. suite,</i> dans la région de : τὰ περὶ τὴν Αἴγυπτον γεγονότα, HDT. <i>3, 13,</i> les événements accomplis en Égypte ; διατρίϐειν περὶ Πιερίην, HDT. <i>7, 131,</i> passer son temps <i>ou</i> séjourner dans la région de la Piérie ; εὕροι δ' ἄν τις αὐτὰς οὐκ ἐλάττους περὶ τοὺς βαρϐάρους ἢ τοὺς Ἕλληνας, PLAT. <i>Rsp. 544</i> d, on n’en trouverait pas moins chez les Barbares que chez les Grecs ;<br><b>   II</b> <i>dev. un nom de personne :</i> οἱ περί τινα, les personnes de l’entourage de qqn, <i>particul</i>. les gardes d’un prince, PLAT. <i>Rsp. 467 ;</i> les disciples d’un philosophe, PLAT. <i>Crat. 440</i> c ; THC. <i>8, 63 ;</i> XÉN. <i>An. 1, 5, 8, etc. ; p. ext</i>. l’entourage d’une personne avec cette personne même : οἱ περὶ Ἀρχίαν πολέμαρχοι, XÉN. <i>Hell. 5, 4, 2,</i> Arkhias et les polémarques ses collègues ; <i>et même</i> cette personne seule : οἱ περὶ Φαϐρίκιον, PLUT. <i>Pyrrh. 20,</i> Fabricius ; <i>cf</i>. PLUT. <i>Tim. 13 ;</i><br><b>   III</b> <i>dev. un n. de temps :</i> περὶ λύχνων ἁφάς, HDT. <i>7, 215,</i> vers l’heure où l’on allume les lampes ; περὶ πλήθουσαν ἀγοράν, XÉN. <i>An. 2, 1, 7,</i> vers l’heure où l’agora est remplie de foule ; περὶ τούτους τοὺς χρόνους, THC. <i>3, 89,</i> vers ce temps ; περὶ μέσας νύκτας, XÉN. <i>An. 1, 7, 1,</i> vers le milieu de la nuit ; <i>particul. avec un n. de nombre :</i> περὶ ἑϐδομήκοντα, THC. <i>1, 54,</i> soixante-dix environ ; περὶ ἔτη μάλιστα πέντε καὶ ἑξήκοντα, PLAT. <i>Parm. 127</i> b, vers 65 ans ; περὶ ἑπτακοσίους, XÉN. <i>Hell. 2, 4, 5,</i> environ sept cents ; <i>avec un n. de nombre ordinal :</i> περὶ ἑξηκοστόν, DÉM. <i>1302, 1,</i> environ le soixantième ;<br><b>B</b> pour (<i>avec un rég. désignant primitiv. un objet autour duquel on agit), particul. :</i><br><b>      1</b> en vue de : περὶ δόρπα πονεῖσθαι, IL. <i>24, 244,</i> se donner de la peine pour son repas (<i>propr</i>. autour de son repas), le préparer ; διατρίϐειν περί τι, XÉN. <i>Cyr. 1, 2, 11,</i> s’occuper de qqe ch. ; περί τι εἶναι, XÉN. <i>An. 3, 5, 7 ;</i> PLAT. <i>Gorg. 450</i> b, être occupé à qqe ch. ; περί τι γίγνεσθαι, POL. <i>1, 41, 6,</i> s’occuper de qqe ch. ; οἱ περὶ τὴν ποίησιν καὶ τοὺς λόγους ὄντες, ISOCR. <i>240</i> a, ceux qui s’occupent de poésie et d’éloquence, les poètes et les orateurs ; <i>ou sans participe :</i> οἱ περὶ τὰς τελετάς, PLAT. <i>Phæd. 69</i> c, ceux qui président aux cérémonies des mystères ; ὁ περὶ τὸν ἵππον, XÉN. <i>Eq. 6, 31,</i> le palefrenier ; οἱ περὶ τὴν θήραν, PLAT. <i>Soph. 220</i> d, ceux qui sont à la chasse ;<br><b>      2</b> à l’égard de : εὐσεϐεῖν περὶ θεούς, PLAT. <i>Conv. 193</i> b, être pieux envers les dieux ; τὰ προσήκοντα πράττειν περί τινα, PLAT. <i>Gorg. 507</i> a, remplir ses devoirs à l’égard de qqn ; σκαιουργεῖν περί τινα, AR. <i>Nub. 994,</i> se mal conduire avec qqn ; ἄδικος περί τινα, XÉN. <i>An. 1, 6, 8,</i> injuste envers qqn ; <i>p. suite,</i> περί <i>et l’acc. devient l’équivalent d’un gén. :</i> οἱ περὶ Λυσίαν λόγοι, PLAT. <i>Phædr. 279</i> a, les discours de Lysias ; ἡ περὶ Φίλιππον τυραννίς, XÉN. <i>Hell. 5, 4, 2,</i> le despotisme de Philippe ; τὰ περὶ ἐμὲ πράγματα (<i>comme</i> τὰ ἐμοῦ πρ.) ATT. les affaires qui me concernent, mes affaires ; τὰ περὶ Κῦρον, HDT. <i>1, 95,</i> ce qui concerne Cyrus ; τὰ περὶ τὰς ναῦς, THC. <i>1, 13,</i> les affaires navales, ce qui concerne la marine ; τὰ περὶ τὸν πόλεμον, PLAT. <i>Rsp. 468</i> a, les choses de la guerre ; τὰ περὶ τοὺς θεούς, XÉN. <i>Cyr. 8, 1, 23,</i> ce qui concerne les dieux ; <i>ou d’un adj. :</i> οἱ νόμοι οἱ περὶ τοὺς γάμους, PLAT. <i>Crit. 50</i> d, les lois sur le mariage ; ὄργανα ὅσα περὶ γεωργίαν, PLAT. <i>Rsp. 370</i> d, tous les instruments propres à l’agriculture.<br><span><b><span class=\"arrow\"></span><br>   I</b> περί <i>peut se construire en poésie et qqf. en prose après son rég. ; il s’accentue alors</i> πέρι : τοῦδε πράγματος πέρι, ESCHL. <i>Eum. 630,</i> au sujet de cette affaire ; <i>cf</i>. ESCHL. <i>Sept. 248, etc. ;</i> ἣν πέρι, IL. <i>5, 739,</i> autour d’elle ; ἄστυ πέρι, IL. <i>22, 173,</i> autour de la ville ; <i>de même en prose,</i> HDT. <i>8, 36 ;</i> PLAT. <i>Phil. 49</i> a, <i>etc. ;</i> ARSTT. <i>Poet. 22 ; il peut être séparé de son rég. par plus. mots,</i> PLAT. <i>Leg. 809</i> e, <i>etc. ;</i><br><b>   II</b> περί <i>s’élide qqf. en poésie dans les composés :</i> περόδοις, PD. <i>N. 11, 51 ;</i> περιδαῖος, PD. <i>fr. 126 ;</i> περιών, AR. <i>Eq. 1011 ;</i> περίαχε, HÉS. <i>Th. 678 ;</i> Q. SM. <i>3, 601 ; 11, 382 ;</i> περάπτων, PD. <i>P. 3, 94, mais non</i> περεϐάλοντο, ESCHL. <i>Ag. 1106, leçon suspecte pour</i> περιϐάλοντο, <i>ni</i> περεσκήνωσεν, ESCHL. <i>Eum. 635, mauv. leç. p</i>. παρεσκήνωσεν ; <i>très rar. d’un mot à un autre, en dor. et en éol. :</i> περ' ἀτλάτου, PD. <i>O. 6, 65 ;</i> περ' αὐτᾶς, PD. <i>P. 4, 265 ; même dev. une consonne :</i> περ σῶ, ALC. <i>74. Il devient</i> περρ- <i>dans</i> πέρροχος <i>p</i>. περίοχος ; περρ' ἀπάλω, THCR. <i>Idyl. 29, 25, est une mauv. leç. p</i>. ὑπὲρ ἀπάλω ;<br><b>   III</b> <i>En compos</i>. περί <i>signifie :</i><br><b>      1</b> autour (περιϐαίνω, περιϐάλλω) ;<br><b>      2</b> <i>p. suite,</i> après un circuit complet, retour au point de départ (περιάγω, περιϐαίνω, περιέρχομαι) ;<br><b>      3</b> par-dessus, au-dessus (περιγίγνομαι, περιεργάζομαι) ;<br><b>      4</b> tout à fait (περικαλλής) ;<br><b>      5</b> <i>l’idée d’une chose double</i> (περιδέξιος).<br><span><b>Étym</b>. <i>indo-europ. locat. sg</i>. *per-i, en traversant, <i>de la</i> R. *per-, au delà, à travers ; <i>cf</i>. πέρα², <i>lat</i>. per, per- <i>dans les composés avec idée de superl</i>. pergrātus, perpaucī ; <i>sscr</i>. pári, autour.</span></span><br><br>\n➁ <b>πέρι</b>, <i>v</i> περί <i>et</i> περίειμι¹.<br><br>\n<b>περί·ειμι</b> <span>(<i>impf</i>. περιῆν, <i>f</i>. περιέσομαι)</span><br><b>   I</b> être autour de, <i>dat</i>. THC. <i>7, 81 ;</i><br><b>   II</b> être au-dessus de, être supérieur à, l’emporter sur : τινός, HDT. <i>3, 146,</i> sur qqn ; τινός τι, OD. <i>18, 248 ; ou en prose</i> τινός τινι, PLAT. <i>Conv. 221</i> a, <i>1 Alc. 119</i> c, sur qqn en qqe ch. ; <i>avec un seul rég. :</i> τινι, HDT. <i>9, 31 ;</i> THC. <i>6, 22 ;</i> XÉN. <i>An. 1, 8, 13, etc</i>. l’emporter en qqe ch., être supérieur en qqe ch. ;<br><b>   III</b> être de plus, être en plus, <i>d’où :</i><br><b>      1</b> être de reste : ἐκ περιόντος, THC. <i>8, 46,</i> avec supériorité ; <i>en mauv. part :</i> ἐκ τοῦ περιόντος, DÉM. <i>1483, 15, etc</i>. par orgueil ; τὸ περιὸν τοῦ στρατοῦ, THC. <i>2, 79,</i> le reste de l’armée ; τὰ περιόντα κλήρου, PLAT. <i>Leg. 923</i> d, ce qui reste d’un héritage ; ἡ περιοῦσα παρασκευή, THC. <i>1, 89,</i> ce qui reste des biens mobiliers ;<br><b>      2</b> survivre : τινί, HDT. <i>1, 121, etc. ;</i> PLUT. <i>M. 259</i> e, à qqn ; <i>abs</i>. HDT. <i>1, 120, etc. ;</i><br><b>      3</b> rester, se maintenir : π. ἐλευθέρην, HDT. <i>7, 139,</i> rester libre, <i>en parl. de la Grèce ; en parl. de choses,</i> HDT. <i>1, 92, etc. ;</i><br><b>      4</b> rester comme résultat final : ψηφίσμαθ' ὑμῖν περιέσται, DÉM. <i>1432, 16,</i> il vous en restera des décrets, vous y gagnerez des décrets ; ὑμῖν περίεστιν ἐκ τούτων, DÉM. <i>172, 9,</i> de cela, il vous reste l’avantage de, <i>etc.,</i> vous gagnez à cela de, <i>etc. ; avec l’inf</i>. περίεστι τοίνυν ἡμῖν ἀλλήλοις ἐρίζειν, DÉM. <i>26, 20,</i> nous y gagnons de nous quereller mutuellement.<br><span><b>Étym</b>. π. εἰμί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περι - περί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n330 fois dans 303 versets de 24 livres bibliques (NT)\n<ul>\n<li>Matthieu (26)</li>\n<li>Marc (24)</li>\n<li>Luc (44)</li>\n<li>Jean (69)</li>\n<li>Actes (69)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (10)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (9)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (3)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (22)</li>\n<li>1 Pierre (5)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (10)</li>\n<li>3 Jean (1)</li>\n<li>Jude (5)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4013":"<h1>periago</h1>\n<p>Strong n° 4013 <i>Prononciation [per-ee-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener autour, conduire avec soi</li>\n<li>parcourir, courir (les mers, ou la campagne)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·άγω</b> <span>[ᾰ]</span><br><b>   I <i>tr</i>.<br>      1</b> conduire autour, promener autour : τὸν ἵππον ἄγχου τῇ ἵππῳ, HDT. <i>3, 85,</i> conduire <i>ou</i> promener le cheval tout auprès autour de la jument ; <i>avec l’acc. du lieu :</i> λίμνην κύκλῳ, HDT. <i>4, 180,</i> conduire autour d’un lac ;<br><b>      2</b> faire circuler : ποτήριον, ATH. <i>420</i> a ; ALCIPHR. <i>1, 22, etc</i>. une coupe ;<br><b>      3</b> faire tourner : τινά, AR. <i>Vesp. 990,</i> qqn ; τῶ χεῖρε, LYS. <i>94, 10 ;</i> LUC. <i>Nav. 30 ;</i> PHILSTR. <i>p. 714,</i> amener les mains derrière le dos (pour les lier) ;<br><b>      4</b> remuer en tournant : τὴν κεφαλήν, AR. <i>fr. 682 Dind. ;</i> τὸν αὐχένα, PLAT. <i>Rsp. 515</i> c, tourner la tête, le cou ;<br><b>      5</b> emmener à ses côtés, avec soi, <i>acc</i>. XÉN. <i>Cyr. 2, 2, 28 ;</i> POL. <i>20, 5, 8, etc. ;</i><br><b>      6</b> détourner, fourvoyer à force de paroles, <i>acc</i>. LUC. <i>Nigr. 8 ;</i><br><b>      7</b> différer, reculer, <i>acc</i>. LUC. <i>M. cond. 31 ;</i><br><b>      8</b> amener insensiblement à, finir par réduire à, <i>avec</i> εἰς <i>et l’acc. :</i> πολιτείαν πρὸς ἑτέραν, ARSTT. <i>Pol. 2, 6, 4,</i> faire évoluer un système de gouvernement vers un autre ;<br><b>   II <i>intr.</i></b> aller autour, tourner autour, CÉB. <i>p. 84 ; d’où</i> parcourir, <i>acc</i>. NT. <i>Matth. 4, 23 ; 9, 35, etc. ;</i><br><b><i>Moy.</i></b> emmener avec soi tout autour, avoir toujours auprès de soi, <i>acc</i>. XÉN. <i>Mem. 1, 7, 2 ;</i> THPP. <i>et</i> POSIDON. (ATH. <i>533</i> b, <i>542</i> b), <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιαγω - περιάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4014":"<h1>periaireo</h1>\n<p>Strong n° 4014 <i>Prononciation [per-ee-ahee-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enlever tout ce qui entoure ou enveloppe une chose</li>\n<li>métaph. délier, libérer tout à fait ou entièrement\n<ol type=\"a\">\n<li>la culpabilité du péché, expier parfaitement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·αιρέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao.2</i> περιεῖλον)</span> enlever autour, <i>d’où :</i><br><b>      1</b> retirer qqe ch. qui enveloppe : χιτῶνα, ARSTT. <i>H.A. 5, 32, 4,</i> une tunique ; δέρματα σωμάτων, PLAT. <i>Pol. 288</i> e, la peau des corps ; <i>avec idée de violence :</i> τί τινος, HDN <i>3, 11, 6,</i> arracher qqe ch. à qqn, dépouiller qqn de qqe ch. ; <i>p. anal</i>. π. τινα τῆς ἀλαζονείας, AR. <i>Eq. 290,</i> faire passer à qqn sa vantardise ; <i>au pass</i>. περιῃρημένοι χρήματα, DÉM. <i>37, 4,</i> dépouillés de leurs ressources ; περιαιρεθεὶς τὰ ὄντα, DÉM. <i>559, 26,</i> dépouillé de ses biens ;<br><b>      2</b> enlever qqe ch. qui entoure : τείχη, HDT. <i>3, 159, etc. ;</i> THC. <i>1, 108 ;</i> LYS. <i>126, 37, etc</i>. renverser <i>ou</i> raser des murs tout autour ; <i>fig</i>. faire disparaître, supprimer, abroger, <i>acc</i>. XÉN. <i>Cyr. 2, 1, 21, etc. ;</i><br><b>      3</b> réfuter successivement, à tour de rôle, <i>acc</i>. XÉN. <i>Mem. 3, 2, 4 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> ôter d’autour (de son doigt, de sa tête, de son corps, <i>etc.) acc</i>. HDT. <i>2, 151, etc. ;</i> PLAT. <i>Conv. 213</i> a ;<br><b>      2</b> ôter tout autour pour soi : βιϐλίον, HDT. <i>3, 128,</i> défaire les cordons qui entourent une lettre, <i>càd</i>. l’ouvrir ; <i>p. suite :</i> τινός τι, XÉN. <i>Cyr. 8, 1, 47 ;</i> PLAT. <i>Gorg. 502</i> c ; DÉM. <i>246, 23, etc</i>. dépouiller qqn <i>ou</i> qqe ch. de qqe ch. qui entoure.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιαιρεω - περιαιρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4015":"<h1>periastrapto</h1>\n<p>Strong n° 4015 <i>Prononciation [per-ee-as-trap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>éclairer autour, faire briller tout autour</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·αστράπτω</b>, illuminer d’éclairs tout autour, <i>acc</i>. NT. <i>Ap. 9, 3 ; avec</i> περί <i>et l’acc</i>. NT. <i>Ap. 22, 6 ; fig</i>. JUNC. (STOB. <i>Fl. 117, 9</i>).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιαστραπτω - περιαστράπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4016":"<h1>periballo</h1>\n<p>Strong n° 4016 <i>Prononciation [per-ee-bal'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter autour de, mettre autour\n<ol type=\"a\">\n<li>entourer une cité avec un mur (une palissade)</li>\n<li>de vêtements, vêtir\n<ol>\n<li>poser une chose sur quelqu'un</li>\n<li>vêtir quelqu'un d'une chose</li>\n</ol>\n</li>\n<li>se vêtir, se revêtir, être vêtu, revêtu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ϐάλλω :<br>A <i>tr. :</i><br>   I</b> jeter autour :<br><b>      1</b> <i>abs</i>. πεῖσμα κίονος ἐξάψας περίϐαλλε, OD. <i>22, 466,</i> il fixa une corde à une colonne et la passa autour (du cou des servantes) ;<br><b>      2</b> <i>avec l’acc. de la chose que l’on jette autour et le dat. de la pers. ou de la chose autour de laquelle on jette :</i> χεῖρας π. τινί, EUR. <i>Or. 1044, I.T. 799, etc. ;</i> PLAT. <i>Conv. 219</i> b, <i>etc</i>. jeter les mains autour de qqn, embrasser qqn ; π. τεῖχος τῷ λιμένι, POL. <i>4, 65, 11,</i> élever un mur autour du port ; <i>fig</i>. π. τινὶ τυραννίδα, EUR. <i>Ion 829,</i> attribuer à qqn le pouvoir d’un tyran ; δουλείαν Μυκήναις, EUR. <i>Ph. 197,</i> réduire Mycènes en esclavage ;<br><b>      3</b> <i>avec l’acc. de la pers. ou de la chose que l’on entoure et le dat. de l’objet dont on entoure :</i> π. τινὰ χαλκεύματι, ESCHL. <i>Ch. 576,</i> frapper qqn d’une épée ; <i>d’où sans dat</i>. π. τινά, SPT. <i>Esaï. 58, 7 ;</i> NT. <i>Matth. 25, 36,</i> vêtir qqn ; Βόσπορον πέδαις, ESCHL. <i>Pers. 748,</i> charger le Bosphore de chaînes ; τὸν αὐχένα βρόχῳ, HDT. <i>4, 60,</i> entourer le cou d’un lacet ; <i>d’où sans dat</i>. π. ἰχθύων πλῆθος, HDT. <i>1, 141,</i> prendre dans des filets une multitude de poissons ; Ὀρέστην χερσί, EUR. <i>Or. 372,</i> embrasser Oreste ; <i>d’où sans dat</i>. π. ἀλλήλους, XÉN. <i>Conv. 9, 7,</i> s’embrasser les uns les autres ; <i>fig</i>. π. τινὰ κακῷ, EUR. <i>Or. 906, litt</i>. entourer qqn de malheur, précipiter dans le malheur ; <i>cf</i>. XÉN. <i>Mem. 1, 2, 63 ;</i> ISOCR. <i>117</i> a ; DÉM. <i>416, 10 ;</i> Σικελίαν πένθει, PLAT. <i>Ep. 351</i> e, jeter la Sicile dans le deuil ; π. τινὰ ὀνείδει, DÉM. <i>604, 9,</i> couvrir qqn de honte ; π. τινὰ φυγῇ, PLUT. <i>M. 775</i> c, punir qqn, jeter qqn en exil ; <i>avec un nom de chose pour suj. :</i> σκότος π. με, EUR. <i>Ph. 1462,</i> l’obscurité m’entoure ;<br><b>      4</b> <i>avec l’acc. de la chose que l’on jette et une prép. :</i> ναῦν π. περὶ ἕρμα, THC. <i>7, 25,</i> pousser un vaisseau sur un banc de sable, échouer avec le navire ;<br><b>B</b> <i>intr. en appar. (s.-e</i>. ἑαυτόν, ἵππον, νῆα, <i>etc</i>.) s’élancer autour ; τὸν Ἄθων π. HDT. <i>6, 44,</i> tourner autour de l’Athos avec la flotte, doubler le mt Athos ; π. Σούνιον, THC. <i>8, 95,</i> doubler le cap Sounion ; <i>abs</i>. revenir à un lieu par des détours, s’en retourner, XÉN. <i>Cyn. 5, 29, etc. ; fig</i>. faire le tour de, <i>càd</i>. dépasser, surpasser : τινά τινι, OD. <i>15, 17,</i> surpasser qqn en qqe ch. ; <i>abs</i>. π. ἀρετῇ, IL. <i>23, 276,</i> être supérieur en vaillance ;<br><b><i>Moy</i>. περιϐάλλομαι</b> :<br><b>A <i>tr. :</i><br>   I</b> jeter autour de soi :<br><b>      1</b> <i>avec l’acc. de l’objet dont on entoure :</i> τεύχεα, OD. <i>22, 148,</i> jeter ses armes autour de soi, revêtir son armure ; τείχεα, HDT. <i>9, 97, ou</i> τεῖχος, THC. <i>1, 8,</i> élever des murs, un mur tout autour pour se protéger ;<br><b>      2</b> <i>avec deux rég. à l’acc. :</i> τεῖχος τὴν πόλιν, HDT. <i>1, 163,</i> élever un mur autour de la ville ; <i>ou plus souv. avec deux rég. de cas différents :</i> ταῖς πόλεσιν ἐρύματα, XÉN. <i>Mem. 2, 1, 14,</i> élever des retranchements autour des villes ; τὴν νῆσον τείχει, PLAT. <i>Criti. 116</i> a, entourer l’île d’un mur ;<br><b>   II</b> jeter autour de, <i>en gén. :</i> περιεϐάλοντό οἱ πτεροφόρον δέμας θεοί, ESCHL. <i>Ag. 1147,</i> les dieux l’entourèrent (le rossignol) d’un corps couvert de plumes ;<br><b>B <i>intr. :</i><br>      1</b> se jeter autour de, <i>d’où</i> cerner, entourer (une troupe, XÉN. <i>Cyr. 1, 4, 17 ;</i> un lieu, XÉN. <i>Cyr. 6, 3, 30</i>) ;<br><b>      2</b> <i>p. suite,</i> s’emparer de : πόλιν, HDT. <i>6, 25 ;</i> XÉN. <i>An. 6, 3, 3,</i> d’une ville ; χρήματα, HDT. <i>8, 8,</i> prendre pour soi des choses précieuses ;<br><b>      3</b> <i>fig</i>. embrasser par la pensée, considérer, <i>acc</i>. ISOCR. <i>106</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. part. pf</i>. περιϐεϐλημένος, <i>au sens pass</i>. HDT. <i>2, 91 ;</i> PLAT. <i>Criti. 116</i> a, DÉM. <i>43, 79 Baiter-Sauppe ; au sens moy</i>. PLAT. <i>Theæt. 174 ;</i> ISOCR. <i>4, 184 Baiter-Sauppe. Pl.q.pf. 3 pl. ion</i>. περιεϐεϐλέατο, HDT. <i>6, 25</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιβαλλω - περιβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 24 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G4017":"<h1>periblepo</h1>\n<p>Strong n° 4017 <i>Prononciation [per-ee-blep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>regarder autour</li>\n<li>regarder tout autour de soi</li>\n<li>jeter les regards (sur quelqu'un qui est proche)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ϐλέπω :<br>      1</b> regarder tout autour, <i>acc</i>. AR. <i>Eccl. 403 ;</i> TÉLÈS (STOB. <i>Fl. 91, 33) ; ou</i> πρός <i>et l’acc</i>. PLAT. <i>Eryx. 395</i> c ;<br><b>      2</b> porter ses regards tout autour, de l’un à l’autre : τινά, XÉN. <i>Cyr. 5, 1, 4 ;</i> CHARÈS (ATH. <i>575</i> d) sur qqn ;<br><b>      3</b> chercher des yeux de tous côtés, <i>acc</i>. POL. <i>5, 20, 5 ;</i> LUC. <i>V. auct. 12 ; fig</i>. π. τοὔνδικον, SOPH. <i>O.C. 996,</i> avoir égard à la justice ;<br><b>      4</b> regarder avec admiration, admirer, <i>acc</i>. EUR. <i>Ion 624 ; au pass</i>. EUR. <i>Ph. 554 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> chercher du regard de tous côtés, <i>acc</i>. POL. <i>9, 17, 6 ;</i> DS. <i>16, 32, etc. ; fig</i>. aspirer à, convoiter, <i>acc</i>. M. ANT. <i>7, 55 ;</i> APP. <i>Civ. 3, 7 ;</i><br><b>      2</b> regarder autour de soi, <i>acc</i>. NT. <i>Marc. 3, 5 ;</i><br><b>      3</b> <i>p. suite,</i> regarder autour de soi avec défiance, prendre garde, être circonspect, ARR. <i>Epict. 3, 14, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιβλεπω - περιβλέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (6)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4018":"<h1>peribolaion</h1>\n<p>Strong n° 4018 <i>Prononciation [per-ib-ol'-ah-yon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une couverture mise autour, une enveloppe\n<ol type=\"a\">\n<li>un manteau</li>\n<li>un voile</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περιϐόλαιον, ου (τὸ)</b> <i>propr</i>. enveloppe, <i>d’où :</i><br><b>      1</b> vêtement, manteau, EUR. <i>H.f. 549, en parl. de la chair qui recouvre le corps,</i> EUR. <i>H.f. 1269 ;</i><br><b>      2</b> couverture pour les pieds, PLUT. <i>Arat. 43 ;</i> couverture d’un char, d’une voiture, PLUT. <i>Alex. 67</i>.<br><span><b>Étym</b>. περιϐολή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιβολαιον - περιβόλαιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4019":"<h1>perideo</h1>\n<p>Strong n° 4019 <i>Prononciation [per-ee-deh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lier autour, attacher, nouer, envelopper étroitement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·δέω-ῶ</b> <span>(<i>f</i>. -δήσω, <i>etc</i>.)</span> lier autour : τί τινι, HDT. <i>1, 193,</i> attacher une chose autour d’une autre ; πώγωνά τινι, AR. <i>Eccl. 127,</i> attacher une fausse barbe au menton de qqn ; <i>ou avec l’acc. de l’objet entouré :</i> πόδα ἱμᾶσι, HPC. <i>Fract. 760,</i> entourer un pied de bandages ; <i>cf</i>. ARSTT. <i>H.A. 9, 39, 4 ;</i><br><b><i>Moy.</i></b> attacher autour de soi, <i>acc</i>. HDT. <i>4, 176 ;</i> AR. <i>Ran. 1038, etc. ;</i> PLAT. <i>Leg. 830</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 3 sg. ion. non contr</i>. περιδέεται, HDT. <i>4, 176 ; impf. 1 pl. att. contracte</i> περιεδούμεθα, PLAT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιδεω - περιδέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4020":"<h1>periergazomai</h1>\n<p>Strong n° 4020 <i>Prononciation [per-ee-er-gad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se remuer inutilement, s'occuper de choses insignifiantes, inutiles, d'affaires sans utilité\n<ol type=\"a\">\n<li>utilisé apparemment pour une personne qui s'enquiert officieusement des affaires des autres, se mêler de tout, s'ingérer dans les affaires de quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·εργάζομαι :<br>      1</b> travailler avec trop de soin, prendre un soin superflu : τινι, HDT. <i>3, 46 ;</i> EL. <i>V.H. 4, 11 ;</i> ἔν τινι, LUC. <i>Her. 6 ;</i> τι, AR. <i>Eccl. 200,</i> en qqe ch. ; <i>avec un part</i>. PLAT. <i>Ap. 19</i> b, <i>etc. ;</i><br><b>      2</b> se mêler indiscrètement de qqe ch., s’ingérer dans les affaires d’autrui, DÉM. <i>805, 4 ; avec l’acc</i>. POL. <i>18, 34, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. 3 sg</i>. περιείργασται, <i>au sens pass</i>. LUC. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιεργαζομαι - περιεργάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4021":"<h1>periergos</h1>\n<p>Strong n° 4021 <i>Prononciation [per-ee'-er-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>occupé à des bagatelles et négligent sur les affaires importantes\n<ol type=\"a\">\n<li>spéc. s'occuper des affaires des gens</li>\n<li>de choses : déplacé, inopportun, superflu\n<ol>\n<li>du domaine des recherches vaines, des arts magiques</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περί·εργος, ος, ον :<br>   I</b> <i>act. :</i><br><b>      1</b> qui prend un soin superflu, minutieux à l’excès, LYS. <i>123, 24 ;</i> ISOCR. <i>102</i> a ; <i>joint à</i> μάταιος, XÉN. <i>Mem. 1, 3, 1 ;</i> περίεργόν ἐστι <i>avec l’inf</i>. ISOCR. <i>47</i> b, <i>etc</i>. il est superflu de, <i>etc. ;</i><br><b>      2</b> qui s’occupe de ce qui ne le regarde pas, indiscret, LUC. <i>D. mar. 3, 2 ; joint à</i> πολυπράγμων, ARR. <i>Epict. 3, 1, 21 ; adv</i>. περίεργα, ANTH. <i>12, 175, etc</i>. avec une curiosité indiscrète ;<br><b>      3</b> qui concerne la magie, NT. <i>Luc. 19, 19 ; en parl. de pers</i>. adonné à l’étude de la magie, DC. <i>69, 11 ;</i><br><b>   II</b> <i>pass</i>. travaillé avec un soin excessif, d’un art raffiné, ESCHN. <i>86, 27 ;</i> DH. <i>Lys. 14, etc. ;</i> τὸ περίεργον, LUC. <i>Nigr. 13,</i> soin excessif, art prétentieux.<br><span>•<i> Cp</i>. -ότερος, ISOCR. <i>416</i> a ; DH. <i>Is. 3, etc</i>.<br><span><b>Étym</b>. π. ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιεργος - περίεργος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4022":"<h1>perierchomai</h1>\n<p>Strong n° 4022 <i>Prononciation [per-ee-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parcourir\n<ol type=\"a\">\n<li>des artistes ambulants</li>\n<li>de vagabonds</li>\n<li>de navigateurs (faisant un circuit)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·έρχομαι</b> <span>(<i>f</i>. -ελεύσομαι, <i>ao.2</i> -ῆλθον, <i>pf</i>. περιελήλυθα)</span><br><b>   I</b> aller autour, <i>càd. :</i><br><b>      1</b> faire le tour de, <i>abs</i>. HDT. <i>7, 225 ;</i> THC. <i>4, 36 ; en parl. d’un astre :</i> τὸν κύκλον, PLAT. <i>Tim. 39</i> c, parcourir le cercle de sa course ; <i>d’où abs</i>. accomplir sa révolution, ARSTT. <i>Cæl. 1, 5, 14 ; en parl. du temps,</i> accomplir son évolution, s’écouler, XÉN. <i>Cyr. 8, 6, 19, etc. ; avec l’acc. du lieu parcouru :</i> τὴν ἀγορὰν κύκλῳ, DÉM. <i>411, 16,</i> faire le tour de la place publique ; τὴν πόλιν, AND. <i>13, 25,</i> faire le tour de la ville, parcourir toute la ville ; πᾶσαν γῆν, XÉN. <i>Ages. 9, 3,</i> faire le tour du monde ; <i>avec l’acc. du chemin :</i> στάδια χίλια, AR. <i>Av. 6,</i> faire mille stades ; ὁδόν, PLAT. <i>Theæt. 147</i> c, faire un détour, <i>etc. ;</i><br><b>      2</b> aller autour, entourer, cerner : τοὺς πολεμίους κύκλῳ, PLUT. <i>Popl. 22,</i> entourer l’ennemi en le cernant ; <i>fig</i>. circonvenir, chercher à tromper, à séduire, à corrompre : τινα, AR. <i>Eq. 1142,</i> qqn ; τινά τινι, HDT. <i>3, 4 ; ou</i> διά τινος, PLUT. <i>Nic. 10,</i> qqn par qqe moyen ;<br><b>   II</b> arriver jusqu’à, <i>d’où :</i> faire un tour complet et revenir au point de départ, <i>avec</i> ἐς <i>et l’acc</i>. HDT. <i>1, 95 ; p. suite, en gén. :</i><br><b>      1</b> échoir par hasard <i>ou</i> par succession : ἔς τινα, HDT. <i>1, 7, 187, etc</i>. à qqn ;<br><b>      2</b> parvenir à : <i>d’où en gén</i>. εἰς ἅπαντας, PLUT. <i>M. 151</i> b, parvenir à la connaissance de tous sans exception ; <i>p. suite,</i> finir par atteindre : ἔς τινα, HDT. <i>7, 158 ; ou avec l’acc</i>. τινα, HDT. <i>8, 106 ;</i> LUC. <i>H. conscr. 2, etc</i>. qqn, <i>en parl. d’un châtiment, d’un mal, etc. ; d’où en gén</i>. venir à, aboutir à : ἔς τι, HDT. <i>7, 88,</i> aboutir à qqe ch., dégénérer en qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. περιηρχόμην, AR. <i>Th. 504</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιερχομαι - περιέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4023":"<h1>periecho</h1>\n<p>Strong n° 4023 <i>Prononciation [per-ee-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entourer\n<ol type=\"a\">\n<li>contenir : le sujet, le contenu d'un écrit</li>\n<li>prendre possession de, saisir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·έχω</b> <span>(<i>f</i>. περιέξω <i>ou</i> περισχήσω, <i>ao.2</i> περιέσχον, <i>etc</i>.)</span><br><b>A <i>tr. :</i><br>   I</b> entourer, envelopper : περιέχειν τινὰ ἀμφοτέραις ταῖς χερσίν, PLUT. <i>Ant. 80,</i> étreindre qqn de ses deux mains ; <i>abs</i>. ὄρους περιέχοντος κύκλῳ, DÉM. <i>1274, 15,</i> une montagne se dressant tout autour ; ὁ περιέχων ἀήρ, TH. <i>H.P. 8, 7, 6 ;</i> DH. <i>3, 47 ;</i> PLUT. <i>M. 333</i> e ; <i>ou abs</i>. ὁ περιέχων, POL. <i>5, 21, 8, etc</i>. l’air ambiant, l’atmosphère ; τὸ περιέχον, ARTÉM. <i>2, 36, m. sign. ; particul. :</i><br><b>      1</b> embrasser qqn, <i>acc</i>. PLUT. <i>Alex. 51 ;</i><br><b>      2</b> entourer pour protéger, PLUT. <i>Cæs. 16, Agis 12, etc. ;</i><br><b>      3</b> <i>avec idée d’hostilité,</i> occuper tout autour, bloquer, cerner, <i>acc</i>. (une maison, PLUT. <i>Agis 19 ;</i> qqn, APP. <i>Civ. 2, 114) ; au pass</i>. être cerné, HDT. <i>8, 79 ;</i> XÉN. <i>Cyr. 7, 1, 24, etc. ; fig</i>. περιέχεσθαι τοῖς πράγμασι, POL. <i>24, 12, 3,</i> être pressé par les événements ;<br><b>   II</b> enfermer, contenir en soi, comprendre : <i>acc</i>. PLAT. <i>Men. 87</i> d ; DS. <i>2, 1 ; au pass</i>. PLAT. <i>Soph. 233</i> d, <i>etc. ; part</i>. περιέχων, ουσα, ον, qui embrasse, <i>d’où</i> général, universel : π. ὀνόματα, ARSTT. <i>Rhet. 3, 5,</i> termes généraux ; τὸ περιέχον, ARSTT. <i>Metaph. 5, 26,</i> le général, l’universel ; ἐκ τοῦ περιέχοντος καλεῖν, ATH. <i>309</i> a, nommer du nom général ;<br><b>B <i>intr.</i></b> dépasser, déborder, <i>en parl. des ailes d’une armée,</i> THC. <i>3, 108 ; d’où</i> avoir la prédominance, l’emporter, THC. <i>5, 7 ; 8, 105, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> s’attacher tout autour, se cramponner à, embrasser, étreindre : γούνατα χερσίν, A. RH. <i>3, 706 ;</i> τινὰ γούνων, A. RH. <i>4, 82,</i> étreindre de ses mains <i>ou</i> embrasser les genoux de qqn ;<br><b>      2</b> <i>particul</i>. embrasser par affection, s’attacher fortement à, <i>gén</i>. HDT. <i>3, 53, etc. ;</i> PLUT. <i>Arat. 42 ;</i><br><b>      3</b> <i>p. suite,</i> entourer pour protéger, protéger, <i>acc</i>. OD. <i>9, 199 ; d’où</i> prendre soin de, embrasser les intérêts de, <i>gén</i>. IL. <i>1, 393 ;</i><br><b>      4</b> s’attacher fortement à, <i>gén</i>. HDT. <i>1, 71 ; 3, 72, etc. ;</i> PLUT. <i>T. Gracch. 16, etc. ; avec l’inf</i>. prier instamment, HDT. <i>9, 57 ;</i> PLUT. <i>M. 778</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2, 3 sg. poét</i>. περίσχετο, A. RH. <i>3, 706 ; impér. 2 sg. poét</i>. περίσχεο, IL. <i>1, 393</i>.<br><span><b>Étym</b>. π. ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιεχω - περιέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4024":"<h1>perizonnumi</h1>\n<p>Strong n° 4024 <i>Prononciation [per-id-zone'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fixer des vêtements avec une ceinture</li>\n<li>se ceindre, mettre une ceinture</li>\n<li>métaph. avec la vérité comme ceinture\n<ol type=\"a\">\n<li>s'équiper, se ceindre, de la connaissance de la vérité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ζώννυμαι :<br>      1</b> se ceindre d’un caleçon, PAUS. <i>1, 44, 1 ;</i> POL. <i>30, 13, 10 ; avec un rég</i>. ἐσθῆτα, PLUT. <i>Rom. 16 ;</i> τήϐεννον, PLUT. <i>Cor. 9,</i> mettre son vêtement, sa toge ; λουτρίδα, THPP. COM. <i>2, 807,</i> mettre un caleçon de bain ; <i>fig</i>. τινα, AR. <i>Pax 687,</i> se couvrir de qqn, d’un ordre <i>ou</i> de la responsabilité de qqn ;<br><b>      2</b> <i>abs</i>. se ceindre d’un tablier, mettre son tablier, ANAXANDR. ALEX. HÉGÉSANDRE (ATH. <i>131</i> b, <i>170</i> c, <i>340</i> f).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιζωννυμι - περιζώννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4025":"<h1>perithesis</h1>\n<p>Strong n° 4025 <i>Prononciation [per-ith'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action de poser autour</li>\n<li>les ornements constitués de bijoux en or et qui sont placés autour de la tête ou du corps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περίθεσις, εως (ἡ)</b> action de placer autour, NT. <i>1Petr. 3, 3 ;</i> SEXT. <i>P. 2, 15</i>.<br><span><b>Étym</b>. περιτίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιθεσις - περίθεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4026":"<h1>periistemi</h1>\n<p>Strong n° 4026 <i>Prononciation [per-ee-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se placer autour de quelqu'un</li>\n<li>se tenir autour\n<ol type=\"a\">\n<li>se détourner dans le but d'éviter quelque chose</li>\n<li>éviter, fuir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ΐστημι :<br>A</b> <i>tr. (prés., impf., fut., ao.1</i> περιέστησα) :<br><b>   I</b> placer, mettre, établir autour : τινί τι, PLAT. <i>Tim. 78</i> e, placer une chose autour d’une autre ; τινὶ τὰ θηρία, POL. <i>1, 85, 7,</i> disposer des éléphants de manière à cerner une troupe ; <i>avec</i> περί <i>et l’acc. :</i> στράτευμα περὶ τὴν πόλιν, XÉN. <i>Cyr. 7, 5, 1,</i> disposer une armée autour d’une ville (pour l’assiéger) ; <i>fig</i>. κακά τινι, DÉM. <i>555, 5,</i> faire du mal à qqn de tous les côtés ; μεγίστους κινδύνους τινί, POL. <i>12, 15, 7,</i> faire naître les plus grands dangers autour de qqn, faire courir à qqn les plus grands dangers ;<br><b>   II</b> faire tourner, <i>fig. càd. :</i><br><b>      1</b> convertir : εἰς τοὐναντίον τινὰ τῷ λόγῳ, PLAT. <i>Ax. 370</i> d, amener qqn, en conversant, à une opinion contraire ; εἰς μοναρχίαν πολίτευμα, POL. <i>3, 8, 2,</i> changer un gouvernement en monarchie ;<br><b>      2</b> tourner vers, diriger vers : λόγον εἰς ζήτησιν αἰτίας, PLUT. <i>M. 673</i> c, amener peu à peu un discours à une recherche de cause ; τινὰ εἰς πενίαν, HDN <i>7, 3, 12,</i> réduire qqn au besoin ;<br><b>      3</b> détourner sur, reporter sur, faire retomber sur : τὴν αἰτίαν π. εἴς τινα, DH. <i>3, 3,</i> faire retomber sur qqn la faute de qqn ; τὰς αὑτοῦ συμφορὰς εἴς τινα, DÉM. <i>1014, 7,</i> faire retomber sur qqn la cause de ses propres malheurs, les imputer à qqn ;<br><b>B</b> <i>intr. (à l’ao.2</i> περιέστην, <i>au pf</i>. περιέστηκα, <i>au pass. et au moy</i>.) :<br><b>      1</b> se dresser autour, se tenir autour, IL. <i>4, 532 ;</i> EUR. <i>Bacch. 1104 ;</i> κῦμα περιστάθη, OD. <i>11, 243,</i> une vague se dressa autour ; <i>avec</i> περί <i>et l’acc</i>. PLAT. <i>Tim. 84</i> e ; <i>avec l’acc. :</i> πολλὸς χορὸν περιΐσταθ' ὅμιλος, IL. <i>18, 603,</i> une foule nombreuse se tenait autour du chœur de danse ; π. βωμόν, ESCHL. <i>fr. 395,</i> se tenir autour de l’autel ; π. τι κύκλῳ, HDT. <i>1, 43,</i> entourer qqe ch. en cercle ;<br><b>      2</b> <i>avec idée d’hostilité,</i> entourer, cerner : τινα, IL. <i>17, 95 ;</i> OD. <i>20, 50,</i> qqn pour l’attaquer ; <i>de même,</i> cerner un gibier, XÉN. <i>Cyn. 8, 6, 8, 10, 14 ;</i> λόφον στρατεύματι, XÉN. <i>Cyr. 3, 1, 5,</i> cerner la colline avec une armée ; <i>fig. en parl. d’une crainte, d’un danger, d’une nécessité,</i> presser <i>ou</i> menacer : τινι, THC. <i>1, 76 ;</i> DÉM. <i>450, 13, etc. ;</i> τινα, THC. <i>3, 55, 4, 10 ;</i> DÉM. <i>30, 24 ; 293, 14, etc</i>. qqn ; τὰ περιεστηκότα πράγματα, LYS. <i>193, 36,</i> l’état fâcheux des affaires ; οἱ περιεστῶτες καιροί, POL. <i>3, 86, 7,</i> les circonstances fâcheuses ;<br><b>      3</b> se tourner, se transformer, se modifier : ἡ περιϊσταμένη ὥρη, HPC. <i>227, 47,</i> les vicissitudes du temps, le cours du temps ; περιϊσταμένης ὥρας, TH. <i>C.P. 2, 11, 2,</i> dans le cours du temps, <i>p. suite,</i> passer d’une situation dans une autre, d’un état dans un autre ; <i>d’ord. en mauv. part ;</i> ἔκ τινος ἀρρωστίης π. ἐς ὕδερον, HPC. <i>194</i> c, passer d’un certain état de faiblesse à un état d’hydropisie ; <i>d’où</i> aboutir à : τοὐναντίον περιέστη αὐτῷ, THC. <i>6, 24,</i> l’événement tourna contrairement à ce qu’il pensait ; ἐνταῦθα τὰ πράγματα περιέστηκε, ISOCR. <i>111</i> b, voilà où en sont venues les affaires ; <i>avec un part</i>. περιέστηκεν ἡ πρότερον σωφροσύνη νῦν ἀϐουλία φαινομένη, THC. <i>1, 32,</i> notre circonspection d’autrefois s’est transformée et se montre maintenant de l’irréflexion ; περιέστηκεν εἰς τοῦτο ὥστε, LYCURG. <i>148, 10,</i> la chose en est venue à ce point que, <i>etc. ; avec la propos. inf</i>. PLAT. <i>Menex. 244</i> d ; DÉM. <i>301, 8, etc. ;</i><br><b>      4</b> se détourner pour éviter ; λυττῶντας κύνας, LUC. <i>Herm. 86,</i> des chiens enragés ; κίνδυνον, JAMBL. <i>V. Pyth. § 239,</i> un danger ; <i>cf</i>. NT. <i>2Tim. 2, 16 ;</i> ARTÉM. <i>4, 59 ;</i> SEXT. <i>p. 708, 712 ;</i> M. ANT. <i>3, 4, etc. ; ttef. cet usage est blâmé par</i> LUC. <i>Sol. 5 ; p. suite,</i> craindre, <i>avec</i> μή <i>et le sbj</i>. JOS. <i>A.J. 4, 6, 12 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. περιστήσομαι)</span><br><b>      1 <i>tr.</i></b> faire se tenir autour de soi, placer autour de soi : κύκλον ξυστοφόρων, XÉN. <i>Cyr. 7, 5, 41,</i> un cercle d’hommes armés de bâtons ; <i>cf</i>. APP. <i>Civ. 3, 4 ;</i><br><b>      2 <i>intr.</i></b> se tourner, aboutir à : εἰς ἕνα περιστήσεται τὸ κράτος, PLUT. <i>Per. 6,</i> le pouvoir passera aux mains d’un seul.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao.2 sbj. 3 pl. épq</i>. περιστήωσι (<i>var</i>. περιστείωσι) <i>p</i>. περιστῶσι, IL. <i>17, 95 ; opt. 3 sg</i>. περισταῖεν, OD. <i>20, 50 ; pf. 2 sg</i>. περιέστακας <span>[τᾰ]</span> PLAT. <i>Ax. 370</i> d ; <i>pf.2 part. neutre</i> περιεστός, ARSTT. <i>Meteor. 4, 1 ; ao. pass. 3 sg. poét</i>. περιστάθη, OD. <i>11, 243</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιιστημι - περιΐστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4027":"<h1>perikatharma</h1>\n<p>Strong n° 4027 <i>Prononciation [per-ee-kath'-ar-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venant du nettoyage, déchet, ordure</li>\n<li>métaph.\n<ol type=\"a\">\n<li>les hommes les plus méprisables et abjects</li>\n<li>le prix des expiations ou de la rédemption, car les Grecs appliquaient le terme « katharmata » aux victimes sacrifiées pour l'expiation du peuple, et même aux criminels entretenus par les fonds publics, et qui pouvaient être offerts en sacrifice pour faire une expiation pour l'état, au commencement d'une peste ou autre calamité.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περικάθαρμα, ατος (τὸ)</b> <span>[κᾰ]</span><br><b>      1</b> purification, expiation, SPT. <i>Prov. 21, 18 ;</i><br><b>      2</b> objet de purification, NT. <i>1Cor. 4, 13 ; d’où</i> homme <i>ou</i> être impur, ARR. <i>Epict. 3, 22, 78</i>.<br><span><b>Étym</b>. περικαθαίρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικαθαρμα - περικάθαρμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4028":"<h1>perikalupto</h1>\n<p>Strong n° 4028 <i>Prononciation [per-ee-kal-oop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couvrir tout autour, recouvrir, voiler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·καλύπτω</b> <span>[ᾰ]</span> cacher en enveloppant, envelopper : τί τινι, HDT. <i>4, 23,</i> envelopper une chose d’une autre ; <i>particul</i>. ensevelir un mort, PLUT. <i>Cleom. 38 ;</i> ἐν ἱματίῳ, XÉN. <i>Cyr. 7, 3, 13,</i> dans un vêtement ; <i>fig</i>. π. τὰ πάθη, PLUT. <i>M. 101</i> a ; τὸ δεινόν, PLUT. <i>M. 1013</i> e, voiler, dissimuler des passions, le caractère étrange de qqe ch. ; τοῖσι πράγμασι σκότον, EUR. <i>Ion 1522,</i> jeter sur les affaires un voile d’obscurité ;<br><b><i>Moy.</i></b> s’envelopper, se couvrir, PLUT. <i>M. 247</i> c ; <i>fig</i>. τινι, PLUT. <i>M. 51</i> d, de qqe. ch., <i>càd</i>. se dissimuler sous qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικαλυπτω - περικαλύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4029":"<h1>perikeimai</h1>\n<p>Strong n° 4029 <i>Prononciation [per-ik'-i-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se trouver autour</li>\n<li>être entouré de, avoir autour de soi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περί·κειμαι :<br>   I <i>intr. :</i><br>      1</b> être étendu autour et tenir embrassé, <i>dat</i>. IL. <i>19, 4 ; abs</i>. être jeté, répandu çà et là, PLUT. <i>Them. 18 ;</i><br><b>      2</b> s’étendre autour, entourer : τεῖχος περίκειται, HÉS. <i>Th. 733,</i> un mur s’étend autour ; <i>avec le dat</i>. γωρυτὸς τόξῳ περίκειτο, OD. <i>21, 54,</i> un étui entourait l’arc ; <i>avec le gén</i>. τὰ τῆς θεοῦ περικείμενα χρυσία, THC. <i>2, 13,</i> l’or suspendu <i>ou</i> appliqué à la statue de la déesse ; <i>abs</i>. περικείμεναι πόλεις, HDN <i>3, 4, 11, etc</i>. villes situées alentour ; <i>fig</i>. s’attacher à, <i>avec le dat</i>. PLUT. <i>Dio. 56 ; ou avec l’acc</i>. LUC. <i>Astr. 10 ;</i><br><b>      3</b> être de reste : οὔ τι μοι περίκειται, IL. <i>9, 321,</i> il ne me reste rien, je n’ai rien gagné ;<br><b>   II</b> <i>pass</i>. être entouré, enveloppé : στέφανους, PLUT. <i>Arat. 17,</i> de couronnes ; τιάρας, STR. <i>733,</i> de tiares ; π. τελαμῶνας περὶ τοῖσι αὐχέσι, HDT. <i>1, 171,</i> porter des baudriers suspendus autour du cou ; <i>fig</i>. περικείμενος ὕϐριν, THCR. <i>Idyl. 23, 14,</i> enveloppé d’insolence ; <i>en ce sens, surt. au part. (v. ci-dessus), qqf. aux autres modes (ind</i>. NT. <i>Ap. 28, 20 ; impér</i>. ANTH. <i>11, 38 ; impf</i>. HDN <i>3, 5, 11 ; 5, 4, 12</i>).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικειμαι - περίκειμαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4030":"<h1>perikephalaia</h1>\n<p>Strong n° 4030 <i>Prononciation [per-ee-kef-al-ah'-yah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un casque</li>\n<li>métaph.\n<ol type=\"a\">\n<li>la protection de l'âme qui consiste dans l'espérance du salut</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·κεφάλαιος, α, ον</b> <span>[φᾰ]</span> qui entoure la tête, <i>d’où :</i><br><b>   I</b> ἡ περικεφαλαία :<br><b>      1</b> casque, POL. <i>3, 71, 4 ;</i><br><b>      2</b> maladie des porcs dans la région de la tête, TH. <i>H.P. 3, 8, 7 ;</i><br><b>      3</b> partie de la quille d’un navire, TH. <i>H.P. 3, 13, 4 ;</i><br><b>   II</b> τὸ περικεφάλαιον, casque, POL. <i>6, 22, 3</i>.<br><span><b>Étym</b>. π. κεφαλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικεφαλαια - περικεφαλαία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4031":"<h1>perikrates</h1>\n<p>Strong n° 4031 <i>Prononciation [per-ee-krat-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ayant un pouvoir sur une chose, qui est maître</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περικρατής, ής, ές</b> <span>[ᾰ]</span><br><b>      1</b> qui commande souverainement à, <i>gén</i>. NT. <i>Ap. 27, 16 ;</i><br><b>      2</b> qui maîtrise, <i>gén</i>. CHRYS.<br><span><b>Étym</b>. περικρατής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικρατης - περικρατής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4032":"<h1>perikrupto</h1>\n<p>Strong n° 4032 <i>Prononciation [per-ee-kroop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dissimuler de tous côtés ou entièrement, cacher, écarter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·κρύπτω</b>, cacher tout autour <i>ou</i> avec soin, LUC. <i>D. mort. 10, 8, etc. ;</i><br><b><i>Moy.</i></b> se cacher à, <i>acc</i>. DL. <i>6, 61</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικρυπτω - περικρύβω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4033":"<h1>perikukloo</h1>\n<p>Strong n° 4033 <i>Prononciation [per-ee-koo-klo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>encercler, entourer, investir\n<ol type=\"a\">\n<li>d'une cité (assiégée)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·κυκλόω-ῶ :<br>      1 <i>tr.</i></b> entourer comme d’un cercle, envelopper, ARSTT. <i>H.A. 4, 8, 11 ;</i> SPT. <i>Gen. 19, 4 ;</i><br><b>      2 <i>intr.</i></b> aller autour, LUC. <i>Oc. 63 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. HDT. <i>8, 78 ;</i> XÉN. <i>An. 6, 3, 11, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περικυκλοω - περικυκλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4034":"<h1>perilampo</h1>\n<p>Strong n° 4034 <i>Prononciation [per-ee-lam'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>briller, illuminer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·λάμπω :<br>      1 <i>intr.</i></b> briller tout autour <i>ou</i> d’un vif éclat, PLUT. <i>Cam. 17, Arat. 21, etc. ;</i><br><b>      2 <i>tr.</i></b> illuminer, <i>acc</i>. PLUT. <i>Cic. 35 ;</i> NT. <i>Ap. 26, 13, etc. ; au pass</i>. PLUT. <i>Per. 39, etc. ;</i> LUC. <i>Dom. 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιλαμπω - περιλάμπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4035":"<h1>perileipo</h1>\n<p>Strong n° 4035 <i>Prononciation [per-ee-li'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>laisser là</li>\n<li>rester, survivre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·λείπομαι</b> (<i>seul. prés</i>.) être de reste, survivre, HDT. <i>1, 82 ;</i> EUR. <i>Hel. 426 ;</i> AR. <i>Nub. 725 ;</i> PLAT. <i>Tim. 23</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιλειπω - περιλείπομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G4036":"<h1>perilupos</h1>\n<p>Strong n° 4036 <i>Prononciation [per-il'-oo-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>très triste, extrêmement affligé</li>\n<li>vaincu par la douleur jusqu'à en mourir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περί·λυπος, ος, ον</b> <span>[ῡ]</span> très triste, affligé, HPC. <i>390, 53 ;</i> ISOCR. <i>11</i> b ; ARSTT. <i>Nic. 4, 3, 18</i>.<br><span><b>Étym</b>. π. λύπη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιλυπος - περίλυπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4037":"<h1>perimeno</h1>\n<p>Strong n° 4037 <i>Prononciation [per-ee-men'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>attendre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·μένω :<br>   I</b> attendre : <i>avec un suj. de pers. :</i><br><b>      1</b> <i>propr</i>. attendre : τινά, HDT. <i>4, 89 ;</i> THC. <i>5, 64 ;</i> AR. <i>Pl. 643, etc</i>. attendre qqn ; τι, AR. <i>fr. 344, 8 Dind. ;</i> PLAT. <i>Phæd. 116</i> a, <i>etc</i>. attendre qqe ch. ; π. ἕως <i>et le fut</i>. XÉN. <i>Cyr. 7, 5, 39 ; ou l’opt</i>. PLAT. <i>Phæd. 59</i> d ; μέχρι τούτου ἕως ἄν, DÉM. <i>113, 7 ;</i> ἄχρι ἄν, XÉN. <i>An. 2, 3, 2 ;</i> ἔστ' ἄν, LUC. <i>Herm. 40,</i> attendre que, jusqu’à ce que ; <i>avec l’inf</i>. attendre de, PLAT. <i>Theæt. 173</i> c ; <i>avec la prop. inf</i>. attendre que, PLAT. <i>Rsp. 375</i> c ;<br><b>      2</b> attendre patiemment, supporter, <i>acc</i>. LUC. <i>Abd. 28 ;</i> μακρὰ λέγοντας, PLAT. <i>Leg. 890</i> e, écouter patiemment de longs discoureurs ;<br><b>   II</b> <i>avec un suj. de chose :</i><br><b>      1</b> attendre, PLUT. <i>Cæs. 17 ;</i><br><b>      2</b> s’attendre à, présumer, <i>acc</i>. PLUT. <i>M. 136</i> e ;<br><b>      3</b> être réservé à, <i>acc</i>. SOPH. <i>Ant. 1296 ;</i> PLAT. <i>Rsp. 365</i> a.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιμενω - περιμένω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4038":"<h1>perix</h1>\n<p>Strong n° 4038 <i>Prononciation [per'-ix]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tout autour : les cités voisines</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέριξ</b>, <i>adv. et prép. :</i><br><b>   I</b> <i>adv</i>., tout autour, alentour, ESCHL. <i>Pers. 418 ;</i> SOPH. <i>Ant. 1286 ;</i> EUR. <i>Andr. 265 ;</i> HDT. <i>5, 115, etc. ;</i> THC. <i>6, 90 ;</i> PLAT. <i>Tim. 62</i> d, <i>etc. ;</i><br><b>   II</b> <i>prép</i>. autour de :<br><b>      1</b> <i>avec le gén. et dev. son rég</i>. HDT. <i>1, 179, etc. ;</i> XÉN. <i>An. 7, 8, 12, etc. ;</i><br><b>      2</b> <i>rar. avec le dat</i>. EUR. <i>Ph. 710 ;</i><br><b>      3</b> <i>avec l’acc. et dev. son rég</i>. HDT. <i>1, 196, etc. ; poét. et qqf. en prose ion. après son rég</i>. ESCHL. <i>Pers. 368 ;</i> EUR. <i>H.f. 243 ;</i> HDT. <i>4, 52, 79,</i> autour de.<br><span><b>Étym</b>. περί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιξ - πέριξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4039":"<h1>perioikeo</h1>\n<p>Strong n° 4039 <i>Prononciation [per-ee-oy-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demeurer tout autour, être voisin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·οικέω-ῶ</b>, habiter autour de, dans le voisinage de, <i>acc</i>. HDT. <i>1, 57 ; 2, 112, etc. ;</i> XÉN. <i>An. 5, 6, 16 ;</i> LYS. <i>110, 40</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιοικεω - περιοικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4040":"<h1>perioikos</h1>\n<p>Strong n° 4040 <i>Prononciation [per-ee'-oy-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demeurant autour, un voisin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περί·οικος, ος, ον :<br>      1</b> qui habite alentour, aux environs, voisin, HDT. <i>4, 159 ;</i> ὁ περίοικος, habitant du voisinage, voisin, HDT. <i>1, 175 ; 4, 161 ;</i> THC. <i>1, 101, etc. ;</i> οἱ περίοικοι, habitants libres d’une ville laconienne autre que Sparte, <i>d’où :</i> les Lacédémoniens proprement dits, <i>p. opp. aux Spartiates d’une part, aux Hilotes et aux Néodamodes de l’autre dans les villes de Laconie,</i> HDT. <i>6, 58 ; 9, 11 ;</i> THC. <i>8, 6 et 22 ; à Argos,</i> ARSTT. <i>Pol. 5, 2 ; en Crète,</i> ARSTT. <i>Pol. 2, 10 ;</i><br><b>      2</b> <i>t. de géogr</i>. οἱ π. habitants de la zone tempérée, sous le méridien opposé au nôtre, <i>p. opp. à</i> ἄντοικοι <i>et à</i> ἀντίποδες, CLÉOM. <i>1, 2 ;</i> GÉM. <i>El. astr. 16, 1</i>.<br><span><b>Étym</b>. π. οἶκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιοικος - περίοικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4041":"<h1>periousios</h1>\n<p>Strong n° 4041 <i>Prononciation [per-ee-oo'-see-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est son propre bien, appartenant à ses possessions\n<ol type=\"a\">\n<li>un peuple choisi par Dieu parmi les autres nations pour sa propre possession</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ούσιος, ος, ον</b>, élu, choisi, NT. <i>Tit. 2, 14</i>.<br><span><b>Étym</b>. π. οὐσία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιουσιος - περιούσιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4042":"<h1>perioche</h1>\n<p>Strong n° 4042 <i>Prononciation [per-ee-okh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un entourage, un environnement, un circuit</li>\n<li>ce qui est contenu\n<ol type=\"a\">\n<li>le contenu de toute écriture</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περιοχή, ῆς (ἡ) :<br>   I</b> <i>act</i>. ce qui entoure :<br><b>      1</b> enveloppe d’un corps, DS. <i>1, 91 ; d’où</i> pourtour, PLUT. <i>M. 892</i> e, <i>etc. ; p. ext</i>. étendue, développement, DS. <i>17, 58 au plur. ;</i><br><b>      2</b> écorce d’un fruit, TH. <i>C.P. 1, 17, 5 ; 1, 19, 2 ;</i><br><b>      3</b> alentours <i>ou</i> environs d’un lieu, HLD. <i>2, 26 ;</i><br><b>      4</b> travaux de fortification <i>ou</i> d’investissement, SPT. <i>1Reg. 22, 4, etc. ;</i><br><b>   II</b> <i>pass</i>. ce qui est entouré :<br><b>      1</b> corps <i>ou</i> masse, PLUT. <i>Lys. 12 ;</i><br><b>      2</b> contenu d’un livre, <i>particul</i>. passage d’un écrit, CIC. <i>Att. 13, 25 ;</i> NT. <i>Ap. 8, 32 ; ou</i> sommaire indiquant le contenu, SCH.-THC. <i>1, 31</i>.<br><span><b>Étym</b>. περιέχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιοχη - περιοχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4043":"<h1>peripateo</h1>\n<p>Strong n° 4043 <i>Prononciation [per-ee-pat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marcher\n<ol type=\"a\">\n<li>être en chemin, progresser; faire bon usage des opportunités</li>\n<li>terme Hébreu pour vivre\n<ol>\n<li>régler sa vie</li>\n<li>se conduire</li>\n</ol>\n</li>\n<li>aller et venir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·πατέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> circuler, aller et venir, se promener, XÉN. <i>Mem. 3, 13, 5 ;</i> PLAT. <i>Euthyd. 273</i> a ; AR. <i>Eq. 744, etc. ; particul</i>. se promener en conversant (<i>v</i>. περιπατητικός) DL. <i>7, 109 ;</i> PLUT. <i>M. 796</i> d ; εἴς τινα, PHILSTR. <i>21, 302,</i> avec qqn (<i>propr</i>. en s’adressant à qqn) ;<br><b>      2</b> <i>p. ext. fig</i>. se comporter, se conduire, vivre de telle <i>ou</i> telle manière, NT. <i>Marc. 7, 5 ; 2Thess. 3, 6, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιπατεω - περιπατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n95 fois dans 89 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (10)</li>\n<li>Luc (5)</li>\n<li>Jean (17)</li>\n<li>Actes (8)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (4)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (5)</li>\n<li>2 Jean (3)</li>\n<li>3 Jean (2)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G4044":"<h1>peripeiro</h1>\n<p>Strong n° 4044 <i>Prononciation [per-ee-pi'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>percer à travers</li>\n<li>métaph. torturer l'âme par des douleurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·πείρω</b> <span>(<i>f</i>. -περῶ, <i>ao.2 pass</i>. περιεπάρην <span>[ᾰ]</span> <i>etc</i>.)</span> percer de part en part, transpercer :<br><b>      1</b> <i>avec l’acc. de l’objet transpercé :</i> τῷ ἀγκίστρῳ, PLUT. <i>Ant. 29,</i> transpercer avec l’hameçon ; <i>fig</i>. ἑαυτὸν ὀδύναις, NT. <i>1Tim. 6, 10,</i> transpercer son propre cœur de douleurs ; <i>au pass</i>. EL. <i>N.A. 7, 48, etc. ;</i><br><b>      2</b> <i>avec l’acc. de l’objet qui transperce :</i> ὀδόντας τῇ δείρῃ, LIB. <i>4, 1081,</i> enfoncer ses dents dans le cou ; τὴν κεφαλὴν περὶ λόγχην, PLUT. <i>Galb. 27,</i> ficher sur une lance la tête de qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιπειρω - περιπείρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4045":"<h1>peripipto</h1>\n<p>Strong n° 4045 <i>Prononciation [per-ee-pip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>comme tomber au milieu et être environné, tomber entre les mains de</li>\n<li>tomber sur un endroit, s'échouer (en parlant d'un navire)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·πίπτω</b> <span>(<i>f</i>. περιπεσοῦμαι, <i>ao.2</i> περιέπεσον, <i>etc</i>.)</span><br><b>   I</b> tomber à droite et à gauche, <i>en parl. des deux parties d’un objet coupé,</i> PLUT. <i>Pyrrh. 24 ;</i><br><b>   II</b> tomber <i>ou</i> verser sur le côté, PLUT. <i>Ant. 67 ;</i> LUC. <i>As. 29, etc. ;</i><br><b>   III</b> tomber autour de <i>ou</i> sur : ξίφει, AR. <i>Vesp. 523,</i> se jeter sur une épée ; τινί, XÉN. <i>An. 1, 8, 28 ; ou</i> ἐπί τινι, PLUT. <i>Crass. 17,</i> se jeter sur qqn ; ἐν σφισὶ περιπεσόντες, THC. <i>2, 65,</i> s’étant attaqués eux-mêmes, s’étant fait du tort par leurs divisions ; <i>fig. :</i><br><b>      1</b> se heurter à, <i>avec le dat</i>. PLUT. <i>Them. 15, ou</i> περί <i>et l’acc</i>. HDT. <i>8, 16,</i> à qqe obstacle ; τοῖς ἑαυτοῦ λόγοις, ESCHN. <i>47, 13 ; ou</i> ἑαυτῷ, LUC. <i>D. mort. 26, 2,</i> se heurter à ses propres paroles, <i>càd</i>. se contredire <i>ou</i> se donner à soi-même un démenti ;<br><b>      2</b> rencontrer par hasard, à l’improviste, tomber sur, <i>dat</i>. HDT. <i>6, 105 ;</i> THC. <i>8, 103 ;</i> XÉN. <i>An. 7, 3, 38 ;</i> ἀδίκοισι γνώμῃσι, HDT. <i>1, 96,</i> être atteint par un jugement inique ; συμφοραῖς, PLAT. <i>Leg. 877</i> c, <i>ou</i> ἐπὶ συμφορήν, HDT. <i>7, 88,</i> tomber dans le malheur ; <i>abs</i>. POL. <i>8, 2, 4 ; avec un nom de chose pour sujet :</i> ἤν μοί τι περιπίπτῃ κακόν, AR. <i>Th. 271,</i> s’il me survient qqe malheur.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιπιπτω - περιπίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4046":"<h1>peripoieomai</h1>\n<p>Strong n° 4046 <i>Prononciation [per-ee-poy-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>constituer une réserve</li>\n<li>réserver, laisser ou garder sauf</li>\n<li>se réserver</li>\n<li>se préserver pour son usage</li>\n<li>obtenir pour soi-même, acheter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ποιέω-ῶ :<br>   I</b> faire survivre, <i>d’où</i> sauver, conserver, <i>acc</i>. HDT. <i>3, 36, etc. ;</i> THC. <i>2, 25, etc. ;</i> τινα ἐκ κακῶν, LYS. <i>107, 22, etc</i>. sauver qqn du malheur ;<br><b>   II</b> procurer un surplus, <i>d’où :</i><br><b>      1</b> mettre de côté, épargner, économiser, XÉN. <i>Œc. 2, 10 ; 11, 10 ;</i><br><b>      2</b> <i>p. ext</i>. procurer, fournir : τινί τι, DÉM. <i>193, 20,</i> procurer qqe ch. à qqn ; αἰσχύνην τινί, ISOCR. <i>150</i> e, faire honte à qqn ; ἑαυτῷ τι, ESCHN. <i>54, 12 ; ou</i> ἐς ἑαυτόν, THC. <i>8, 48,</i> se procurer qqe ch. à soi-même ; <i>particul</i>. approprier, <i>au pass</i>. être disposé pour, approprié à, TH. <i>H.P. 9, 3, 4 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> conserver pour soi-même : τὰς ψυχάς, XÉN. <i>Cyr. 4, 4, 10,</i> sauver leur propre vie ; ἀπ' ὀλίγων, XÉN. <i>Mem. 4, 2, 38,</i> se réserver, mettre de côté pour soi, épargner avec peu de ressources, faire des économies avec une petite fortune ; π. τι παρά τινος, DÉM. <i>164, 9,</i> se procurer une chose avec une autre ; περιποιεῖσθαι δύναμιν, THC. <i>1, 9,</i> se procurer de la puissance ;<br><b>      2</b> procurer, fournir, <i>en gén. :</i> τινι δυναστείαν, ARSTT. <i>Pol. 3, 16,</i> procurer à qqn le souverain pouvoir.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιποιεομαι - περιποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4047":"<h1>peripoiesis</h1>\n<p>Strong n° 4047 <i>Prononciation [per-ee-poy'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une réserve, une conservation, salut</li>\n<li>possession, sa propre propriété</li>\n<li>une acquisition</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περιποίησις, εως (ἡ) :<br>      1</b> action de sauver d’un danger, conservation, PLAT. <i>Def. 415</i> c ; SPT. <i>2Par. 14, 13 ;</i> NT. <i>Hebr. 10, 39 ;</i><br><b>      2</b> acquisition, NT. <i>1Thess. 5, 9 ; 2, 2 et 14 ; d’où</i> possession, NT. <i>1Petr. 2, 9</i>.<br><span><b>Étym</b>. περιποιέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιποιησις - περιποίησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4048":"<h1>perirrhegnumi</h1>\n<p>Strong n° 4048 <i>Prononciation [per-ir-hrayg'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briser de tous côtés, rompre tout autour</li>\n<li>déchirer ou arracher entièrement, de toute part</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·ρρήγνυμι</b> <span>(<i>f</i>. -ρρήξω, <i>ao</i>. -έρρηξα, <i>pf.2 au sens intr</i>. -έρρωγα)</span> briser <i>ou</i> déchirer autour : τι, PLAT. <i>Criti. 113</i> d, briser qqe ch. tout autour ; σκαφίδιον πρὸς πέτραν, LUC. <i>M. cond. 2,</i> briser une barque contre une roche ; τὸν Νεῖλον περὶ τὴν χώραν, ISOCR. <i>227</i> d, briser, <i>càd</i>. séparer en deux branches le cours du Nil pour envelopper le pays ; <i>en parl. de vêtements,</i> déchirer, <i>acc</i>. ESCHL. <i>Sept. 329 ;</i> DÉM. <i>403, 3 ;</i> POL. <i>15, 33, 4, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1 <i>tr.</i></b> déchirer sur soi : πέπλον, PLUT. <i>Ant. 77,</i> son vêtement ; <i>abs</i>. déchirer son vêtement, ARR. <i>An. 7, 24, 5 ;</i> JOS. <i>A.J. 9, 7, 3, etc. ;</i><br><b>      2 <i>intr.</i></b> se briser autour, <i>d’où</i> éclater autour, ARSTT. <i>H.A. 5, 19, etc. ; 6, 29, etc. ; en parl. de la foudre,</i> PLUT. <i>Crass. 19 ; particul. en parl. d’un fleuve,</i> se diviser en deux <i>ou</i> plusieurs branches, HDT. <i>2, 16 ;</i> EL. <i>N.A. 7, 24</i>.<br><span><b>Étym</b>. π. ῥήγνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιρρηγνυμι - περιρήγνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4049":"<h1>perispao</h1>\n<p>Strong n° 4049 <i>Prononciation [per-ee-spah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>distraire, affoler</li>\n<li>métaph.\n<ol type=\"a\">\n<li>être conduit mentalement, être distrait</li>\n<li>être très occupé, trop occupé d'une chose, absorbé, affairé, être tiraillé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·σπάω-ῶ :<br>   I</b> tirer autour, <i>particul. :</i><br><b>      1</b> <i>t. de tact</i>. faire faire une conversion à droite <i>ou</i> à gauche, <i>particul</i>. faire obliquer deux fois, POL. <i>1, 76, 5 ;</i><br><b>      2</b> ôter en tirant autour de soi : ξίφος, EUR. <i>I.T. 296,</i> une épée ; χλαμύδιον, DS. <i>19, 9,</i> une petite chlamyde ;<br><b>   II</b> tirer <i>ou</i> entraîner d’un autre côté : τινα, DS. <i>20, 3 ;</i> PLUT. <i>Fab. 22,</i> qqn (l’ennemi) ; τὸν ἐντὸς τείχους θόρυϐον ἐπὶ τοὺς ἔξω πολέμους, DH. <i>6, 23,</i> détourner l’agitation intérieure et la diriger vers les guerres du dehors ; τὸν ἀργὸν δῆμον περὶ τὰς στρατείας, DH. <i>9, 43,</i> entraîner le peuple oisif vers les expéditions ; τινα πρὸς ἑαυτόν, NT. <i>Luc. 13, 40,</i> attirer qqn à soi ; <i>fig</i>. distraire l’attention, occuper par une diversion <i>ou</i> une distraction, <i>acc</i>. POL. <i>9, 22, 5 ;</i> PLUT. <i>Cam. 9 ; abs</i>. PLUT. <i>M. 160</i> c ; <i>au pass</i>. avoir l’esprit occupé ailleurs, POL. <i>4, 10, 3, etc. ;</i><br><b>   III</b> <i>t. de gr</i>. tirer en sens contraire, <i>d’où</i> περισπᾶν συλλαϐήν, PLUT. <i>Thes. 26,</i> prononcer une syllabe avec l’accent circonflexe ; <i>particul</i>. prononcer la dernière syllabe d’un mot avec l’accent circonflexe, TRYPH. (ATH. <i>397</i> e) ; <i>au pass</i>. être marqué de l’accent circonflexe sur la dernière syllabe, DH. <i>Comp. 11 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> ôter d’autour de : τιάραν, XÉN. <i>Cyr. 3, 1, 13,</i> ôter la tiare de sa tête ;<br><b>      2</b> tourner autour de soi (ses regards) <i>acc</i>. LUC. <i>D. deor. 20, 11</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισπαω - περισπάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4050":"<h1>perisseia</h1>\n<p>Strong n° 4050 <i>Prononciation [per-is-si'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abondance, surabondamment, d'une façon superflue</li>\n<li>supériorité, préférence, prééminence</li>\n<li>gain, profit</li>\n<li>résidus, restes : la méchanceté qui reste dans un Chrétien et qui provient de son état antérieur à sa conversion</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσεία, ας (ἡ) :<br>      1</b> supériorité, SPT. <i>Eccl. 1, 3 ;</i><br><b>      2</b> abondance excessive, superflu, NT. <i>2Cor. 8, 2</i>.<br><span><b>Étym</b>. περισσεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσεια - περισσεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4051":"<h1>perisseuma</h1>\n<p>Strong n° 4051 <i>Prononciation [per-is'-syoo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abondance, dans laquelle on se complaît\n<ol type=\"a\">\n<li>de ce qui remplit le cœur</li>\n</ol>\n</li>\n<li>ce qui est laissé de côté, reste, résidu, reliquat, reliefs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περίσσευμα</b>, <i>att</i>. <b>περίττευμα, ατος (τὸ) :<br>   I</b> ce qui est en plus, <i>d’où :</i><br><b>      1</b> surplus, reste, NT. <i>Marc. 8, 8 ;</i><br><b>      2</b> excrément, PLUT. <i>M. 962</i> e ;<br><b>   II</b> ce qui est en trop, excès, surabondance, ARSTT. <i>fr. 259 ;</i> NT. <i>Matth. 12, 34, etc</i>.<br><span><b>Étym</b>. περισσεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσευμα - περίσσευμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4052":"<h1>perisseuo</h1>\n<p>Strong n° 4052 <i>Prononciation [per-is-syoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>excéder un nombre fixé de mesure, être laissé et mis de côté au dessus d'un certain nombre ou d'une certaine mesure\n<ol type=\"a\">\n<li>être en plus, rester</li>\n<li>exister ou être en abondance\n<ol>\n<li>être grand (abondant)</li>\n<li>chose qui vient en abondance, ou déborde sur quelqu'un, quelque chose qui arrive dans une large mesure</li>\n<li>qui redouble</li>\n</ol>\n</li>\n<li>abonder, déborder\n<ol>\n<li>être abondamment fourni de, avoir en abondance, une chose qui abonde</li>\n<li>être prééminent, exceller</li>\n<li>exceller encore plus, excéder</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>faire abonder\n<ol type=\"a\">\n<li>fournir quelqu'un richement pour qu'il soit dans l'abondance</li>\n<li>rendre abondant ou excellent</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσεύω</b>, <i>att</i>. <b>περιττεύω</b> <span>(<i>impf</i>. ἐπερίσσευον, <i>ao</i>. ἐπερίσσευσα, <i>pf. inus</i>.)</span><br><b>A <i>intr</i>.<br>   I</b> être en plus :<br><b>      1</b> <i>avec un suj. de pers</i>. être plus nombreux, <i>d’où</i> déborder (les ailes d’une armée) <i>gén</i>. XÉN. <i>An. 4, 8, 11 ;</i><br><b>      2</b> <i>avec un suj. de chose,</i> être en surplus, PLAT. <i>Leg. 855</i> a ; <i>p. suite,</i> être de reste, NT. <i>Matth. 14, 20 ;</i><br><b>   II</b> être de trop :<br><b>      1</b> <i>avec un suj. de chose,</i> être superflu, surabondant, SOPH. <i>El. 1288 ;</i> XÉN. <i>Conv. 4, 35 ;</i> τὸ περιττεῦον, POL. <i>4, 38, 9,</i> le superflu ; τὸ ἀνδρεῖον περισσεύει αὐτῇ, DH. <i>3, 11,</i> les sentiments virils surabondent en elle ; <i>abs</i>. περισσεύει, il y a en surcroît : τοσοῦτον τῷ Περικλεῖ ἐπερίσσευεν, THC. <i>2, 65,</i> Périclès avait un tel surcroît de crédit (<i>ou sel. d’autres,</i> une telle surabondance de ressources) ;<br><b>      2</b> <i>avec un suj. de pers</i>. surabonder, avoir en surabondance : τινί, POL. <i>18, 18, 5 ;</i> τινός, NT. <i>Luc. 15, 17,</i> qqe ch. ;<br><b>B <i>tr.</i></b> fournir en abondance, <i>d’où :</i><br><b>      1</b> prolonger au delà du temps fixé, <i>acc</i>. ATH. <i>24</i> b ;<br><b>      2</b> multiplier, <i>acc</i>. BABR. <i>130, 4 ; d’où</i> répandre abondamment <i>ou</i> avec excès, <i>acc</i>. NT. <i>2Cor. 9, 8 ; 1Thess. 3, 12 ; au pass</i>. être en excès, en surabondance, NT. <i>Matth. 13, 12 ; 25, 29</i>.<br><span><b>Étym</b>. περισσός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσευω - περισσεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n39 fois dans 35 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (10)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (3)</li>\n</ul>\n</td></tr>\n</table>","G4053":"<h1>perissos</h1>\n<p>Strong n° 4053 <i>Prononciation [per-is-sos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>excédant un nombre ou une mesure ou un rang ou un besoin</li>\n<li>voir définition </li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσός</b>, <i>att</i>. <b>περιττός, ή, όν :<br>A</b> qui dépasse la mesure, <i>d’où :</i><br><b>   I</b> extraordinaire en grandeur, en grosseur, en beauté, <i>càd. :</i><br><b>      1</b> magnifique, remarquable : ἀνήρ, EUR. <i>Hipp. 948,</i> homme supérieur ; περισσὸν δῶρον, HÉS. <i>Th. 399,</i> présent magnifique ; τὸ περισσόν, LGN, ce qui est distingué, <i>p. opp. à</i> δημῶδες ; περισσός τι, ALCIPHR. <i>1, 12, etc. ;</i> κατά τι, ARSTT. <i>Probl. 30, 1 ;</i> τινι, PLUT. <i>Demetr. 2, etc. ;</i> ἔν τινι, PLUT. <i>Dem. 3, etc.,</i> remarquable, distingué en qqe ch. ; <i>avec l’inf</i>. περιττὸς συνθεῖναι τὰ ὀνόματα, DH. <i>Comp. 17,</i> très habile à former des composés ;<br><b>      2</b> <i>en parl. d’animaux,</i> remarquable, prodigieux, étrange, singulier, ARSTT. <i>H.A. 4, 7, etc. ; G.A. 3, 10, etc. ;</i><br><b>      3</b> <i>en parl. de choses :</i> important, considérable, extraordinaire (butin, EUR. <i>Bacch. 1195 ;</i> action, ARSTT. <i>Pol. 5, 10, etc</i>.) : λόγος π. SOPH. <i>O.R. 841,</i> langage qui mérite une attention particulière ; <i>joint à</i> θαυμαστά, ARSTT. <i>Nic. 6, 7 ; avec une nuance d’ironie,</i> ARSTT. <i>Metaph. 9, 1 ; en ce sens joint à</i> ξένος καὶ παράδοξος, DH. <i>Thuc. 34, 2 ;</i><br><b>   II</b> démesurément grand <i>ou</i> nombreux, <i>d’où :</i><br><b>      1</b> démesuré, excessif, PLAT. <i>Rsp. 407</i> b, <i>etc. ;</i> τινὸς περισσὸς πρὸς τὸ ἄχος, SOPH. <i>El. 155,</i> qui s’abandonne plus que qqn, <i>càd</i>. avec moins de retenue à sa douleur ; ἀκριϐὴς καὶ περιττὸς τὴν περὶ τὸ σῶμα θεραπείαν, PLUT. <i>Cic. 8,</i> consciencieux à l’excès pour les soins du corps ;<br><b>      2</b> superflu, XÉN. <i>Mem. 3, 6, 6, etc. ;</i> τὰ περιττά, XÉN. <i>Œc. 20, 1,</i> le superflu, <i>p. opp. à</i> τὰ ἀναγκαῖα, <i>avec le gén. :</i> εἴ τι περισσὸν εἰδείη σοφίης, THGN. <i>170,</i> s’il devait connaître qqe ch. de plus dans la sagesse ; τὰ περιττὰ τῶν ἀρκούντων, XÉN. <i>Cyr. 8, 2, 21 ; ou</i> τῶν ἱκανῶν, XÉN. <i>Hier. 1, 19,</i> plus que nécessaire, plus que suffisant ;<br><b>      3</b> <i>p. suite,</i> inutile, vain, XÉN. <i>Œc. 18, 2 ;</i> SOPH. <i>Ant. 780 ;</i> EUR. <i>Med. 819, etc. ;</i> ἐκ (τοῦ) περιττοῦ, en excédent, surabondamment, PLAT. <i>Prot. 308</i> b, <i>etc. ;</i> par-dessus le marché, PLAT. <i>Leg. 802</i> d, <i>etc. ;</i> inutilement, d’une façon superflue, POL. <i>5, 11, 4 ;</i><br><b>      4</b> plus qu’on n’a coutume, extraordinairement : τί περισσὸν ποιεῖτε ; NT. <i>Matth. 5, 47,</i> que faites-vous d’extraordinaire ? περιττότερον τῶν ἄλλων, PLAT. <i>Ap. 20</i> c, <i>etc</i>. au delà de ce que font les autres, plus que les autres, autrement que les autres ;<br><b>   III</b> <i>au mor</i>. excessif dans ses sentiments, ses passions, <i>d’où :</i><br><b>      1</b> mauvais à l’excès, dur à l’excès, EUR. <i>Suppl. 791, etc. ;</i><br><b>      2</b> hautain, orgueilleux, présomptueux, SOPH. <i>Aj. 758 ;</i> EUR. <i>Hipp. 444, etc. ;</i><br><b>      3</b> <i>en parl. de l’habillement et de la parure,</i> surchargé, recherché, maniéré, PLUT. <i>M. 615</i> d ; ANTH. <i>12, 192 ;</i><br><b>   IV</b> <i>t. de rhét. en parl. du style :</i><br><b>      1</b> surchargé, orné, enflé, PLAT. <i>Ax. 365</i> c, <i>366</i> d, <i>etc. ;</i><br><b>      2</b> <i>en b. part :</i> non ordinaire, noble <i>ou</i> gracieux, choisi, <i>p. opp. à</i> κοινός, συνήθης, δημώδης, DH. <i>Comp. p. 26, 47 ;</i><br><b>B</b> qui dépasse la quantité, qui est en surplus, qui reste, de reste, X. ÉPH. <i>2, 14 ;</i> τὰ περιττά, les restes, le résidu, ANTH. <i>11, 239 ; avec un gén</i>. τὸ περιττὸν τῆς ἡμέρας, X. ÉPH. <i>1, 3,</i> le reste du jour ; impair, inégal, PLAT. <i>Prot. 356</i> e, <i>etc. ;</i> τὸ π. PLAT. <i>Gorg. 451</i> c, <i>etc</i>. le nombre impair ; <i>t. milit</i>. τὸ περιττόν, XÉN. <i>Cyr. 6, 3, 20 ;</i> τὰ περιττά <i>ou</i> οἱ περιττοί, XÉN. <i>An. 4, 8, 11,</i> l’excédent des forces ; <i>particul. en parl. de nombres qui dépassent un nombre complet ou pair</i> (<i>v</i>. ἄρτιος) <i>d’où</i> ἀρτιάκις περισσὸς ἀριθμός, EUCL. <i>Elem. 7, 10,</i> nombre divisible par deux, mais composé de parties impaires, <i>d’où</i> nombre divisible par deux et non par quatre ; <i>p. suite</i> inégal en nombre, en nombre inégal, XÉN. <i>Hipp. 2, 6 ;</i> PLAT. <i>Leg. 946</i> a, <i>etc</i>.<br><span>•<i> Cp</i>. -ότερος, PLAT. <i>Conv. 219</i> c ; PLUT. <i>M. 57</i> f ; NT. <i>Matth. 11, 9, etc. ;</i> ANTH. <i>12, 192, etc. ;</i> <i>• Sup</i>. -ότατος, ARSTT. <i>H.A. 4, 6, etc</i>.<br><span><b>Étym</b>. περί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσος - περισσός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G4054":"<h1>perissoteron</h1>\n<p>Strong n° 4054 <i>Prononciation [per-is-sot'-er-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>excédant un certain nombre ou une mesure ou un rang ou un besoin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>περισσότερος</b>, <i>cp. de</i> .<br><br>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσοτερων - περισσότερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Comparatif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4055":"<h1>perissoteros</h1>\n<p>Strong n° 4055 <i>Prononciation [per-is-sot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>excédant un nombre ou une mesure ou un rang ou un besoin\n<ol type=\"a\">\n<li>plus et au-dessus, plus que nécessaire, superflu\n<ol>\n<li>excédant abondamment, suprêmement</li>\n<li>en plus, davantage, plus que tout, plus simplement</li>\n</ol>\n</li>\n<li>supérieur, extraordinaire, hors du commun\n<ol>\n<li>prééminence, supériorité, avantage, plus remarquable, plus excellent</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσότερος</b>, <i>cp. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσοτερος - περισσότερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Comparatif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4056":"<h1>perissoteros</h1>\n<p>Strong n° 4056 <i>Prononciation [per-is-sot-er'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plus abondamment</li>\n<li>au plus haut degré</li>\n<li>plus sérieusement, extrêmement plus</li>\n<li>spécialement, au-dessus des autres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσοτέρως</b>, <i>cp. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσοτερως - περισσοτέρως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 12 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4057":"<h1>perissos</h1>\n<p>Strong n° 4057 <i>Prononciation [per-is-soce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>au delà de la mesure, extraordinaire, abondamment, avec excès</li>\n<li>grandement, extrêmement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περισσῶς</b>, <i>att</i>. <b>περιττῶς</b>, <i>adv. :</i><br><b>   I</b> au delà de la mesure, supérieurement, à un plus haut degré, PD. <i>N. 7, 63 ;</i> EUR. <i>Hec. 579 ;</i> NT. <i>2Cor. 2, 4 ;</i> GAL. <i>1, 14, etc. ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> excellemment, EUR. <i>Bacch. 1195, etc. ;</i><br><b>      2</b> magnifiquement, HDT. <i>2, 129 ;</i> ATH. <i>501</i> d, <i>etc. ;</i><br><b>      3</b> remarquablement, ARSTT. <i>H.A. 8, 2, etc. ;</i><br><b>      4</b> singulièrement, ARSTT. <i>Pol. 2, 11 ;</i> PLUT. <i>M. 30</i> d, <i>etc</i>.<br><span>•<i> Cp</i>. περισσοτέρως, DS. <i>13, 108 ;</i> ATH. <i>192</i> f, <i>etc. ; att</i>. περιττοτέρως, ISOCR. <i>35</i> e ; <i>ou</i> περισσότερον, HDT. <i>2, 129 ;</i> PLAT. <i>Ap. 20</i> c, <i>etc. ;</i> LUC. <i>Im. 14, etc.</i> <i>• Sup</i>. περισσότατα, DC. <i>37, 17 ; att</i>. περιττότατα, ARSTT. <i>H.A. 8, 2, 4</i>.<br><span><b>Étym</b>. περισσός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περισσως - περισσῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4058":"<h1>peristera</h1>\n<p>Strong n° 4058 <i>Prononciation [per-is-ter-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une colombe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περιστερά, ᾶς (ἡ)</b> colombe, pigeon, HDT. <i>1, 138 ;</i> ARSTT. <i>H.A. 6, 4, 1, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. περιστερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιστερα - περιστερά</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G4059":"<h1>peritemno</h1>\n<p>Strong n° 4059 <i>Prononciation [per-ee-tem'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couper autour, découper</li>\n<li>circoncire\n<ol type=\"a\">\n<li>suppression du prépuce (de ce rite bien connu fait sur les enfants mâles des Israélites, au huitième jour après leur naissance, mais également aux « prosélytes de justice » qui étaient consacrés à l'Eternel et introduits au nombre de son peuple)</li>\n<li>se présenter à la circoncision, être circoncis, recevoir la circoncision</li>\n<li>comme par le rite de la circoncision l'homme était séparé du monde impur et dédié à Dieu, le mot est transféré à la suppression des convoitises et à l'enlèvement des péchés.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·τέμνω</b> <span>(<i>f</i>. περιτεμῶ, <i>ao.2</i> περιέταμον)</span><br><b>   I</b> couper tout autour, <i>càd. :</i><br><b>      1</b> tailler tout autour, <i>acc</i>. HÉS. <i>O. 568 ;</i> HDT. <i>4, 64, etc. ;</i><br><b>      2</b> couper les extrémités (oreilles, nez, <i>etc</i>.) HDT. <i>2, 162 ;</i> DC. <i>62, 7, etc. ;</i> LUC. <i>Anach. 20 ; particul</i>. circoncire, <i>acc</i>. DS. <i>1, 28 ; 3, 32 ;</i> SPT. <i>Gen. 17, 10, etc. ; fig</i>. rogner, amoindrir (l’autorité) POL. <i>23, 13, 2 ;</i><br><b>      3</b> cerner et intercepter, XÉN. <i>Cyr. 5, 4, 8 ; d’où</i> enlever, dépouiller ; <i>au pass</i>. γῆν περιτάμνεσθαι, HDT. <i>4, 159,</i> être volé d’un morceau de terre ;<br><b><i>Moy.</i></b> :<br><b>      1</b> se faire circoncire, <i>acc</i>. HDT. <i>2, 36, 104 ;</i><br><b>      2</b> enlever <i>ou</i> ravir pour soi, <i>acc</i>. OD. <i>11, 402 ; 24, 112</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et épq</i>. περιτάμνω, OD. HDT. <i>ll. cc. ; inf. prés. épq</i>. περιταμνέμεν, HÉS. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιτεμνω - περιτέμνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (6)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4060":"<h1>peritithemi</h1>\n<p>Strong n° 4060 <i>Prononciation [per-ee-tith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer autour, fixer autour de</li>\n<li>couvrir d'un vêtement</li>\n<li>mettre ou lier une chose autour d'une autre</li>\n<li>présenter, accorder, conférer, une chose à quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·τίθημι</b> <span>(<i>ao</i>. περιέθηκα, <i>etc</i>.)</span> mettre autour : στέφανόν τινι, PLAT. <i>2 Alc. 151</i> a, ceindre qqn d’une couronne ; τι περὶ τὴν κεφαλήν, PLAT. <i>Rsp. 406</i> d, ceindre qqe ch. autour de la tête de qqn ; <i>fig. avec un acc. de pers. :</i> π. τινὰ ὕϐρει, DL. <i>6, 33,</i> remplir qqn d’orgueil ; <i>avec un acc. de chose :</i> appliquer, attribuer : τί τινι, HDT. <i>1, 129, etc. ;</i> THC. <i>4, 87, etc. ;</i> ISOCR. <i>265</i> b, <i>etc</i>. qqe ch. à qqn ;<br><b><i>Moy.</i></b> mettre sur soi tout autour (du corps, de la tête) : τι, EUR. <i>Med. 984 ;</i> XÉN. <i>Cyr. 2, 4, 6 ;</i> PLAT. <i>Crit. 53</i> d, <i>etc</i>. se ceindre <i>ou</i> se revêtir de qqe ch.<br><span><b>Étym</b>. une couronne, un collier, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιτιθημι - περιτίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4061":"<h1>peritome</h1>\n<p>Strong n° 4061 <i>Prononciation [per-it-om-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>circoncis\n<ol type=\"a\">\n<li>celui qui est passé par le rite de la circoncision, « ceux de la circoncision » est un terme utilisé par les Juifs\n<ol>\n<li>des Chrétiens recueillis parmi les Juifs</li>\n<li>l'état de la circoncision</li>\n</ol>\n</li>\n<li>métaph.\n<ol>\n<li>Chrétiens séparés de la multitude impure et vraiment consacrés à Dieu</li>\n<li>l'extinction des passions et l'abandon de l'impureté spirituelle</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περιτομή, ῆς (ἡ)</b> circoncision, SPT. <i>Gen. 17, 13 ;</i> NT. <i>Rom. 2, 29</i>.<br><span><b>Étym</b>. περιτέμνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιτομη - περιτομή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n36 fois dans 32 versets de 9 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>Romains (15)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (4)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4062":"<h1>peritrepo</h1>\n<p>Strong n° 4062 <i>Prononciation [per-ee-trep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tourner, se détourner, retourner</li>\n<li>transférer ou changer par retournement\n<ol type=\"a\">\n<li>une personne ou une chose dans un tel état</li>\n<li>faire devenir fou</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·τρέπω :<br>   I <i>tr.</i></b> faire tourner tout autour, <i>d’où :</i><br><b>      1</b> retourner : τινά, PLUT. <i>Marc. 7,</i> qqn ; ναῦν, LUC. <i>Char. 7,</i> faire chavirer un navire ; <i>fig</i>. renverser, précipiter : π. ὕψος τινός, TRAG. (STOB. <i>Fl. 105, 51</i>) précipiter qqn de la hauteur où il est élevé ; π. δούλι' ἔργα, SIM. AM. <i>fr. 7, 58</i> (περιτρέμει <i>Schneidew</i>.), se refuser aux travaux serviles ; λόγον, PLAT. <i>Phæd. 95</i> b, renverser, réduire à néant un argument ; τὸ παράδειγμα περιτέτραπται, LUC. <i>J. tr. 49,</i> l’exemple n’est bon à rien, ne convient pas ; π. ἑαυτόν, PLAT. <i>Ax. 370</i> a, se renverser, <i>càd</i>. se frapper soi-même ;<br><b>      2</b> retourner, mettre à l’envers, PLUT. <i>M. 1036</i> f, <i>etc. ;</i> LUC. <i>Laps. 15 ; avec l’inf. :</i> ἡ νέα φωνὴ τοὐναντίον περιέτρεψε μηνύειν τὸ δέον, PLAT. <i>Crat. 418</i> b, la langue nouvelle a tellement changé le sens du mot δέον, qu’il signifie le contraire ; <i>avec un n. de pers. pour rég</i>. mettre dans la situation opposée : π. τινὰ εἰς μανίαν, NT. <i>Ap. 26, 24 ;</i> εἰς χαράν, JOS. <i>B.J. 9, 4, 4,</i> faire devenir qqn fou de joie ;<br><b>      3</b> mettre, rejeter sur le compte de : τὴν αἰτίαν εἴς τινα, LYS. <i>104, 26,</i> rejeter l’accusation sur qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιτρεπω - περιτρέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4063":"<h1>peritrecho</h1>\n<p>Strong n° 4063 <i>Prononciation [per-ee-trekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>courir autour, parcourir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·τρέχω :<br>   I</b> courir autour, <i>d’où :</i><br><b>      1</b> <i>au propre :</i> courir autour de, <i>abs</i>. IL. <i>22, 369 ;</i> THGN. <i>505 ;</i> XÉN. <i>Œc. 13, 8 ;</i> τινά, HDT. <i>8, 128,</i> courir autour de qqn ; τὴν Πύκνα, AR. <i>Th. 657,</i> courir autour du Pnyx ; εἰς ταὐτόν, PLAT. <i>Theæt. 200</i> c, courir tout autour pour revenir au même point ; <i>fig</i>. PLAT. <i>Clit. 410</i> a ;<br><b>      2</b> accourir autour de, fondre sur, <i>acc</i>. A. RH. <i>3, 676 ;</i><br><b>      3</b> <i>fig</i>. circonvenir, tromper, AR. <i>Eq. 56 ;</i><br><b>   II</b> courir de tous côtés, <i>d’où :</i><br><b>      1</b> rôder, PLAT. <i>Conv. 173</i> a ;<br><b>      2</b> <i>fig</i>. περιτρέχων, PLAT. <i>Ep. 333</i> e, qui court les rues ; ὀνόματα κοινὰ καὶ περιτρέχοντα, DH. <i>Din. 2,</i> expressions <i>ou</i> locutions courantes, usuelles, <i>d’où</i> banales ; τέχνη περιτρέχουσα, QUINT. <i>2, 21, 7,</i> art vulgaire, qui s’exerce sur tous les sujets.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. περιέθρεξα, AR. <i>Ran. 193 ; ao.2 poét</i>. περίδραμον, IL. <i>l. c. ; pf</i>. περιδέδρομα, THCR. A. RH. <i>ll. cc. ;</i> περιδεδράμηκα, PLAT. <i>Clit. 410</i> a.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιτρεχω - περιτρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4064":"<h1>periphero</h1>\n<p>Strong n° 4064 <i>Prononciation [per-ee-fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter dans une tournée, transporter partout avec soi</li>\n<li>porter ici et là</li>\n<li>être conduit\n<ol type=\"a\">\n<li>dans le doute et l'hésitation, être amené tantôt à une opinion, tantôt à une autre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·φέρω</b> <span>(<i>f</i>. περιοίσω, <i>ao.1</i> περιήνεγκα, <i>etc</i>.)</span><br><b>   I</b> porter tout autour : τὸ τεῖχος, HDT. <i>1, 84,</i> porter autour du mur ; <i>particul</i>. faire circuler, faire passer à la ronde, <i>en parl. du service des mets autour d’une table,</i> XÉN. <i>Cyr. 2, 2, 2 ; au pass</i>. περιφέρεσθαι, être porté tout autour, circuler, PLUT. <i>M. 721</i> b ; <i>particul</i>. accomplir sa révolution, <i>en parl. des astres du ciel, etc</i>. HDT. <i>4, 72 ;</i> PLUT. <i>Tim. 27, etc. ;</i><br><b>   II</b> faire circuler un bruit, un mot, <i>p. suite,</i> divulguer, faire connaître, PLAT. <i>Prot. 343</i> b, <i>etc. ;</i> PLUT. <i>M. 115</i> c, <i>etc. ; d’où au pass</i>. se répandre, circuler, PLUT. <i>Galb. 22, etc. ;</i><br><b>   III</b> amener par un circuit : εἰς ἑαυτὸν τὰς Ἀθήνας, PLUT. <i>Per. 15,</i> amener Athènes en son pouvoir, soumettre Athènes ;<br><b>   IV</b> ramener par un tour complet : εἰς ταὐτόν, PLAT. <i>Phædr. 247</i> d, au point de départ ; <i>d’où au pass</i>. εἰς ταὐτό, PLAT. <i>Gorg. 517</i> c, revenir au point de départ, <i>en parl. d’un raisonnement ;</i><br><b>   V</b> ramener par un retour en arrière, reporter vers le passé : περιφέρει τίς με μνήμη τινός, PLAT. <i>Lach. 180</i> e, le souvenir de qqe ch. me fait faire un retour vers le passé, <i>càd</i>. me reporte par le souvenir à qqe ch. ; <i>avec un inf. :</i> οὔτε με περιφέρει οὐδὲν εἰδέναι τουτέων, HDT. <i>6, 86,</i> il ne me revient pas à l’esprit que je sache rien de ces choses ;<br><b>   VI</b> amener à terme, <i>d’où abs</i>. tenir bon, THC. <i>7, 28 ;</i> TH. <i>H.P. 9, 12, 1 ;</i> APP. <i>Civ. 2, 149, etc. ;</i><br><b>   VII</b> porter hors du droit chemin, égarer, <i>acc</i>. PLUT. <i>M. 522</i> c ; SPT. <i>Eccl. 7, 8 ;</i> π. εἴς τι, PLUT. <i>M. 165</i> c, <i>546</i> c, conduire à qqe ch. de mauvais ; <i>particul</i>. amener d’une situation meilleure dans une pire : τὴν Ἰταλίαν εἰς λιμόν, APP. <i>Civ. 5, 143,</i> réduire l’Italie à la famine.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. ion</i>. περιήνεικα, HDT. <i>1, 84</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιφερω - περιφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4065":"<h1>periphroneo</h1>\n<p>Strong n° 4065 <i>Prononciation [per-ee-fron-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>considérer ou examiner sous tous les aspects, soigneusement, complètement</li>\n<li>se considérer comme étant au-dessus, s'élever au-dessus d'une personne</li>\n<li>mépriser, considérer avec mépris</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περι·φρονέω-ῶ :<br>      1</b> méditer sur tous les points, examiner à fond, <i>acc</i>. AR. <i>Nub. 225, etc. ; abs</i>. être réfléchi, circonspect, PLAT. <i>Ax. 365</i> b ;<br><b>      2</b> regarder de côté, dédaigner, mépriser, <i>acc</i>. THC. <i>1, 25 ; gén</i>. PLAT. <i>Ax. 372</i> b ; PLUT. <i>Thes. 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιφρονεω - περιφρονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4066":"<h1>perichoros</h1>\n<p>Strong n° 4066 <i>Prononciation [per-ikh'-o-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se trouvant tout autour, voisinage\n<ol type=\"a\">\n<li>la région environnante</li>\n<li>la région du Jourdain</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περί·χωρος, ος, ον</b>, situé autour <i>ou</i> auprès, limitrophe : ἡ περίχωρος (<i>s.-e</i>. γῆ) SPT. <i>Gen. 13, 10 ;</i> NT. <i>Matth. 14, 35 ; ou</i> τὰ περίχωρα (<i>s.-e</i>. μέρη) SPT. <i>Gen. 13, 12, Deut. 3, 4 ; 1Par. 5, 16,</i> le pays d’alentour ; οἱ περίχωροι, DÉM. <i>426, 9 ;</i> PLUT. <i>Cato ma. 25, etc</i>. les populations voisines.<br><span><b>Étym</b>. π. χώρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιχωρος - περίχωρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (5)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4067":"<h1>peripsema</h1>\n<p>Strong n° 4067 <i>Prononciation [per-ip'-say-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est essuyé</li>\n<li>la saleté qui est enlevée</li>\n<li>déchets du nettoyage, raclures</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περίψημα, ατος (τὸ) :<br>      1</b> ce qu’on ôte en frottant tout autour, ordure, NT. <i>1Cor. 4, 13 ;</i><br><b>      2</b> délivrance, SPT. <i>Tob. 5, 19</i>.<br><span><b>Étym</b>. περιψάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περιψημα - περίψημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4068":"<h1>perpereuomai</h1>\n<p>Strong n° 4068 <i>Prononciation [per-per-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se glorifier</li>\n<li>affichage de soi, en employant un embellissement rhétorique pour se vanter avec excès</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>περπερεύομαι</b>, être léger, frivole, étourdi, NT. <i>1Cor. 13, 4 ;</i> M. ANT. <i>5, 5</i>.<br><span><b>Étym</b>. πέρπερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περπερευομαι - περπερεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4069":"<h1>Persis</h1>\n<p>Strong n° 4069 <i>Prononciation [per-sece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Perside (Angl. Persis) = « une femme Perse »\n<ol><li>une femme Chrétienne à Rome</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Περσίς, ίδος</b> <span>[ῐδ]</span> <i>adj. f</i>. de Perse, persan, persique, ESCHL. <i>Pers. 59, etc. ;</i> HDT. <i>3, 3, 6, etc. ;</i> XÉN. <i>Cyr. 8, 2, 25, etc. ;</i> Περσὶς χώρη, HDT. <i>3, 97 ; ou simpl</i>. ἡ Περσίς, XÉN. <i>Cyr. 2, 1, 1 ;</i> PLAT. <i>1 Alc. 121</i> a, <i>etc</i>. la Perse (<i>auj</i>. Fars, <i>province d’Iran</i>) ; ἡ Περσίς (<i>s.-e</i>. γυνή) ESCHL. <i>Pers. 136, etc. ;</i> XÉN. <i>Cyr. 8, 5, 21, etc</i>. femme de Perse, Persane ; (<i>s.-e</i>. χλαῖνα) AR. <i>Vesp. 1137,</i> robe persane.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. Περσίς, ESCHL. <i>Pers. 250</i>.<br><span><b>Étym</b>. Πέρσης².</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Περσις - Περσίς</font>\n<br><br>gr. : Persane</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4070":"<h1>perusi</h1>\n<p>Strong n° 4070 <i>Prononciation [per'-oo-si]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>depuis une année passée, il y a un an</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέρυσι(ν)</b> <span>[ῠῐ]</span> <i>adv. :</i><br><b>      1</b> l’an passé, AR. <i>Vesp. 1038, etc. ;</i> PLAT. <i>Prot. 327</i> d ; LYS. <i>148, 34, etc. ;</i><br><b>      2</b> <i>p. ext</i>. autrefois, auparavant, XÉN. <i>Hell. 3, 2, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῑ]</span> THCR. <i>Idyl. 29, 26</i>.<br><span><b>Étym</b>. <i>cf. sscr</i>. parut, « l’an <i>passé</i> » <i>de</i> para « autre » <i>et</i> vat = ἔτος <i>p</i>. *ϝετος, « année ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">περυσι - πέρυσι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4071":"<h1>peteinon</h1>\n<p>Strong n° 4071 <i>Prononciation [pet-i-non']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui volent, qui ont des ailes</li>\n<li>animaux volants ou ailés, oiseaux\n<ol type=\"a\">\n<li>les oiseaux du ciel, volant dans les cieux (dans l'air)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>πετεινός, ή, όν</b>, <i>c</i>. πετεηνός THGN. <i>1097 ;</i> HDT. <i>1, 140 ; 2, 123 ; 3, 106</i>.<br><br>\n<b>πετεηνός, ή, όν :<br>      1</b> qui peut voler ; τὰ πετεηνά, IL. <i>8, 247, etc</i>. les volatiles, les oiseaux ;<br><b>      2</b> qui est déjà en état de voler, OD. <i>16, 218</i>.<br><span><b>Étym</b>. πέτομαι, <i>avec distension</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πετεινον - πετεινόν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4072":"<h1>petomai</h1>\n<p>Strong n° 4072 <i>Prononciation [pet'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>voler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέτομαι</b> <span>(<i>f</i>. πτήσομαι <i>et</i> πετήσομαι, <i>ao.2</i> ἐπτόμην, <i>d’où inf</i>. πτέσθαι ; <i>ao. radical</i> ἐπτάμην (<i>c. de</i> πέταμαι) ; <i>act. intr</i>. ἔπτην, <i>d’où opt</i>. πταίην, <i>inf</i>. πτῆναι <i>et part</i>. πτάς ; <i>pf. inus</i>.)</span> voler :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> <i>en parl. d’oiseaux (aigle,</i> IL. <i>12, 207 ;</i> OD. <i>2, 147, 148 ; vautour,</i> IL. <i>13, 62 ; grues,</i> IL. <i>3, 5, etc.) ; ou d’insectes ailés (abeilles,</i> IL. <i>2, 89 ; mouches,</i> HDT. <i>2, 95</i>) ;<br><b>      2</b> <i>p. anal. en parl. de petits enfants qui n’ont pas encore la force de prendre leur essor,</i> SOPH. <i>O.R. 17 ; en parl. de flèches, de pierres lancées avec force,</i> IL. <i>13, 140 ; 20, 99, etc. ; ou d’hommes et d’animaux qui courent rapidement (hommes,</i> IL. <i>13, 755 ; 16, 245, etc. ; chevaux,</i> IL. <i>5, 366, 768, etc. ;</i> OD. <i>3, 481, etc. ; chars,</i> HÉS. <i>Sc. 308, etc.) ; en parl. de danseurs,</i> EUR. <i>Cycl. 71 ; en gén</i>. PLAT. <i>Rsp. 567</i> d, <i>647</i> d, <i>etc. ;</i><br><b>      3</b> <i>fig</i>. voltiger par la pensée, ne fixer son esprit sur rien, EUR. <i>Bacch. 332 ; particul</i>. être ballotté par l’espérance, SOPH. <i>O.R. 487</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 2 sg</i>. πέτει, EUR. <i>Bacch. 332 ;</i> πέτεαι, ANACR. <i>9. Ao. radical 3 sg</i>. ἔπτη, BATR. <i>208, d’où opt. 2 sg</i>. πταίης, ANTH. <i>5, 152 ; inf</i>. πτῆναι, A. PL. <i>16, 108</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *pet-, tomber ; <i>cf</i>. πέταμαι, ἵπταμαι, πτερόν, πτῆσις, <i>lat</i>. petō, <i>sscr</i>. pátati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πετομαι - πέτομαι</font>\n<br><br>vient d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G4073":"<h1>petra</h1>\n<p>Strong n° 4073 <i>Prononciation [pet'-ra]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un roc, falaise ou chaîne\n<ol type=\"a\">\n<li>rocher escarpé, terrain rocheux</li>\n<li>un rocher, une grosse pierre</li>\n<li>métaph. l'homme comme un roc en raison de sa fermeté et de la force de son âme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πέτρα, ας (ἡ)</b> rocher, roche :<br><b>   I</b> <i>en gén</i>. IL. <i>9, 15, etc. ;</i> OD. <i>5, 412, etc. ;</i> HÉS. <i>Sc. 421, etc. ;</i> ESCHL. <i>Pr. 4, etc. ;</i> SOPH. <i>O.R. 464, etc. ;</i> PLAT. <i>Leg. 838</i> b, <i>etc. ; fig. comme emblème :</i><br><b>      1</b> <i>de solidité, d’immobilité,</i> OD. <i>17, 463 ;</i><br><b>      2</b> <i>de dureté, d’inflexibilité,</i> ESCHL. <i>Pr. 242 ;</i> EUR. <i>Andr. 537, etc. ;</i><br><b>      3</b> <i>de stérilité,</i> PLAT. <i>Rsp. 544</i> d, <i>etc. ;</i><br><b>   II</b> rocher dans la mer <i>ou</i> sur le rivage, écueil, IL. <i>16, 619 ;</i> OD. <i>3, 293 ; 4, 501 ; etc. ;</i> quartier de roc, OD. <i>9, 243, 486 ;</i> HÉS. <i>Th. 675</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. πέτρη, IL. <i>9, 15, etc. ;</i> OD. <i>5, 412, etc</i>.<br><span><b>Étym</b>. <i>probabl. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πετρα - πέτρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4074":"<h1>Petros</h1>\n<p>Strong n° 4074 <i>Prononciation [pet'-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pierre (Angl. Peter) = « un roc ou une pierre »\n<ol><li>un des douze disciples de Jésus</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πέτρος, ου (ὁ)</b> Pierre :<br><b>      1</b> <i>un des douze apôtres</i> NT. <i>Matth. 4, 18, etc. ;</i><br><b>      2</b> <i>rhéteur,</i> ANTH. <i>7, 579</i>.<br><br>\n<b>πέτρος, ου (ὁ) :<br>      1</b> pierre, IL. <i>7, 270 ; 16, 734 ; 20, 288 ;</i> PD. <i>O. 10, 86, etc. ;</i> ESCHL. <i>Pers. 460 ;</i> SOPH. <i>O.C. 435, etc. ;</i> EUR. <i>I.T. 327, etc. ;</i> XÉN. <i>An. 4, 7, 12 ; Hell. 3, 5, 20, etc. ; prov</i>. <span>πάντα πέτρον κινεῖν</span>, EUR. <i>Her. 1002,</i> remuer toute sorte de pierres, <i>càd</i>. mettre tout en jeu ; <i>cf</i>. PLAT. <i>Leg. 843</i> a ; <i>fig. comme synon. de</i> dureté, d’insensibilité, SOPH. <i>O.R. 334 ;</i> EUR. <i>Med. 28, H.f. 1397 ;</i><br><b>      2</b> <i>rar. c</i>. πέτρα, rocher, SOPH. <i>Ph. 272, O.C. 19, 1595</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Postér</i>. ἡ π. <i>comme</i> ἡ λίθος, ANTH. <i>7, 274, 479</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πετρος - Πέτρος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n159 fois dans 154 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (23)</li>\n<li>Marc (19)</li>\n<li>Luc (19)</li>\n<li>Jean (34)</li>\n<li>Actes (57)</li>\n<li>Galates (5)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4075":"<h1>petrodes</h1>\n<p>Strong n° 4075 <i>Prononciation [pet-ro'-dace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rocheux, pierreux\n<ol type=\"a\">\n<li>d'un sol plein de pierres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πετρώδης, ης, ες :<br>      1</b> pierreux, rocailleux, HPC. <i>Aër. 280 ;</i> PLAT. <i>Rsp. 612</i> a ; ARSTT. <i>H.A. 5, 17, 8 ;</i><br><b>      2</b> de pierre, fait en pierres, SOPH. <i>Ant. 774, 948</i>.<br><span><b>Étym</b>. πέτρα <i>ou</i> πέτρος, -ωδης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πετρωδης - πετρώδης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G4076":"<h1>peganon</h1>\n<p>Strong n° 4076 <i>Prononciation [pay'-gan-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la rue</li>\n<li>une plante en arbuste d'environ 60 cm, ayant des propriétés médicinales</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πήγανον, ου (τὸ)</b> <span>[ᾰ]</span> rue, <i>plante à feuilles grasses,</i> AR. <i>Vesp. 480 ;</i> TH. <i>H.P. 1, 3, 4 ;</i> DIOSC. <i>3, 52, etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηγανον - πήγανον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4077":"<h1>pege</h1>\n<p>Strong n° 4077 <i>Prononciation [pay-gay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fontaine, source</li>\n<li>un puits alimenté par une source</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πηγή, ῆς (ἡ)</b> source, <i>particul. :</i><br><b>      1</b> source d’un fleuve, IL. <i>20, 9, etc. ;</i> OD. <i>6, 124 ;</i> HDT. <i>1, 189 ;</i> ESCHL. <i>Pr. 89, 434, etc. ;</i> EUR. <i>H.f. 1297, etc. ; différent de</i> κρουνός, IL. <i>22, 147 ;</i><br><b>      2</b> <i>p. suite,</i> écoulement continu d’un liquide, de larmes, ESCHL. <i>Ag. 888 ;</i> SOPH. <i>Tr. 852, Ant. 803 ; d’où abs. au plur</i>. les larmes elles-mêmes, ESCHL. <i>Pr. 401 ;</i> EUR. <i>Alc. 1071, etc. ;</i> de lait, SOPH. <i>El. 895 ;</i> de vin, EUR. <i>Cycl. 496 ; p. anal</i>. de feu, PD. <i>P. 1, 42 ;</i><br><b>      3</b> <i>p. ext</i>. source, <i>càd</i>. le lieu d’où naît qqe ch., qui produit qqe ch. : πηγαὶ ἡλίου, ESCHL. <i>Pr. 809 ;</i> νυκτός, SOPH. <i>fr. 655,</i> la source du soleil, <i>càd</i>. l’Orient ; la source de la nuit, <i>càd</i>. l’Occident ; πηγὴ ἀργύρου, ESCHL. <i>Pers. 238,</i> source d’argent, <i>en parl. des mines du Laureion ;</i> τῆς πηγῆς ἀκουούσης, SOPH. <i>O.R. 1386,</i> du sens de l’ouïe, <i>litt</i>. de la source de l’audition ;<br><b>      4</b> <i>fig</i>. source, principe, origine (de biens, de maux, <i>etc</i>.) PD. <i>P. 4, 532 ;</i> ESCHL. <i>Pers. 743 ; joint à</i> ἀρχή, PLAT. <i>Phædr. 245</i> c ; <i>à</i> ῥίζα, PLUT. <i>M. 856</i> d, <i>etc. ;</i> XÉN. <i>Cyr. 7, 2, 13, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. παγά <span>[ᾱᾱ]</span> PD. <i>l. c. ;</i> ESCHL. <i>Pr. 401, etc. ;</i> SOPH. <i>Tr. 852, etc</i>.<br><span><b>Étym</b>. <i>v. p.-ê</i>. πήγνυμι, « se figer, se glacer », <i>cf. l’idée de source comme</i> « froide » ; <i>autrement p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηγη - πηγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (3)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G4078":"<h1>pegnumi</h1>\n<p>Strong n° 4078 <i>Prononciation [payg'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre ferme, fixer, ficher, enfoncer, planter, dresser (une tente)</li>\n<li>attacher ensemble, bâtir en liant des éléments</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πήγνυμι, A <i>tr.</i></b> (<i>aux temps suiv. : prés., impf., f</i>. πήξω, <i>ao</i>. ἔπηξα ; <i>pass. prés</i>. πήγνυμαι, <i>impf</i>. ἐπηγνύμην, <i>f. 2</i> παγήσομαι, <i>ao.2</i> ἐπάγην, <i>ao.1 poét</i>. ἐπήχθην, <i>pf</i>. πέπηγμαι) :<br><b>   I</b> fixer en enfonçant, <i>càd. :</i><br><b>      1</b> ficher, enfoncer : ἐν μετώπῳ, IL. <i>4, 460 ; 6, 10,</i> clouer (le casque) sur le front (avec la pointe de l’arme) ; τὸ ξίφος διὰ φρενῶν, PD. <i>N. 7, 38,</i> enfoncer l’épée dans le cœur ; ἐρετμὸν γαίῃ, OD. <i>11, 129 ;</i> ἐν γαίῃ, OD. <i>23, 276,</i> enfoncer une rame dans la terre ; τύμϐῳ, OD. <i>11, 77 ;</i> ἐπὶ τύμϐῳ, OD. <i>12, 15,</i> fixer sur un tombeau ; πόδα στέρνοις, ANTH. <i>5, 268,</i> mettre le pied sur la poitrine ; <i>abs</i>. ficher dans le sol, enfoncer en terre : σκῆπτρον, SOPH. <i>El. 420,</i> un sceptre ; <i>cf</i>. XÉN. <i>Cyn. 6, 7 ; au pass</i>. ἐν χροῒ δοῦρα πήγνυτο, IL. <i>15, 315,</i> les javelines s’enfonçaient dans la peau ; <i>cf</i>. IL. <i>8, 298 ;</i> δοῦρα ἐν σάκεϊ πάγεν, IL. <i>11, 572,</i> les javelines s’enfoncèrent dans le bouclier ; ὅρος παγήσεται, THC. <i>4, 92,</i> une borne sera plantée ;<br><b>      2</b> <i>particul</i>. ficher un objet pointu, <i>d’où</i> empaler, embrocher : κεφαλὴν ἀνὰ σκολόπεσσι, IL. <i>18, 177,</i> ficher une tête sur des pieux ; δέμας σκόλοψι, EUR. <i>I.T. 1430,</i> ficher un corps sur des pieux ; κρᾶτα ἐπ' ἄκρον θύρσον, EUR. <i>Bacch. 1139,</i> ficher une tête sur la pointe d’un thyrse ; <i>au pass</i>. ἱκέται πηχθέντες μέλη ἀμφὶ ὀϐελοῖσι, EUR. <i>Cycl. 302,</i> suppliants dont les membres sont traversés par des broches ;<br><b>      3</b> <i>p. anal</i>. fixer : κατὰ χθονὸς ὄμματα, IL. <i>2, 317 ;</i> ἐπὶ χθονός, THCR. <i>Idyl. 2, 112,</i> fixer les yeux sur le sol ;<br><b>   II</b> fixer en assemblant, assembler, ajuster, construire : νῆας, IL. <i>2, 664, (cf</i>. ναυπηγέομαι), des vaisseaux ; σκηνὰς κατ' ἀγοράν, PLAT. <i>Leg. 817</i> c, des tentes sur l’agora ; <i>cf</i>. POL. <i>6, 27, 2 ;</i><br><b>   III</b> fixer en rendant compact, <i>d’où</i> faire fixer, faire coaguler, faire geler : ῥέεθρον, ESCHL. <i>Pers. 496 ;</i> ποταμούς, AR. <i>Ach. 139,</i> un cours d’eau, des fleuves ; ἀνθρώπους, XÉN. <i>An. 4, 5, 3,</i> geler des hommes, <i>en parl. du froid ; au pass</i>. se solidifier, se cristalliser, <i>en parl. du sel,</i> HDT. <i>4, 53 ;</i> cailler, <i>en parl. du lait,</i> ARSTT. <i>P.A. 3, 15 ;</i> geler, <i>en parl. de l’eau,</i> XÉN. <i>An. 7, 4, 3 ;</i> PLAT. <i>Tim. 49</i> b, <i>etc. ; en parl. des articulations,</i> se raidir, IL. <i>22, 453 ; fig</i>. être glacé d’effroi, demeurer immobile de stupeur, ANTIPH. (ATH. <i>224</i> d) ; HLD. <i>2, 13 ;</i><br><b>   IV</b> <i>en gén</i>. fixer solidement, rendre ferme, consistant : ὅρκος παγείς, EUR. <i>I.A. 395,</i> serment confirmé solennellement ; ὅρκου πῆγμα παγέν, ESCHL. <i>Ag. 1198,</i> fixité d’un serment confirmé solennellement ;<br><b>B</b> <i>intr. (au pf.2</i> πέπηγα <i>et au pl.q.pf</i>. ἐπεπήγειν) :<br><b>   I</b> s’enfoncer, être enfoncé, HDT. <i>7, 64 ;</i> ATT. ; ἐν γῇ, SOPH. <i>Aj. 819,</i> dans la terre ; δόρυ ἐν κραδίῃ ἐπεπήγει, IL. <i>13, 442,</i> la javeline était restée enfoncée dans le cœur ;<br><b>   II</b> se fixer, <i>particul</i>. avoir les yeux fixés : πρός τι, PLAT. <i>Rsp. 530</i> d ; ἔς τι, PHILSTR. <i>882,</i> vers qqe ch., sur qqe ch. ; <i>avec un inf</i>. ἀρέσκειν τινί, PLAT. <i>Rsp. 605</i> a, avoir pour but de plaire à qqn ;<br><b>   III</b> être formé de parties solidement ajustées, CHRYS. ;<br><b>   IV</b> être congelé, être gelé, <i>d’où, en gén</i>. être raidi, <i>en parl. d’articulations,</i> EUR. <i>H.f. 1395</i> ;<br><i><b>Moy</b>. :</i><br><b>      1</b> enfoncer qqe ch. de soi : χείλεα ἐν ἀλλήλοις, ANTH. <i>5, 255,</i> fixer ses lèvres l’un sur l’autre, <i>càd</i>. s’embrasser ;<br><b>      2</b> assembler <i>ou</i> construire pour soi, <i>acc</i>. OD. <i>5, 163 ;</i> HÉS. <i>O. 807, etc. ;</i> HDT. <i>5, 83, etc. ;</i><br><b>      3</b> faire coaguler pour soi : τυρούς, LUC. <i>V.H. 1, 24,</i> se faire du fromage.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. dor</i>. πάξω, PD. <i>O. 6, 3 ; ao. dor</i>. ἔπαξα, PD. <i>N. 7, 26, etc. ; part. dor</i>. πάξαις, PD. <i>O. 11, 45. Pf. dor</i>. πέπαγα <span>[πᾱ]</span> ALC. <i>34. Pl.q.pf. 3 sg</i>. ἐπεπήγει <i>et poét</i>. πεπήγει, IL. <i>13, 442 ; 16, 772. Pass. ao. 3 pl</i>. πῆχθεν, IL. <i>8, 298 ; sbj. dor. 3 sg</i>. παχθῇ, THCR. <i>Idyl. 23, 31. Pass. ao.2, 3 pl. épq</i>. πάγεν, IL. <i>11, 572. Moy. ao. dor</i>. ἐπαξάμην, PD. <i>fr. 140 Bgk ; 2 sg</i>. ἐπάξα, THCR. <i>Idyl. 4, 28</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *peh₂ǵ-, coaguler, fixer ; <i>cf. lat</i>. pangō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηγνυμι - πήγνυμι</font>\n<br><br>forme prolongée d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4079":"<h1>pedalion</h1>\n<p>Strong n° 4079 <i>Prononciation [pay-dal'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le gouvernail d'un navire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πηδάλιον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>   I</b> gouvernail, <i>particul</i>. partie plate, et qui plonge dans l’eau, du gouvernail, <i>p. opp. à</i> οἴαξ, OD. <i>3, 280 ; 5, 255, 270, 315 ;</i> HÉS. <i>O. 45, 677 ;</i> HDT. <i>2, 96 ; fig</i>. PD. <i>P. 1, 166 ;</i> PLAT. <i>Clit. 408</i> b ; <i>p. anal</i>. barre <i>ou</i> traverse de bois, dans le frein du cheval, ESCHL. <i>Sept. 206 ;</i><br><b>   II</b> <i>p. anal. au plur. :</i><br><b>      1</b> pieds de derrière d’une sauterelle, ARSTT. <i>H.A. 4, 7, 9 ;</i><br><b>      2</b> <i>autre n. de la plante</i> πολύγονον, DIOSC. <i>4, 4</i>.<br><span><b>Étym</b>. πηδόν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηδαλιον - πηδάλιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4080":"<h1>pelikos</h1>\n<p>Strong n° 4080 <i>Prononciation [pay-lee'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>combien est grand\n<ol type=\"a\">\n<li>dans une référence matérielle (dénotant une grandeur géométrique distincte de l'arithmétique)</li>\n<li>dans un sens moral : qu'il est distingué !</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πηλίκος, η, ον</b> <span>[ῐ]</span><br><b>   I</b> <i>adj. interr. :</i><br><b>      1</b> combien grand ? de quelle grandeur ? PLAT. <i>Men. 82</i> d, <i>etc. ;</i> DÉM. <i>432, 22, joint à</i> πόσος, POL. <i>1, 2, 8, etc. ;</i><br><b>      2</b> combien âgé ? de quel âge ? XÉNOPHAN. (ATH. <i>54</i> f) ;<br><b>   II</b> <i>adj. indéf</i>. d’un certain âge, ARSTT. <i>Nic. 5, 6, 8</i>.<br><span><b>Étym</b>. *πός, ἡλίκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηλικος - πηλίκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4081":"<h1>pelos</h1>\n<p>Strong n° 4081 Prononciation [pay-los']</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>argile, glaise, que les potiers utilisent</li>\n<li>boue (argile mouillée)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πηλός, οῦ (ὁ) :<br>   I</b> matière liquide épaissie, <i>d’où :</i><br><b>      1</b> boue, HDT. <i>4, 28 ;</i> fange, ESCHL. <i>Ch. 697 ;</i> THC. <i>2, 4 ; 7, 84 ;</i> PLAT. <i>Rsp. 363</i> d ; AR. <i>Vesp. 248 ; au pl</i>. POL. <i>3, 79, 9 et 11 ;</i><br><b>      2</b> lie de vin, SOPH. <i>fr. 928 Dind. ; d’où</i> vin tourné, ATH. <i>383</i> c ; <i>p. ext</i>. vin, TRIPHIOD. <i>349 ;</i><br><b>   II</b> argile, terre glaise, HDT. <i>2, 36, etc. ;</i> THC. <i>2, 76 ;</i> SOPH. <i>fr. 432 ;</i> AR. <i>Av. 839 ;</i> PLAT. <i>Theæt. 147</i> a ; <i>d’où</i> mortier, THC. <i>1, 93 ; fig</i>. matière dont l’homme est formé, AR. <i>Av. 686 ;</i> CALL. <i>fr. 87 ;</i> πηλὸς ἠχυρωμένος <i>ou</i> τετριχωμένος, PLUT. <i>Dem. 11,</i> mortier mélangé de paille, torchis.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηλος - πηλός</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (5)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4082":"<h1>pera</h1>\n<p>Strong n° 4082 <i>Prononciation [pay'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un portefeuille</li>\n<li>un sac en cuir, dans lequel les voyageurs et bergers transportaient leurs provisions</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πήρα, ας (ἡ)</b> besace, sac de cuir, sac <i>ou</i> poche, <i>en gén</i>. OD. <i>13, 437 ; 17, 197, 357, 411, 466 ;</i> AR. <i>Pl. 298, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πήρη, OD. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηρα - πήρα</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n</ul>\n</td></tr>\n</table>","G4083":"<h1>pechus</h1>\n<p>Strong n° 4083 <i>Prononciation [pay'-khoos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une coudée</li>\n<li>une mesure de longueur égale à la distance du joint du coude au bout du majeur (environ 50 cm) sa longueur précise étant variable et discutée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πῆχυς, εως (ὁ) :<br>   I</b> coude, IL. <i>21, 166 ;</i> XÉN. <i>Hipp. 12, 5, etc. ; p. ext</i>. bras, IL. <i>5, 314 ;</i> OD. <i>17, 38 ; 24, 347, etc. ;</i> EUR. <i>Or. 1466, Her. 728, etc. ; fig</i>. coudée, aune, <i>mesure de longueur de la pointe du coude à celle du médius valant 2</i> σπιθαμαί <i>ou 6</i> παλασταί <i>ou 24</i> δάκτυλοι, HDT. <i>1, 178, etc. ;</i> XÉN. <i>An. 4, 7, 16 ;</i> AR. <i>Ran. 799 ;</i> PLAT. <i>1 Alc. 126</i> d ; EUR. <i>Cycl. 396, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> équerre, instrument de géomètre, ANTH. <i>6, 204, etc. ;</i><br><b>      2</b> angle, P. SIL. <i>Ecphr. ag. Soph. 150 ;</i><br><b>      3</b> courbure du milieu de l’arc, IL. <i>11, 375 ;</i> OD. <i>21, 419 ;</i><br><b>      4</b> milieu recourbé du fléau d’une balance, Ps.-JAMBL. <i>Theol. arithm. p. 29 ;</i><br><b>      5</b> montants <i>ou</i> bras d’une lyre, réunis par une barre transversale, HDT. <i>4, 192 ;</i> LUC. <i>D. deor. 7, 4, 4 ;</i><br><b>      6</b> figurines de petits hommes grands comme le coude, <i>càd</i>. des Pygmées représentés sur les tableaux du dieu Nil comme folâtrant autour de lui, LUC. <i>Rh. præc. 6 ;</i> PHILSTR. <i>p. 869</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att. gén. pl</i>. πήχεων (<i>non</i> πηχῶν) CIA. <i>2, add. 834, c, 15 (329 av. J.C.) ; v. Meisterh. p. 108, § 53, 2</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *b<sup>h</sup>eh₂ǵ-u-, avant-bras, coude ; <i>cf. sscr</i>. bāhú-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πηχυς - πῆχυς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4084":"<h1>piazo</h1>\n<p>Strong n° 4084 <i>Prononciation [pee-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se saisir de</li>\n<li>prendre, capturer\n<ol type=\"a\">\n<li>des poissons</li>\n</ol>\n</li>\n<li>saisir, appréhender\n<ol type=\"a\">\n<li>un homme, dans le but de l'emprisonner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πιάζω</b> <span>(<i>impf</i>. ἐπίαζον, <i>ao</i>. ἐπίασα <span>[ᾰ]</span>, <i>f. et pf. inus. ; pass. f</i>. πιασθήσομαι, <i>ao</i>. ἐπιάσθην, <i>pf</i>. πεπίασμαι)</span><br><b>      1</b> serrer, presser, tenir fermement : ταῦρον ὁπλᾶς, THCR. <i>Idyl. 4, 35,</i> tenir solidement, un taureau par le sabot ;<br><b>      2</b> saisir : τινὰ τῆς χειρός, NT. <i>Ap. 3, 7,</i> qqn par la main, <i>d’où</i> prendre, faire prisonnier, <i>acc</i>. SPT. <i>Sir. 23, 21</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Part. ao. dor</i>. πιάξας, THCR. <i>Idyl. l. c</i>.<br><span><b>Étym</b>. <i>cf</i>. πιέζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιαζω - πιάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (8)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4085":"<h1>piezo</h1>\n<p>Strong n° 4085 <i>Prononciation [pee-ed'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>presser, serrer ensemble, comprimer, tasser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πιέζω</b> <span>(<i>f</i>. έσω, <i>ao</i>. ἐπίεσα, <i>pf. inus. ; pass. ao</i>. ἐπιέσθην, <i>pf</i>. πεπίεσμαι)</span> serrer, presser, étreindre :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> χειρὶ π. βραχίονα, IL. <i>16, 510 ;</i> χειρὶ πόδα π., HÉS. <i>O. 497,</i> étreindre de la main le bras, le pied ; π. τινὰ ἐν δεσμοῖς, OD. <i>8, 336 ; 12, 164,</i> serrer qqn dans des liens ; <i>abs</i>. XÉN. <i>Mem. 3, 10, 13 ;</i> ARSTT. <i>Rhet. 1, 5, 9 ; joint à</i> ἐχέμεν, OD. <i>4, 419 ; p. opp. à</i> χαλᾶν, HPC. <i>755</i> a ; <i>au pass</i>. être pressé, être courbé, se courber sous le poids de qqe ch. AR. <i>Ran. 30 ;</i> XÉN. <i>Cyr. 7, 5, 11 ;</i><br><b>      2</b> serrer de près : <i>en parl. de l’ennemi, acc</i>. HDT. <i>4, 11 ; 9, 63 ;</i> POL. <i>5, 29, 1 ; au pass</i>. THC. <i>1, 49,</i> XÉN. <i>Hell. 2, 4, 34 ; 7, 1, 43 ;</i> POL. <i>3, 74, 2 ;</i> PLUT. <i>Cam. 2, etc. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> presser : τινὰ λιμῷ, XÉN. <i>Hell. 2, 3, 41,</i> réduire qqn à la famine ; <i>cf</i>. ESCHL. <i>Ch. 250 ;</i> EUR. <i>Suppl. 249 ;</i> THC. <i>2, 52 ; au pass</i>. être pressé, accablé (par le malheur, la maladie, <i>etc.) dat</i>. THC. <i>2, 52 ;</i> XÉN. <i>Cyr. 7, 2, 20, etc. ;</i> ὑπό <i>et le gén</i>. THC. <i>1, 126 ;</i> ὑπό <i>et le dat</i>. SOL. <i>fr. 12 (4), 35 Bgk ; abs</i>. πιέζεσθαι, tomber dans le besoin, dans la misère, dans la disette, XÉN. <i>Hell. 7, 2, 1, etc. ;</i><br><b>      2</b> pousser qqn au pied du mur, réfuter, PLAT. <i>Crat. 405</i> a ; PLUT. <i>Alc. 6 ;</i><br><b>      3</b> presser, insister sur, prendre particulièrement en considération, <i>acc</i>. PLAT. <i>Leg. 965</i> d ; PLUT. <i>M. 31</i> e, <i>etc. ; avec</i> ἐπί <i>et l’acc</i>. POL. <i>3, 21, 8 ;</i><br><b>      4</b> réprimer, refouler (la colère) <i>acc</i>. PD. <i>O. 6, 61</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. part. ao. dor</i>. πιέσαις, PD. <i>O. 6, 37 ; ao. ion</i>. ἐπίεξα, HPC. <i>3, 434 (dout.) ; ao. pass</i>. ἐπιέχθην, HPC. <i>3, 324, etc., pf</i>. πεπίεγμαι, HPC. <i>3, 442, d’où inf</i>. πεπιέχθαι, HPC. <i>3, 432, etc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιεζω - πιέζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4086":"<h1>pithanologia</h1>\n<p>Strong n° 4086 <i>Prononciation [pith-an-ol-og-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parole adaptée pour persuader, discours dans lequel des arguments intéressants sont avancés</li>\n<li>dans un mauvais sens, discours persuasif, spécieux, conduisant les autres à l'erreur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πιθανολογία, ας (ἡ)</b> <span>[ῐθᾰ]</span> langage persuasif, raison spécieuse, PLAT. <i>Theæt. 163</i> a ; NT. <i>Col. 2, 4</i>.<br><span><b>Étym</b>. πιθανολόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιθανολογια - πιθανολογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4087":"<h1>pikraino</h1>\n<p>Strong n° 4087 <i>Prononciation [pik-rah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre amer\n<ol type=\"a\">\n<li>produire un goût amer dans l'estomac</li>\n</ol>\n</li>\n<li>aigrir, envenimer, exaspérer\n<ol type=\"a\">\n<li>rendre fâché, indigné</li>\n<li>être aigri, irrité</li>\n<li>visité par l'amertume, chagriner (traiter amèrement)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πικραίνω</b> <span>(<i>f</i>. ανῶ, <i>ao</i>. ἐπίκρανα <span>[ᾱν]</span>, <i>pf. inus. ; pass. f</i>. πικρανθήσομαι, <i>ao</i>. ἐπικράνθην)</span><br><b>      1</b> rendre amer, <i>acc</i>. NT. <i>Apoc. 10, 9 ; fig</i>. aigrir, irriter, SPT. <i>Job 27, 2 ; d’où au pass</i>. s’aigrir, s’irriter, PLAT. <i>Leg. 731</i> c ; DÉM. <i>1464, 18 ;</i> πρός τινα, LYNC. (ATH. <i>242</i> c) contre qqn ; <i>ou simpl</i>. se dépiter, se décourager, ANTIPH. (ATH. <i>258</i> d) ;<br><b>      2</b> rendre dur, <i>acc. en parl. du style,</i> DH. <i>Dem. 34, 55</i>.<br><span><b>Étym</b>. πικρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πικραινω - πικραίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Colossiens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4088":"<h1>pikria</h1>\n<p>Strong n° 4088 <i>Prononciation [pik-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fiel amer\n<ol type=\"a\">\n<li>méchanceté extrême</li>\n<li>une racine amère, et ainsi produisant un fruit amer</li>\n<li>métaph. amertume, haine amère</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πικρία, ας (ἡ) :<br>   I</b> amertume, goût amer, ARSTT. <i>Plant. 2, 10, 1 ;</i> TH. <i>H.P. 6, 10, 7 ;</i> PLUT. <i>M. 897</i> a, <i>etc. ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> aigreur, colère, POL. <i>15, 4, 11 ;</i> PLUT. <i>Cor. 15 ;</i><br><b>      2</b> dureté, DÉM. <i>580, 1, etc. ;</i> PLUT. <i>Lyc. 19</i>.<br><span><b>Étym</b>. πικρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πικρια - πικρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4089":"<h1>pikros</h1>\n<p>Strong n° 4089 <i>Prononciation [pik-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amer</li>\n<li>métaph. rude, virulent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πικρός, ά, όν</b> <span>[ῑ ; <i>par exc</i>. ῐ, <i>v. ci-dessous</i>]</span><br><b>   I</b> piquant, aigu, <i>en parl. de traits,</i> IL. <i>4, 118, etc. ;</i> OD. <i>22, 8, etc. ;</i> SOPH. <i>Tr. 681 ; d’un aiguillon,</i> EUR. <i>H.f. 1288 ;</i><br><b>   II</b> <i>p. anal</i>. piquant, pénétrant, <i>d’où :</i><br><b>      1</b> <i>en parl. du goût,</i> amer (racine, IL. <i>11, 846 ;</i> eau de mer, OD. <i>5, 223 ;</i> larme, OD. <i>4, 153, etc.) ; p. opp. à</i> γλυκύς, PLAT. <i>Phil. 46</i> c, <i>etc. ;</i><br><b>      2</b> <i>en parl. d’odeurs,</i> âcre, pénétrant, OD. <i>4, 406 ;</i><br><b>      3</b> <i>en parl. du toucher,</i> aigre, piquant, pénétrant (mal, douleur, <i>etc</i>.) IL. <i>11, 271 ;</i> SOPH. <i>Tr. 41 ;</i><br><b>      4</b> <i>en parl. du son,</i> aigu, perçant, SOPH. <i>Ph. 189, O.C. 1610, etc. ;</i> AR. <i>Pax 805 ;</i><br><b>      5</b> <i>fig</i>. âpre, dur, cruel, <i>en parl. de choses,</i> OD. <i>17, 448 ;</i> ESCHL. <i>Ag. 745 ;</i> SOPH. <i>Aj. 1239 ;</i> EUR. <i>Hel. 482 ;</i> PLAT. <i>Gorg. 522</i> b ; DÉM. <i>261, 1, etc. ; en parl. de pers</i>. dur, cruel, ESCHL. <i>Pr. 739, etc. ;</i> τινι, ESCHL. <i>Ch. 234 ;</i> ἔς τινα, HDT. <i>1, 123,</i> pour qqn ; <i>d’où</i> odieux à, haï de : θεοῖς, SOPH. <i>Ph. 254,</i> haï des dieux ; <i>cf</i>. EUR. <i>Ph. 956 ; particul</i>. irritable, violent, ARSTT. <i>Nic. 4, 5</i>.<br><span>•<i> Cp</i>. -ότερος, ESCHL. <i>Suppl. 875 ;</i> ANT. <i>116, 40 ;</i> ISOCR. <i>246</i> a, <i>etc.</i> <i>• Sup</i>. -ότατος, PD. <i>I. 7, 68 ;</i> EUR. <i>Hec. 772 ;</i> AR. <i>Pax 805, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> SOPH. <i>Aj. 500 ;</i> THCR. <i>Idyl. 8, 74. Fém</i>. -ός, OD. <i>4, 406</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *piḱ-ro-, varié, bariolé ; <i>cf. sscr</i>. piṃśáti « couper sur mesure, orner », <i>v</i>. ποικίλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πικρος - πικρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G4090":"<h1>pikros</h1>\n<p>Strong n° 4090 <i>Prononciation [pik-roce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amèrement, avec amertume</li>\n<li>métaph. avec un chagrin poignant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πικρῶς</b>, <i>adv</i>., amèrement, avec amertume ; <i>fig. càd. :</i><br><b>      1</b> avec aigreur, EUR. <i>Ion 610, etc. ; Andr. 189 ;</i> POL. <i>1, 72, 5 ; 4, 14, 1, etc. ;</i><br><b>      2</b> cruellement, durement, ESCHL. <i>Pr. 195 ;</i> SOPH. <i>O.C. 994 ;</i> DÉM. <i>26, 3, etc</i>.<br><span>•<i> Cp</i>. -ότερον, MÉN. <i>Monost. 659, etc. ;</i> <i>• Sup</i>. -ότατα, POL. <i>1, 72, 3</i>.<br><span><b>Étym</b>. πικρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πικρως - πικρῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4091":"<h1>Pilatos</h1>\n<p>Strong n° 4091 <i>Prononciation [pil-at'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pilate = « armé d'une lance »\n<ol><li>le sixième procurateur Romain de Juda et Samarie qui ordonna la crucifixion de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πιλᾶτος, ου (ὁ)</b> <span>[ῑᾱ]</span> = <i>lat</i>. Pilatus, Pilate, <i>gouverneur romain en Judée,</i> NT. <i>Luc. 3, 1, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐᾰ]</span> NONN. <i>Jo. 18, 140, 156, 174, 180 ;</i> <span>[ῐᾱ]</span> Ps.-LACT. <i>Pass. Chr. 35</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πιλατος - Πιλᾶτος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n55 fois dans 53 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (10)</li>\n<li>Luc (12)</li>\n<li>Jean (20)</li>\n<li>Actes (3)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4092":"<h1>pimpremi</h1>\n<p>Strong n° 4092 <i>Prononciation [pim'-pray-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souffler, brûler</li>\n<li>faire gonfler, rendre timide</li>\n<li>enfler, devenir enflé\n<ol type=\"a\">\n<li>des parties du corps</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πίμπρημι</b> <span>(<i>impf</i>. ἐπίμπρην, <i>f</i>. πρήσω, <i>ao</i>. ἔπρησα, <i>pf</i>. πέπρηκα ; <i>pass. ao</i>. ἐπρήσθην, <i>pf</i>. πέπρημαι <i>et</i> πέπρησμαι)</span> brûler, incendier : ναῦς, EUR. <i>Tr. 81 ;</i> πόλιν, ESCHL. <i>Sept. 434 ;</i> des vaisseaux, une ville, <i>etc. ;</i> γῆν πυρί, SOPH. <i>Ant. 201</i>, mettre un pays à feu et à sang ; <i>ou avec le gén. :</i> πυρὸς θύρετρα, IL. <i>2, 415</i>, détruire des portes par le feu ; <i>au pass</i>. être brûlé, AR. <i>Lys. 341 ; p. anal</i>. être consumé par la fièvre, PHÉRÉCR. (ATH. <i>75</i> b) ; <i>en parl. de blessures,</i> être enflammé, NIC. <i>Th. 306 ; fig</i>. s’enflammer (de colère) : ἐπί τινι, LUC. <i>J. voc. 8</i>, au sujet de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér</i>. πίμπρη, EUR. <i>Ion 527, 974</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *prh₁-, souffler, brûler ; <i>cf</i>. *πρήθω ; <i>pour la format. cf</i>. πίμπλημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιμπρημι - πίμπρημι</font>\n<br><br>vient d'une forme d'un mot primaire preo (preh'-o)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4093":"<h1>pinakidion</h1>\n<p>Strong n° 4093 <i>Prononciation [pin-ak-id'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une petite tablette</li>\n<li>une tablette pour écrire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πινακίδιον, ου (τὸ)</b> <span>[ῐᾰῐδ]</span> tablette, HPC. <i>1199</i> f ; ARSTT. <i>Mir. 57, 2 ; particul</i>. tablette pour écrire, PLUT. <i>Eum. 1, etc</i>.<br><span><b>Étym</b>. <i>dim. de</i> πινακίς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πινακιδιον - πινακίδιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4094":"<h1>pinax</h1>\n<p>Strong n° 4094 <i>Prononciation [pin'-ax]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une planche, une tablette</li>\n<li>un plat, une plaque</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πίναξ, ακος (ὁ)</b> <span>[ῐᾰκ]</span> planche, ais, OD. <i>12, 67 ;</i> OPP. <i>H. 1, 194 ; particul. :</i><br><b>      1</b> plat pour servir les mets, assiette, <i>primit. en bois, postér. en terre ou en métal,</i> OD. <i>1, 141 ; 16, 49 ;</i> MÉTAG. (ATH. <i>228</i> e) ; MATR. (ATH. <i>135</i> d) ; DH. <i>2, 23, etc. ;</i><br><b>      2</b> tablette pour tracer des signes, IL. <i>6, 169 ; ou</i> pour écrire, ESCHL. <i>Suppl. 946 ;</i> AR. <i>Th. 778 ;</i> PLAT. <i>Criti. 120</i> c ;<br><b>      3</b> planche pour peindre, TH. <i>H.P. 5, 7, 4 ;</i> ATH. <i>543</i> f ; <i>d’où</i> tableau, PLUT. <i>Pel. 25, M. 232</i> e, <i>etc. ;</i> ARSTT. <i>Pol. 8, 6, etc. ;</i><br><b>      4</b> carte géographique, HDT. <i>5, 49 ;</i> PLUT. <i>Thes. 1 ;</i><br><b>      5</b> table d’astrologie, planche magique des diseurs de bonne aventure, PLUT. <i>Rom. 12, M. 386</i> b ;<br><b>      6</b> planche d’affichage, <i>d’où</i> liste, PLUT. <i>Syll. 26 ;</i> catalogue, ATH. <i>585</i> b ; <i>particul</i>. Catalogue, <i>titre d’un ouvrage de Callimaque,</i> ATH. <i>244</i> a ;<br><b>      7</b> cuir à rasoir, TH. <i>C.P. 5, 5, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. épq</i>. πινάκεσσιν, OPP. <i>l. c</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιναξ - πίναξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4095":"<h1>pino</h1>\n<p>Strong n° 4095 <i>Prononciation [pee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>boire</li>\n<li>au figuré, recevoir dans l'âme ce qui sert à la rafraîchir, la fortifier, la nourrir jusqu'à la vie éternelle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πίνω</b> <span>(<i>f</i>. πίομαι, <i>postér</i>. πιοῦμαι, <i>ao.2</i> ἔπιον, <i>pf</i>. πέπωκα ; <i>pass. ao</i>. ἐπόθην, <i>pf</i>. πέπομαι)</span> <span>[ῑ <i>prés. et impf., au fut</i>. ῑ <i>épq. et</i> ῐ <i>v. ci-dessous ; à l’ao</i>. ῐ <i>excepté à l’impér</i>. πῖθι]</span> boire :<br><b>   I</b> <i>en parl. de l’homme et des animaux :</i><br><b>      1</b> <i>au propre, joint à</i> ἐσθίω, IL. <i>24, 476, etc. ;</i> OD. <i>5, 94, etc. ; à</i> φαγέμεν, OD. <i>15, 378 ; à</i> δαινυμένω, OD. <i>15, 398, etc. ; avec l’acc. :</i> οἶνον, PLAT. <i>Conv. 211</i> d, <i>etc. ;</i> HOM. ATT. boire du vin ; φάρμακα, OD. <i>10, 326</i>, boire des breuvages préparés ; <i>avec le gén. partit</i>. οἴνοιο, OD. <i>22, 11</i>, boire une part de vin, boire du vin ; αἵματος, OD. <i>11, 96</i>, boire du sang ; <i>avec l’acc. du contenant :</i> οἴνοιο κύπελλα, IL. <i>4, 346 ;</i> κρητῆρας οἴνοιο, IL. <i>8, 232</i>, boire des coupes, des cratères de vin ; <i>en prose :</i> κύλικα, LUC. <i>Tox. 63</i>, boire une coupe ; πιεῖν αἰτεῖν, XÉN. <i>Cyr. 8, 3, 41</i>, demander à boire ; πινεῖν δοῦναι, HDT. <i>4, 172, etc</i>. donner à boire ; πιεῖν ἐγχεῖν, XÉN. <i>Cyr. 1, 3, 9</i>, verser à boire ; πιεῖν ἑλέσθαι, OD. <i>11, 584</i>, prendre à boire ; <i>avec le n. du lieu où l’on boit, au gén. :</i> π. κρήνης, THGN. <i>962 ;</i> ποταμοῦ, LUC. <i>Bacch. 6</i>, boire à une source, à un fleuve ; <i>ou au gén. précédé d’une prép. :</i> ἀπὸ κρήνης, THGN. <i>959 ;</i> ἀπὸ ποταμοῦ, XÉN. <i>Cyr. 4, 5, 4</i>, à une source, à un fleuve ; <i>de même avec le n. de l’instrument avec lequel on boit, au gén. précédé d’une prép. :</i> ἐκ κεράμων, IL. <i>9, 469</i> (du vin) des cruches ; ἐξ ἀργυρίου ἢ χρυσοῦ, XÉN. <i>Cyr. 5, 3, 3</i>, avec un vase d’argent ou d’or ; ἐκ χειρός, HDT. <i>4, 172</i>, boire dans la main ; ἀπ' αὐτοῦ (δέπαος), IL. <i>16, 226</i>, dans la coupe ; φάρμακον π. παρὰ τοῦ ἰατροῦ, PLAT. <i>Rsp. 406</i> d, boire une potion ordonnée par le médecin ; π. πρὸς βίαν, ALC. <i>20,</i> boire de force ; π. πρὸς ἡδονήν, PLAT. <i>Conv. 176</i> e, boire par plaisir ; π. εἰς μέθην, PLAT. <i>Leg. 775</i> b, boire jusqu’à l’ivresse ; <i>en parl. d’animaux :</i> μῆλα πιόμεν' ἐκ βοτάνης, IL. <i>13, 493</i>, moutons qui vont s’abreuver au sortir du pâturage ; πίνειν ὕδωρ Αἰσήποιο, IL. <i>2, 825</i>, boire l’eau de l’Æsèpos, <i>càd</i>. demeurer au bord de l’Æsèpos ;<br><b>      2</b> <i>fig</i>. avaler, engloutir, <i>d’où</i> ruiner, <i>au pass</i>. ANTH. <i>5, 44 ;</i><br><b>   II</b> <i>en parl. de choses :</i> αἷμα, ESCHL. <i>Sept. 736, 821 ; Eum. 980 ;</i> SOPH. <i>O.R. 1401</i>, boire du sang, <i>en parl. de la terre ;</i> ὕδωρ, XÉN. <i>Conv. 2, 25</i>, boire de l’eau, <i>en parl. de plantes ;</i> τοὔλαιον, LUC. <i>Cat. 27</i>, boire l’huile, <i>en parl. d’une lampe, etc. ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. PD. <i>O. 6, 147 ;</i> THGN. <i>962 ;</i> NIC. <i>Th. 912, m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. inf. épq</i>. πινέμεναι, IL. <i>4, 346 et</i> πινέμεν, OD. <i>7, 220 ;</i> HÉS. <i>O. 592. Impf. itér</i>. πίνεσκον, IL. <i>16, 226. Fut</i>. πίομαι <span>[ῑ]</span> IL. <i>13, 493 ;</i> ESCHL. <i>Ch. 578, etc. ; d’où 2 sg</i>. πίεσαι, SPT. <i>Ezech. 23, 34 ;</i> NT. <i>Luc. 17, 8 ; mais</i> πίομαι <span>[ῐ]</span> ION <i>2, 10 Bgk ;</i> PLAT. COM. <i>2-2, 668 Mein. ;</i> πιοῦμαι <span>[ῐ]</span> HPC. <i>538, 16 ;</i> XÉN. <i>Conv. 4, 7 ;</i> ARSTT. <i>Rhet. 1, 11, 10 ;</i> EL. <i>V.H. 12, 49 ; ao.2 impér. poét</i>. πίε, OD. <i>9, 347 ;</i> MÉN. (<i>Com. fr. 4, 113</i>) ; LUC. <i>D. mort. 13, 6 ; att</i>. πῖθι, AR. <i>Vesp. 1489 ;</i> CRAT. (<i>Com. fr. 2, 96</i>) ; LUC. <i>Lex. 20 ; sbj. 2 sg. épq</i>. πίῃσθα, IL. <i>6, 260 ; inf. ion</i>. πιέειν, IL. <i>4, 263 ; 7, 481 ;</i> OD. <i>11, 232, etc. ; épq</i>. πιέμεν <span>[ῐ]</span> OD. <i>15, 378 ;</i> <span>[ῑ]</span> IL. <i>16, 825 ;</i> OD. <i>16, 143 ; 18, 3 ; poét</i>. πίν <i>ou</i> πῖν (<i>p</i>. πιεῖν) ANTH. <i>11, 140 ; part. fém. ion</i>. πιέουσα, HPC. <i>1213</i> d. <i>Pass. impf. 3 sg. poét</i>. πίνετο, OD. <i>9, 45 ; part. ion</i>. πινεύμενος, HPC. <i>286, 18. Moy. prés. impér. 2 sg. épq</i>. πίνεο, NIC. <i>Th. 912 ; part. gén</i>. πινομένοιο, OD. <i>20, 312</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *p(e)h₃-, *p(e)h₃-i-, boire ; <i>cf</i>. ποτός, πόμα, πόσις, πῶμα, <i>lat</i>. bibō, <i>avec redoubl.,</i> pōtus, pōculum.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πινω - πίνω</font>\n<br><br>une forme prolongée de pio (pee'-o)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n74 fois dans 65 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (10)</li>\n<li>Luc (17)</li>\n<li>Jean (11)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (14)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4096":"<h1>piotes</h1>\n<p>Strong n° 4096 <i>Prononciation [pee-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>embonpoint</li>\n<li>hébraïsme « racine pleine de sève huileuse »</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πιότης, ητος (ἡ)</b> <span>[ῑ]</span><br><b>      1</b> graisse, HPC. <i>Aër. 292 ;</i> ARSTT. <i>H.A. 3, 17, 4, etc. ;</i> TH. <i>H.P. 9, 1, 3 ;</i> LUC. <i>Am. 14 ;</i><br><b>      2</b> <i>fig</i>. opulence, PHIL. <i>1, 299, etc</i>.<br><span><b>Étym</b>. πίων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιοτης - πιότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4097":"<h1>piprasko</h1>\n<p>Strong n° 4097 <i>Prononciation [pip-ras'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vendre\n<ol type=\"a\">\n<li>prix, celui qui est en esclavage</li>\n<li>maître à qui est vendu un esclave</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>vendu au péché, entièrement sous le contrôle de l'amour du péché</li>\n<li>de celui obligé de se livrer entièrement à la volonté d'un autre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πιπράσκω</b> <span>(<i>impf</i>. ἐπίπρασκον, <i>f</i>. περάσω, <i>att</i>. περῶ <span>[ᾰ]</span>, <i>ao</i>. ἐπέρασα <span>[ρᾰ]</span>, <i>pf</i>. πέπρακα <span>[ᾱκ]</span>, <i>pl.q.pf</i>. ἐπεπράκειν <span>[ᾱ]</span>; <i>pass. f</i>. πραθήσομαι <span>[ᾱ]</span>, <i>ao</i>. ἐπράθην <span>[ᾱ]</span>, <i>pf</i>. πέπραμαι <span>[ᾱ]</span>, <i>pl.q.pf</i>. ἐπεπράμην <span>[ᾱ]</span>, <i>f. ant</i>. πεπράσομαι <span>[ᾱ]</span>)</span> transporter pour vendre, <i>en parl. de pers</i>. (prisonniers, esclaves, <i>etc</i>.) ANACR. <i>14, 11 ;</i> PLUT. <i>M. 178</i> c ; <i>au pass</i>. ESCHL. <i>Ch. 132, etc. ;</i> EUR. <i>Tr. 936 ;</i> HDT. <i>1, 156 ;</i> XÉN. <i>Hell. 6, 2, 15, etc. ;</i> πρ. τινι, SOPH. <i>Tr. 252</i>, être vendu à qqn ; <i>en parl. de choses :</i> π. τί τινι, LUC. <i>As. 32</i>, vendre qqe ch. à qqn ; π. ἑαυτόν, DÉM. <i>244, 10</i>, se vendre soi-même, <i>càd</i>. se laisser corrompre ; π. ἑαυτόν τινι, DÉM. <i>148, 8</i>, se vendre à qqn ; <i>avec le gén. de prix :</i> π. πέντε ταλάντων, IS. <i>66, 34</i>, vendre cinq talents ; <i>cf</i>. XÉN. <i>An. 7, 7, 86 ;</i> LYS. <i>151, 12, etc. ; fig</i>. vendre, trahir ; τὸ πρᾶγμά τινι, DÉM. <i>739, 3</i>, vendre l’affaire à qqn ; <i>au pass</i>. être vendu, trahi, SOPH. <i>Ph. 978, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Au lieu des prés., fut. et ao. on emploie plutôt en prose att. ceux de</i> πωλῶ <i>et qqf. de</i> ἀποδίδομαι, <i>f</i>. ἀποδώσομαι, <i>ao.2</i> ἀπεδόμην (<i>v. Cobet N. L. p. 158</i>) ; <i>f. pass</i>. πραθήσομαι, <i>non att. — Conj. ion. en</i> -η : πιπρήσκω, HPC. <i>3, 593 ;</i> CALL. <i>fr. 185 ;</i> MAN. <i>6, 727 ; ao. pass</i>. ἐπρήθην, HDT. <i>1, 156, etc. ; pf</i>. πέπρημαι, HDT. <i>2, 56</i>.<br><span><b>Étym</b>. πέρνημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιπρασκω - πιπράσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4098":"<h1>pipto</h1>\n<p>Strong n° 4098 <i>Prononciation [pip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendre d'un lieu élevé vers un lieu plus bas\n<ol type=\"a\">\n<li>tomber (soit de où, ou vers)\n<ol>\n<li>être jeté à terre</li>\n</ol>\n</li>\n<li>métaph. tomber sous le jugement, venir sous la condamnation</li>\n</ol>\n</li>\n<li>descendre d'une position debout à une position de prosternation\n<ol type=\"a\">\n<li>tomber au sol\n<ol>\n<li>être abattu, prosterné, prostré</li>\n<li>de ceux qui sont vaincus par la terreur, le chagrin, ou sous l'attaque d'un mauvais esprit, tombant subitement morts</li>\n<li>le démembrement d'un corps par délabrement</li>\n<li>se prosterner</li>\n<li>utilisé pour ceux qui supplient et à ceux qui rendent hommage ou adoration</li>\n<li>tomber en ruine (constructions, murs etc.)</li>\n</ol>\n</li>\n<li>tomber depuis un état de prospérité\n<ol>\n<li>perdre son autorité, ne plus avoir de force\n<ol type=\"a\">\n<li>de dires, préceptes, etc.</li>\n</ol>\n</li>\n<li>perdre son pouvoir par la mort</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πίπτω</b> <span>(<i>f</i>. πεσοῦμαι, <i>ao.2</i> ἔπεσον, <i>pf</i>. πέπτωκα)</span> tomber, <i>càd. :</i><br><b>A</b> <i>avec un n. de pers. pour suj. :</i><br><b>   I</b> faire une chute :<br><b>      1</b> <i>avec idée d’une chute involontaire, en parl. de pers. et de choses :</i> πέσε πρηνής, IL. <i>6, 307, etc</i>. il tomba en avant ; πέσεν ὕπτιος, IL. <i>15, 435, etc. ;</i> OD. <i>9, 371, etc</i>. il tomba à la renverse ; πέσε δὲ λίθος εἴσω, IL. <i>12, 459</i>, la pierre tomba dedans ; <i>de même en parl. d’un mât,</i> OD. <i>12, 410 ; de la foudre,</i> ARSTT. <i>Meteor. 1, 4, etc. ; avec</i> ἐν <i>et le dat. pour marquer l’idée que la pers. ou la chose reste étendue à l’endroit où elle est tombée :</i> π. ἐν κονίῃσιν, IL. <i>11, 425</i>, tomber dans la poussière (et y rester couché) ; <i>cf</i>. OD. <i>22, 384 ;</i> THGN. <i>867 ;</i> ESCHL. <i>Pers. 125, etc. ; en prose :</i> π. ἐν ποταμῷ, XÉN. <i>Ages. 1, 32</i>, tomber dans un fleuve ; <i>de même avec d’autres prép. :</i> ἐπὶ χθονί, OD. <i>24, 535 ;</i> ἐπὶ γᾷ, SOPH. <i>Ant. 134</i>, tomber à terre, <i>en parl. d’armes ;</i> τινὶ ἐπὶ βλεφάροισι, OD. <i>2, 398</i>, tomber sur les paupières de qqn, <i>en parl. du sommeil ;</i> ὑπὸ ἄξοσι, IL. <i>16, 378</i>, tomber sous les roues ; <i>avec le dat. :</i> π. πεδίῳ, IL. <i>5, 82</i>, tomber dans la plaine ; πέδῳ, ESCHL. <i>Ch. 48, etc</i>. tomber à terre ; <i>avec</i> χαμαί, tomber sur la terre, tomber à terre, <i>en parl. de pers. :</i> ἐν κονίῃσι χαμαὶ π. IL. <i>4, 482, etc</i>. tomber à terre dans la poussière ; <i>d’ord. en parl. de choses,</i> IL. <i>13, 578, 617, etc. ;</i> OD. <i>18, 397, etc. ; fig</i>. χαμαὶ π. tomber à terre, <i>càd</i>. être vain, inutile, <i>en parl. de paroles,</i> PLAT. <i>Euthyphr. 14</i> d ; π. χαμᾶζε, AR. <i>Vesp. 1013, m. sign. ; avec un rég. de mouv</i>. π. ἐς πόντον, s’enfoncer dans la mer, <i>en parl. des Pléiades,</i> HÉS. <i>O. 618 ;</i> π. ἐπὶ γᾶν, ESCHL. <i>Ag. 1018 ;</i> ἐπὶ τὴν γῆν, PLAT. <i>Phædr. 248</i> c, tomber à terre ; π. χαμάδις, IL. <i>16, 118 ;</i> π. ἔραζε, IL. <i>12, 156 ; 17, 633 ;</i> OD. <i>22, 280, m. sign. ;</i> πρὸς οὖδας, EUR. <i>Hec. 405</i>, tomber contre le sol ; <i>avec une prép. marquant le lieu d’où l’on tombe :</i> π. ἐκ νηός, OD. <i>12, 417 ; 14, 307 ;</i> ESCHL. <i>Pers. 313</i>, tomber d’un vaisseau ; ἐκ χειρῶν ἐν κονίῃσιν, IL. <i>5, 583</i>, tomber des mains dans la poussière, <i>en parl. de rênes ; cf</i>. IL. <i>13, 530 ; 15, 714, etc. ;</i> ἀπ' ὤμων ἀσπὶς χαμαὶ πέσε, IL. <i>16, 803</i>, le bouclier tomba de ses épaules à terre ; π. ἀπ' οὐρανοῦ, ESCHL. <i>fr. 38, 3</i>, tomber du ciel, <i>en parl. de la pluie ;</i> π. ἀπ' ὄνου, PLAT. <i>Leg. 701</i> d, tomber de dessus un âne ;<br><b>      2</b> <i>avec idée d’une chute volontaire,</i> se précipiter, se jeter : ἠὲ πεσὼν ἐκ νηὸς ἀποφθίμην ἐνὶ πόντῳ, OD. <i>10, 51</i>, (je délibérai) si je me précipiterais du navire et périrais dans la mer ; <i>particul. avec idée d’hostilité,</i> tomber sur, fondre sur : ἐνὶ νήεσσι, IL. <i>13, 742</i>, sur les vaisseaux ; ἐπ' ἀλλήλοισι, HÉS. <i>Sc. 379</i>, se précipiter les uns contre les autres, <i>en parl. de combattants ;</i> ἐν βουσί, SOPH. <i>Aj. 374 ;</i> πρὸς μῆλα καὶ ποίμνας, SOPH. <i>Aj. 1061</i>, sur des bœufs, sur des moutons et des bergeries ; περὶ ξίφει, SOPH. <i>Aj. 828</i>, se précipiter sur son épée ; <i>abs. en parl. du vent qui se précipite avec furie,</i> OD. <i>14, 475 ; sans idée d’hostilité,</i> tomber sur les genoux, se jeter aux pieds de qqn, πρὸς βρέτη θεῶν, ESCHL. <i>Sept. 185</i>, devant les statues des dieux ; ἀμφὶ γόνυ τινός, EUR. <i>Hec. 787</i>, en embrassant les genoux de qqn ; <i>ttef</i>. π. εἰς γόνατα, A. PL. <i>24</i>, tomber à genoux, <i>en parl. d’un combattant qui succombe ; d’un cheval qui s’affaisse,</i> XÉN. <i>Cyr. 1, 4, 8 ;</i><br><b>   II</b> <i>particul</i>. tomber mort, succomber, IL. <i>8, 67 ;</i> OD. <i>8, 524, etc. ;</i> οἱ πεπτωκότες, XÉN. <i>Cyr. 1, 4, 24</i>, ceux qui sont tombés ; <i>joint à</i> θνῄσκοντες, IL. <i>1, 243 ; à</i> νέκυες, IL. <i>10, 200 ; à</i> νεκροί, EUR. <i>Ph. 881 ;</i> πίπτειν δορί, EUR. <i>Hec. 5</i>, tomber frappé par une lance ; ὑπό τινος, HDT. <i>9, 67 ;</i> PLUT. <i>Cato mi. 54, etc</i>. tomber par les mains de qqn, tomber <i>ou</i> être tué par qqn ; <i>en parl. de choses</i> (épis fauchés, IL. <i>11, 69 ; 18, 552 ;</i> arbres, branches, fleurs, fruits qui tombent, IL. <i>11, 158 ; 23, 120, etc. ;</i> ESCHL. <i>Sept. 358</i>) ; <i>fig</i>. ESCHL. <i>Pers. 252 ; en parl. de maisons, d’édifices,</i> s’écrouler, s’effondrer, PLAT. <i>Leg. 862</i> b ; ARSTT. <i>Pol. 6, 8 ;</i> τὰ πεπτωκότα, DC. <i>75, 12</i>, les ruines ; <i>en parl. de remparts détruits,</i> EUR. <i>Hec. 11, 1112 ;</i> ESCHN. <i>51, 11 ; de villes conquises et détruites,</i> EUR. <i>Rhes. 398 ;</i> PLAT. <i>Lach. 181</i> b ; <i>de peuples subjugués,</i> HDT. <i>7, 18 ;</i> DÉM. <i>510, 15 ; d’armées vaincues,</i> HDT. <i>8, 16 ;</i> THC. <i>2, 89, etc. ; de races ou de pers. déchues,</i> SOPH. <i>Tr. 84, O.R. 50, El. 429, etc. ; d’orgueil humilié,</i> ESCHL. <i>Sept. 794 ; d’espérances déçues,</i> POL. <i>1, 87, 1, etc. ; en parl. d’un poète,</i> échouer avec sa pièce, AR. <i>Eq. 530 ;</i><br><b>   III</b> tomber, <i>càd</i>. faire une faute, se tromper, manquer, <i>p. opp. à</i> ἀσφαλὲς εἶναι, PLAT. <i>Phæd. 100</i> e ;<br><b>   IV</b> <i>fig</i>. tomber dans, <i>càd</i>. en arriver à ; <i>en mauv. part :</i> εἰς ἄτην, SOL. <i>fr. 12, 68 Bgk ;</i> ἐς κακόν, εἰς κακά, εἰς ξυμφοράν, <i>etc</i>. ATT., dans le malheur ; εἰς νόσον, ESCHL. <i>Pr. 478</i>, tomber malade ; ἐς δάκρυα, HDT. <i>6, 21</i>, fondre en larmes ; <i>de même avec</i> ἐν <i>et le dat. :</i> ἐν ἀρκυστάτοις, SOPH. <i>El. 1471</i>, tomber dans un piège, <i>cf</i>. EUR. <i>H.f. 1092 ; avec le dat. :</i> π. δυσπραξίαις, SOPH. <i>Aj. 759 ;</i> αἰσχύνῃ, SOPH. <i>Tr. 597</i>, tomber dans le malheur, dans la honte ; <i>en b. part :</i> εἰς ἔρον τοῦ μαθεῖν, EUR. <i>I.T. 1172</i>, en venir à désirer passionnément apprendre ; εἰς ὕπνον, SOPH. <i>Ph. 826, etc. ;</i> ἐν ὕπνῳ, PD. <i>I. 4, 39 ;</i> ὕπνῳ, ESCHL. <i>Eum. 68</i>, tomber dans le sommeil ; <i>en parl. d’événements fortuits : en parl. d’affaires de pays :</i> εἰς τὴν τῶν Ῥωμαίων ἐξουσίαν, POL. <i>3, 4, 12</i>, tomber au pouvoir des Romains ; <i>avec une prép. marquant le lieu d’où l’on tombe :</i> π. ἐκ θυμοῦ τινι, IL. <i>23, 595</i>, tomber hors du cœur de qqn, <i>càd</i>. perdre sa faveur et son affection ; π. ἔξω κακῶν, AR. <i>Ran. 968</i>, échapper au mal ; <i>avec un gén. :</i> π. φρενῶν, EUR. <i>Hipp. 390</i>, perdre la raison ;<br><b>   V</b> <i>p. anal. :</i><br><b>      1</b> <i>en parl. du vent,</i> tomber, <i>càd</i>. s’apaiser, cesser, faiblir, OD. <i>19, 202</i>, DC. <i>39, 32 ;</i><br><b>      2</b> <i>en parl. des dés :</i> ἀεὶ εὖ πίπτουσιν οἱ Διὸς κύϐοι, SOPH. <i>Tr. 763</i>, les dés de Zeus tombent toujours bien ; <i>cf</i>. ANTH. <i>7, 427, etc. ; de même :</i> ὁ παρά τινα πίπτων κλῆρος, <i>ou</i> τινὶ πίπτων, PLAT. <i>Rsp. 617</i> e, <i>619</i> e, le sort qui échoit à qqn ; τὰ πεπτωκότα, ce qui est tombé, le dé, <i>d’où fig</i>. ce qui échoit comme lot à qqn, sort, destinée, événement, PLAT. <i>Rsp. 604</i> c ; EUR. <i>Hipp. 718 ; p. suite, en gén</i>. échoir, arriver inopinément, se produire : πολλὰ π. παρὰ γνώμαν, PD. <i>O. 12, 14</i>, beaucoup de choses arrivent contre toute attente ; εὖ, καλῶς πίπτειν, EUR. <i>El. 1101, etc</i>. avoir une heureuse issue, se terminer bien, réussir ; ᾗ πεσέεται ἡ μάχη, HDT. <i>7, 163</i>, comment la bataille tournera, se terminera ; τύχαι καὶ ξυμφοραὶ παντοῖαι πίπτουσαι παντοίως, PLAT. <i>Leg. 709</i> a, événements et accidents de toute sorte qui se produisent de façons diverses ;<br><b>      3</b> <i>en parl. d’argent qui échoit à qqn, d’échéances, de revenus :</i> ἑκατὸν καὶ εἴκοσι τάλαντα πρόσοδος πίπτει τῷ δήμῳ, POL. <i>31, 7, 7</i>, le peuple a un revenu de cent vingt talents ; τὸ πεσὸν ἀπὸ τῆς τιμῆς ἀργύριον, DH. <i>20, 9</i>, l’argent provenant du prix de vente ;<br><b>      4</b> <i>en parl. d’événements qui tombent à une époque déterminée :</i> κατ' Ὀλυμπιάδα, POL. <i>1, 5, 1</i>, dans une Olympiade, <i>cf</i>. POL. <i>4, 14, 9 ;</i><br><b>      5</b> tomber dans, <i>càd</i>. se rattacher à, appartenir à : αἱ ἀρχαὶ π. εἰς γένη ταῦτα, ARSTT. <i>Metaph. 3, 2</i>, les principes rentrent dans <i>ou</i> appartiennent à ces catégories ; οὐδ' ὑπὸ λόγον π. ἡ ἀδικία, POL. <i>4, 13, 11</i>, l’injustice n’entre pas même en considération, en ligne de compte ; οἱ χρόνοι οἱ πίπτοντες ὑπὸ τὴν ἡμετέραν ἱστορίαν, POL. <i>4, 2, 2</i>, les périodes de temps qui tombent dans le domaine de notre récit, de nos investigations.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. sbj. 3 sg. épq</i>. πίπτῃσι, PLAT. COM. <i>2-2, 665 Mein. Fut. ion</i>. πεσέομαι, HDT. <i>7, 168 ; 3 pl</i>. πεσέονται, IL. <i>11, 824 ; d’où inf</i>. πεσέεσθαι, IL. <i>9, 235 ; fut. poét</i>. πεσσέομαι, SIB. <i>10, 244 ; fut. réc</i>. πέσομαι, SIB. <i>3, 83, etc. ; f. poét</i>. πέσσομαι, SIB. <i>12, 239. Ao.1</i> ἔπεσα, ORPH. <i>Arg. 523 ;</i> SPT. <i>Judith 12, 6. Ao.2, 3 sg. épq</i>. πέσε, IL. <i>12, 459 ;</i> πέσεν, IL. <i>14, 418 ; 21, 385 ; sbj. 3 sg</i>. πέσῃσι, IL. <i>15, 624 ; inf. épq</i>. πεσέειν, IL. <i>6, 307 ; ao. éol. et dor</i>. ἔπετον, ALC. <i>60 ; part. masc. pl. dat</i>. πετόντεσσιν (<i>p</i>. πεσοῦσι) PYTHAG. <i>5, 50 Bgk ; fém. pl</i>. πετοῖσαι (<i>p</i>. πεσοῦσαι), PD. <i>O. 7, 69. Pf. réc</i>. πέπτηκα, ANTH. <i>7, 427 ; part. épq</i>. πεπτηώς, OD. <i>14, 354 ;</i> ANTH. <i>7, 24 ; gén</i>. -ηῶτος, A. RH. <i>3, 321, et</i> -ηότος, A. RH. <i>4, 1298 ;</i> HPC. <i>8, 146 ; fém</i>. -ηυῖα, A. RH. <i>2, 535 ; et</i> πεπτεώς, <i>d’où acc. pl</i>. πεπτεῶτας, <i>trisyll. par syniz</i>. OD. <i>22, 384 ; neutre</i> πεπτεῶτα, <i>trisyll. par syniz</i>. IL. <i>21, 503 ; att</i>. πεπτώς, ῶτος, SOPH. <i>Aj. 828, Ant. 697. Pl.q.pf. 3 sg. ion</i>. ἐπεπτώκεε, HDT. <i>9, 62. Pass. ao. part</i>. πτωθείς, ANTH. <i>1, 109</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *petH-, voler, tomber ; <i>cf</i>. πέτομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πιπτω - πίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n90 fois dans 85 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (7)</li>\n<li>Luc (19)</li>\n<li>Jean (3)</li>\n<li>Actes (9)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (3)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (23)</li>\n</ul>\n</td></tr>\n</table>","G4099":"<h1>Pisidia</h1>\n<p>Strong n° 4099 <i>Prononciation [pis-id-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pisidie (Angl. Pisidia) = « bitume, enduit de poix »\n<ol><li>région d'Asie Mineure bordée par la Pamphylie, et la Mer Pamphylienne, la Phrygie, et la Lycaonie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πισιδία, ας (ἡ)</b> <span>[ῐῐδ]</span> Pisidie, <i>contrée d’Asie Mineure,</i> EL. <i>N.A. 16, 7, etc</i>.<br><span><b>Étym</b>. Πισίδαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πισιδια - Πισιδία</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>"};
